/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20120123-6","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"区民委員会","time":"午後０時５９分～午後３時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山元委員","kind":"質問・要望","question":"今、課長のほうからご説明いただきました。１つは、先ほど選定方式で公募型ということで４社の申し込みがあったということで、実際、具体的に４社というのはどういうところが申し込みがあったのかというのを教えていただきたいということと。","respondent":"武内地域活動課長","answer":"東京ケータリングですと、これだけではなくてさまざまな観光資源的な釣り舟を出すとか、ゴルフ場の連携だとか、そんなようなアイデアが出されておりますので、その辺をトータルしまして今回、東京ケータリングという会社に決定させていただきました。","voiceIndex":5,"id":"exchange-001"},{"speaker":"山元委員","kind":"質問・要望","question":"もう一つ気になっているのは、放射線のことでちょっと心配しております。特に光林荘は栃木県ということで、今回、調べていらっしゃるかと思うんですが、移動教室というか、そういう学校で使うこともあるかと思うんですが、その辺は今後どのように区としては、対応されるのか。その辺もちょっと教えていただきたいと思うんですけど。","respondent":"武内地域活動課長","answer":"委員言われるとおり、今後も品川区の学校につきましては、光林荘を利用した移動教室、林間学校をそのまま引き続き従来と変わらない方式で利用する予定です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"山元委員","kind":"質問","question":"そうすると、定期的に例えばそういう移動教室が始まる前のある程度何カ月前とかという、何かそういう定期的にはかることというのは予定されているんでしょうか。","respondent":"武内地域活動課長","answer":"私も４月以降は光林荘の所管というのは、地域活動課が財産管理的なものはやっていくわけなんですけれども、学校の林間学校の執務については教育委員会のほうで責任を持って、その辺のことは検討しているということで聞いておりますので、この場で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"３の新しいこの８施設なんですけれども、区として一般料金と優待料金の差を補助するというのでいいんでしょうか。","respondent":"武内地域活動課長","answer":"こちらの施設については、品川区民については東京ケータリングの特別の会員という視点から、若干金額的なものを企業努力の中で進めていただいている額でございまして、区のほうはこの辺の補助的なものは一切考えておりません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"藤原委員","kind":"意見","question":"そうすると、丸得というか、この東京ケータリングを頼んだ結果、こういう形でできたということで、区の予算が使われないということですよね。品川荘、光林荘なんですけれども、年間で大体延べ人数でどのぐらい来るか、予想はしていますか。","respondent":"武内地域活動課長","answer":"それと、区民利用が２４年度、どの程度ということにつきましては、今後予算審議、３月にありますけれども、予算計上的なものは１万２,５００人ぐらいを財政のほうと調整して。","voiceIndex":13,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"そうすると、今までのシステムと、こういうふうに変えて、結局予算ベースで言うと、どのぐらいマイナスになっているんでしょうか。そのところで結局年間何千万円もかかっていたわけですよね。だから、そこの金額とあと、今度はこういう形で品川荘にしろ光林荘にしろ変えたわけですが、それとは別ですけれども、今までのシステムを変えたわけですから、お金的にはどのぐらいマイナスになったか教えてください。","respondent":"武内地域活動課長","answer":"これはあくまでも、補助制度を使いますので、補助金が５,２００万円ほどという金額の中での予測ですけれども、一応そんなようなことで、経済性、効率性を考えますと、かなり圧縮できている部分があるのかなというふうには考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"新しい料金なんですけれども、今まで、例えば品川荘でいくと、５人で部屋を借りた場合、１万円で１人当たり２,０００円ですね。それに食事代が２,５２０円で４,５２０円が、今度いくらになるのかなというところで、平日で見ると５,９７５円で、特に上がったわけでもない。その辺と、あとこの料金が入ったときの予算計上というのがどうなるのか。それを教えてください。","respondent":"武内地域活動課長","answer":"その場合については、その黒字になった金額の５割を区のほうに歳入としていただくという契約で考えております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"それと、補助金を出しているところで、料金のところですね。１泊大人４,０００円の補助金があるんですけれども、それに対して高齢者や障害者だと補助金がさらに１,０００円上がりますけど、この方たちが例えば２人で１室借りる場合でも、やはりこの２,１００円というのは割増になってきちゃうんですか。","respondent":"武内地域活動課長","answer":"委員言われるとおり、３人で利用したときの金額でありますので、それを２人でという場合については割増は通常どおりの割増をいただくということになります。","voiceIndex":19,"id":"exchange-008"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１室２名で利用した場合と１名で利用した場合の金額の増が示されていますが、例えば団体で行かれる場合に団体割引とかというのは、そういった割引についてどのような会社としてのあれがあるのか。その辺の割引とそういったサービスについて、もしわかれば教えてください。そういった部分を把握していただきたいと思うんですが、その点、どのように考えているのか。３点あわせてお願いします。","respondent":"武内地域活動課長","answer":"今回の資料ではお知らせしていませんけれども、団体割引ということで１５名以上で利用する場合については、利用料金の５％引きというようなことを東京ケータリングがやる予定で、それで、団体の呼び込みをはかりたいということで。","voiceIndex":21,"id":"exchange-009"},{"speaker":"石田副委員長","kind":"質問・要望","question":"これは要望で終わります。光林荘なんですけれども、これは確かに１年前に学校行事が決まっていて、そこでまず予定をはめて６カ月前から区民の皆さんの受付がスタートする。再度ご答弁をお願いします。","respondent":"武内地域活動課長","answer":"そのようなことで、状況に応じて対応させていただいてというようなことで、従来と同じような形で、やはり区民に利用を受け付けている場合については、それはもういついつ利用できなくなりますよということではなくて。","voiceIndex":23,"id":"exchange-010"}]},{"id":"topic-02","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"教えてもらいたいんですけれども、京浜工業地帯発祥の地大崎となっていますけれども、これはどうしてかというのをお伺いしたいのと。ですから、その差し上げて製品等、また開発をしていただいた投資対効果というのはものすごく大事だと思うんですよね。","respondent":"福島ものづくり・経営支援課長","answer":"ここには品川区の企業以外にも呼びかけますので、ほかの全都ですとか、あるいは全国に向けて発信できればというふうに思ってあります。それをもとにさらにその企業が発展し、また、品川区自体も品川区の産業が発展し続ければというふうに考えているところです。","voiceIndex":38,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"この名前が違うかもしれませんけれども、この歴史というのは長いですよね、このフェア。前の産業振興課のときぐらいから、もうやられていると思うんですけれども、いわゆる助成している、助成の施策というのも何年かやっているじゃないですか。実際にこういうフェアで果実というか、出てきている例というのは実際問題あるんでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"そういう事例もありますので、こちら、参加する企業については十分役立っているのではないかというふうに思ってあります。","voiceIndex":40,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"だけれども、産業振興課という課を２つに分けた時点で、やはり区長の工業に対する思いというのがあらわれているんだなという思いがすごくありましたので、せっかくこう２つの課に分かれてやられているわけですから、商業、工業と分けるわけじゃありませんけれども、工業に対して行政がどういうふうにかかわっていくか、工業を伸ばしていくためにという思いがすごくあるんですけれども、最後にその辺について。","respondent":"福島ものづくり・経営支援課長","answer":"そういう形で発展させておりますので、今後もそういった企画を強め、さらなるものづくり事業に対する支援等を行っていきたいというふうに考えてあります。","voiceIndex":42,"id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2626#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":18646,"voices":53}},{"id":"h24-20120123-7","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"厚生委員会","time":"午後１時００分～午後３時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"杜松小学校跡高齢者福祉施設等の運営事業者の選定","agenda":"杜松小学校跡高齢者福祉施設等の運営事業者の選定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"特別養護老人ホームのところで、全室個室の新型なのかを教えてください。それから、(7)の緊急対応室というのは、常に開けておくのか。緊急対応は、結構利用される方が多いと聞いているんですけれども、需要はどれぐらいあるのかというのを、ちょっとお聞きしたいと思います。","respondent":"原高齢者福祉課長","answer":"緊急対応室ですけれども、さまざまな形で、緊急対応室というのは考えられるところです。一つは、介護をしている方が急に病気で介護ができなくなってしまった、あるいは、入院等々があります。あるいは、虐待ということもあろうかと思います。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"意見","question":"２ページのところで、ちょっと細かいことになってしまうんですが、(3)のポケットパーク「さんさん」というのが書いてないなということ。それから、(5)のリサーチを行ったということですけれども、どのように、どんなことを聞いて行ってきたのか、お聞かせください。","respondent":"原高齢者福祉課長","answer":"そういうリサーチの中で、在宅介護支援センターを品川介護福祉専門学校の５階から移したほうがいいというところは、やはり、地域の方が何かで来たときに、１階で相談ができるんだということで立ち寄れるといったところも、そのリサーチの中での結果だと理解したところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"この事業者を選定していくにあたって、その運営事業者が指定管理者候補にもなってくるということなんですけれども、今後、品川区としての運営事業者の選定の考え方というのを、お聞きしたいんです。区内の法人ではなくて、結構、今、外から入れてきているなと思うんですけれども、今後は、どのような考え方で進められるのか、お聞かせください。","respondent":"原高齢者福祉課長","answer":"そういった意味では、施設の規模、内容等々によって、そこの部分については、今、申し上げた考え方に基づきながら進めていくです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"こういうところに対しては、どんな提案だったのかというところも、あわせてちょっとお聞かせいただきたいと思います。若竹大寿会は、こういうふうにいろいろとお示しいただいているのでわかるんですけれども、ほかの２法人の提案が、それと比べてどうだったのかというあたりを、ちょっと教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"具体的に、２番とも絡むところですけれども、認知症ケアの提案の中でも、若年性の関係でのピック病、あるいは、そういった部分の対応、これは新生寿会のほうでも、ほかの施設等でも、かなりそこの部分については力を入れておりまして、そういった提案も、今回いただいたところで。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここの選定理由の(2)の3)のところで、医療と連携しターミナルまでを支える機能と書かれているんですけれども、医療と連携するというのは、どういうところと連携をしていくのかということと、それから、ターミナルまでを支える機能ということなので、特別養護老人ホームにしても、グループホームにしても、小規模多機能型居宅介護にしても、ターミナルまで。","respondent":"原高齢者福祉課長","answer":"例えば、看護師による介護福祉士との連携の中での研修体制の確立、こういったことを、既に実施してきておりまして、より在宅に近いという、こういった施設の中で、ターミナルというのはこれからの課題ということを、この法人は認識しております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"もう一つ、３の(2)に、法定基準以上の職員配置等と書かれているんですけれども、この公募要項の中でも、職員配置や職員についても、提案の中身として、さまざま詳しく、例えば、常勤、非常勤の割合とか、経験、未経験者の比率とか、そういうところまで提案をしてくださいということで書かれているんですけれども、ここの法定基準以上の職員配置というのは、どれぐらいを考えているのかということ。","respondent":"原高齢者福祉課長","answer":"そういう中で、施設、職員みずからがそういった認識の中で対応するという中で、こういった研修が大変に重要になっておりまして、ここの法人の中では、そういったものをきちっとカリキュラムとして実践し、また、職員の評価というところ、あるいは人事制度まで。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"離職率とかについては、この法人がどうなっているのかということも、教えていただきたいと思います。それからもう一つは、この提案の施設を改修して整備するにあたっての、全体の事業費が、提案の中でも出てきているのではないかと思うんですけれども、おおよそどれぐらいかかるのかということも、わかったら、教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"経営の部分ですけれども、一つは、この施設、工夫の中で、ショートステイを１０床です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ、教えてください。さっきからずっと、施設を見てきた、見てきたと言うんだけど、新生寿会は、岡山県まで行ったという理解でいいのか。","respondent":"原高齢者福祉課長","answer":"見てきたというのを、ちょっと強調し過ぎて大変恐縮です。麹町の小規模特別養護老人ホーム、それから、小規模多機能型居宅介護、グループホーム、それから地域の交流の部分ということで、見てきたです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"これは、１日で見てきて、多分そこに行ったんだろうと思ったんですけれども、あまり見てきた、見てきたというと、新生寿会は、本拠地は多分岡山県だし、もちろん麹町でも賄えるというのは、小山倶楽部もよくやってくれているからという意味があったんでしょうけれども、平で見るなら、こういうときに、横浜市ぐらいだから行けるとか、岡山県が本拠地だったら、岡山県まで行こうとか、それはぜひ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"１点だけ、さっきの選定理由で、(2)の3)の話が出ました。さっき、看護師と介護福祉士との連携という説明で終わっているんですが、実際に現在、横浜市でやっておられるわけですね。その具体的なお話と、この事業者が品川区にきて、具体的に品川区でどういうふうにされていこうとしているのか、イメージとして、ちょっと押さえていただきたいと思うんです。","respondent":"原高齢者福祉課長","answer":"そういう中で、医療対応看取りというものを、今言ったようなモデル事業を通じて、現場がきちっと研修をし、それから、仕組みの実践を、この間やってきたです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"若林委員","kind":"意見","question":"すみません、ちょっとまだイメージがわかないので、そうすると、この法人が診療所を持っておられますけれども、こういうところと、いわゆる法人の中の介護の枠の中で、横浜市ではやっていらして、その外の、例えば医師会とか、そういうところとのモデル事業の内容だけ、ちょっと具体的に。","respondent":"原高齢者福祉課長","answer":"これが、若竹大寿会の考え方ですけれども、こういった考え方をもとに、区としても、ご家族の意向、あるいは、どういう時期にどうするのがいいのかというところを、若竹大寿会が持っているノウハウを聞きながら、地域の医師会と連携しながら対応していくということで。","voiceIndex":24,"id":"exchange-011"}]},{"id":"topic-02","title":"品川区立大井林町高齢者住宅の入居者募集","agenda":"品川区立大井林町高齢者住宅の入居者募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"応募はどれぐらいきて、どれぐらいの方が落選されたのか、教えてください。","respondent":"間部高齢者いきがい課長","answer":"このうち、以前、ご説明させていただいたように、今回、７０戸のうち６４戸については、おふろがついているところ、１階の６戸についてはおふろがないということで、この１階の６戸のおふろのないところにつきましては。","voiceIndex":31,"id":"exchange-012"}]},{"id":"topic-03","title":"品川区立心身障害者福祉会館機能の再編","agenda":"品川区立心身障害者福祉会館機能の再編","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"１面の１番の表のところで、サービス等利用計画案に基づく支給決定とあるんですけれども、これは具体的にはどのようなことなのでしょうか。","respondent":"永尾障害者福祉課長","answer":"そうすると、その後、モニタリングを行うというのが、今度の新しい法律の部分になります。そのモニタリングについても、その状態に応じて、６カ月、１年、これは、これからガイドラインが出る予定ですので、その結果を見て、またご報告をしたいと考えております。","voiceIndex":38,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"全然わからないので、素直に教えていただきたいんですが、ここで言う意味の、障害者自立支援法で法律改正が行われたと。これで、障害者の方々にとって、よくなる部分を教えていただきたい。それから、例えば、区にとっての負担は増えるのか、そういう意味では、出すお金が増えるのか。利用者のメリットがどこにあるのか、教えてください。","respondent":"永尾障害者福祉課長","answer":"一方、品川区のほうで見れば、これが個別給付になるということになりますと、国が２分１、東京都が４分の１、区が４分の１となり、この区の４の１の部分が出てくるという意味で、負担が増えるということになります。","voiceIndex":40,"id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それが今度は、介護保険のケアプランのような形で、皆さんにそういう計画がつくられるというイメージで考えていいのか。その対象というのは、知的・身体・精神すべてが含まれていくのかということを教えていただきたいと思います。そして、その対象者というのは、おおよそ何人ぐらいになるというあたりも、ちょっと教えていただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"この次の質問の会館の職員体制とか、そういう従事する方の状況を見ましても、それをいっぺんにやるというのは非常に難しいということで、今現在、国のほうで示しているところでは、３年の経過措置の中で、徐々に拡大してくださいというようなことが出ております。","voiceIndex":42,"id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、そういう点では、今度、４月１日からこういう形でやるというところに対しても、国の本気度というか、そこら辺が出てくるのかなという思いがしているんです。ぜひ、そういう方向にしていただきたい。それから、じゃあ品川区としては、もうほんとうに間近に迫っている段階で、４月１日からはどの程度というところを、考えられているところをお聞かせいただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"このやり方についても、実践を踏まないとわからない部分もありますので、しばらくは、過渡的な部分がありますので、そういう実践を増やして、職員のケアマネジメントの技術を磨いていくというほうに力を入れていきたいと考えています。","voiceIndex":44,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"そこら辺、いわゆるこういう制度が変わるときって、いつも必ず、要するに、利用者によく説明が行き届かなかったり、説明されても、なかなか理解ができなかったり、こっちからあっちへとか、ほんとうは私はこうだったんだけれども、こうされちゃったとかいうことが必ずあるので、そこら辺の現状フォロー体制とか、ちょっときめ細かく、これはやるということで、当然。","respondent":"永尾障害者福祉課長","answer":"３月中に利用契約を結んで、４月から開始できれば、というふうに考えております。この２月から３月の動きについても、心身障害者福祉会館とげんき品川の職員と両方で、この部分の説明等を行っていきたいと考えております。","voiceIndex":46,"id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今、旗の台の心身障害者福祉会館で行っている、就労移行支援の対象の方は何人ぐらいいらっしゃるんでしょうか。","respondent":"永尾障害者福祉課長","answer":"今現在、２２名いらっしゃいます。","voiceIndex":48,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"具体的に、就労移行支援というのがどういう中身なのかということと、その２２名の方は、旗の台から大崎というと、地理的にもちょっと変わると思うんですけれども、そういうところでは、２２名の方は、区内のどこら辺の方が旗の台まで通われてきているのか、そういう地理的なことで大変になるということに対しては、ちょっとどうなのかということも、教えていただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"今、通われている方の平均年齢から申し上げますと、２６歳です。","voiceIndex":50,"id":"exchange-019"}]},{"id":"topic-04","title":"障害者自立支援法の「同行援護」","agenda":"障害者自立支援法の「同行援護」","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"実質、５６時間だったのが５０時間ちょっとに減ったということになるのか、お聞かせください。","respondent":"永尾障害者福祉課長","answer":"実はこの単位が、時間ごとに決められておりまして、まず１時間の場合は、こちらに書いてあるとおり１９７単位、２時間の場合は３４６単位、３時間の場合は４８６単位、４時間の場合は６２６単位というふうに決まっております。いずれも身体介護なしで出した単位数です。","voiceIndex":57,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この同行援護というのは、ガイドヘルパーって、視覚の方と知的の方がいらっしゃると思うんですけれども、視覚障害の方だけが対象ということで、知的障害の方は、今までどおり、地域生活支援事業のほうでいくということなんでしょうか。そのことが一つ。それから、現在、利用している方は何人ぐらいいらっしゃるのかについても、お聞かせいただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"そのほかにも、移動支援を実施している事業者は区内にありますので、そちらのほうに移行していくような形をとっていきたいと考えています。それから、利用者数ですけれども、現在、５７名の登録になっております。","voiceIndex":59,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"サービス利用計画を作成して、何時間というので決めていくと思うんですけれども、これはどこでつくられるのかということ。それから、利用者負担のところは、経費の１割が原則ということになっていますけれども、住民税非課税の方は無料で受けられるのかと思うんですけれども、そこら辺のところを、利用料のことについても、ちょっとお聞かせください。","respondent":"永尾障害者福祉課長","answer":"サービス利用計画ですけれども、こちらにつきましては、障害者生活支援センターおよび品川区のケースワーカー両方で連携しながらつくっていきます。住民税非課税の方につきましては、無料です。","voiceIndex":61,"id":"exchange-022"}]},{"id":"topic-05","title":"平成２４、２５年度東京都後期高齢者医療保険料率案","agenda":"平成２４、２５年度東京都後期高齢者医療保険料率案","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ざっと数字だけをお聞きしたいので、まとめて言います。収納率と滞納者数と、短期証の方はどれぐらいいらっしゃるのかということ。国民健康保険の場合は、滞納理由なんかも出されているんですけれども、今回はあるのか、あればお聞かせいただきたいと思います。","respondent":"榎本高齢者医療担当課長","answer":"一つ目の質問、収納率ですが、昨年度につきましては９８.５８％です。本年度につきましては、現段階におきまして、若干０.７６％増えております。滞納者数につきましては、平成２３年８月末現在ですが、９９４人となっております。","voiceIndex":68,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"もう一つあったんですけれども、資料の一番最後のページの表の一番上の旧ただし書き所得が０円で、年金収入換算額が０～１５３万円という方が、東京都で言うと５５.２％いるということなんですけれども、区で見ると、どれぐらいかというのがわかれば、教えてください。","respondent":"榎本高齢者医療担当課長","answer":"品川区での旧ただし書き所得の割合ですが、５３.５５％で、人数としては１万８,２３１人です。","voiceIndex":70,"id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区の後期高齢者の人数を、まず教えていただきたいと思います。それから、旧ただし書き所得で０円という方は５３.５５％ということですが、一番最高の６４５万円以上の方は何人ぐらいいらっしゃるのか、そのこともちょっと教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ちょっとお聞きしたいのが、区市町村による特別対策の継続というのは、1)、2)、3)、4)の葬祭事業から保険料未収入補てん分までのところは、全国でも東京都広域連合のみということで書かれていて、東京都はこういう対策がとられているということだと思うんですけれども、その隣の財政安定化基金の活用というところは、全国同じようにされているということで考えていいんでしょうか。","respondent":"榎本高齢者医療担当課長","answer":"今回、大きく影響いたしました積増分につきましては、広域連合が、１１月から１２月にかけまして、東京都と何度か協議を重ねまして、広域連合のほうから強く要望を出しておりました。","voiceIndex":75,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この東京都独自の1)から4)のことに加えて、財政安定化基金というのも、それぞれ違うということで、財政安定化基金の積増分が、全国の中では、どういう状況になっているのかというあたりが、わかったら教えていただきたいことが１点です。","respondent":"榎本高齢者医療担当課長","answer":"広域連合、もしくは担当課長会等でも、もう少しなだらかな形にならないかということで、こちらもお話をすることがあります。広域連合としても、段階的な所得の軽減の変化について、もう少しなだらかな形にできないかということで、国のほうに要望しています。","voiceIndex":77,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどのところでは、軽減率が８.５割から一気に２割となってしまうというところでは、国民健康保険なんかにしても、５割軽減とかいうのもありますし、ここの軽減のところは、ぜひ、これからも主張していただいて、中間の方が一気にこういうふうに上がる仕組みを改善していただくように、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"意見","question":"すみません、今、鈴木ひろ子副委員長からも話があって、広域連合議会の部分もあるんだけれども、一般財源を投入したと、それで、東京都の広域連合は抑制策をしていると。私は、こういう書き方は一番嫌いで、本則はこれですよ、抑制策をとっているから、これだけ安くしているんですよという、こういう見せ方はあまり好きじゃないんです。じゃあ、品川区はどういうスタンスでいるのかというところを、聞きたい。","respondent":"榎本高齢者医療担当課長","answer":"そういった意味で、世代間の公平性等を考えまして、若い方々からの税金を投入するという形になりますので、そういった意味では、ご理解をいただきながら、世代間の公平性ということで、保険制度を実現させていくしか、現状ではないと考えています。","voiceIndex":80,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、そういう説明をするのはわかるんです、世代間の公平性。それはいただくならいただく。わかるけれども、それであるならば、こういう本則と抑制策なんていうことを、ソフトランディングするようなことをよくやるけれども、それは書くべきじゃない。そのうちいつか、こっちの本則に戻りますよみたいな、いつになるかわからないわけじゃないですか、これは。","respondent":"木下健康福祉事業部長","answer":"そうは言っても、特に後期高齢者の制度につきましては、保険制度ではありますけれども、同時に年齢の高い方で、医療費も非常にかかるということがありますから、保険原則を踏まえつつ、つまりこれは本則ということですが、本則を明示しつつ、本来でしたら、保険料で対応すべき。","voiceIndex":82,"id":"exchange-030"}]},{"id":"topic-06","title":"「放射能に関する講演会」の開催","agenda":"「放射能に関する講演会」の開催","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"逆に、あまり怖がると、そんな気にしていたら生きていられないじゃないかみたいなことが、今度は逆にあって、それがよくわからないので、そこら辺のフォローは、ある程度とって、もし、こういうことをやるんだったら、そういう両極端の人に２人きてもらうとか、そういうことができるのかどうかわからないけれども、そこら辺のフォローをしておかないと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":89,"id":"exchange-031"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ホームページを見ればいいと思うんですけれども、これは、普通に参加はできるんですか。それから、料金とか、定員とか、どうなっているんですか。","respondent":"工藤品川区保健所生活衛生課長","answer":"広報等で周知していますけれども、チラシができております。こちらのほうを、今日、この委員会終了後にお配りしたいと考えていますけれども、料金無料、先着４００名ということで周知しています。","voiceIndex":90,"id":"exchange-032"},{"speaker":"若林委員","kind":"確認","question":"放射能の講演会の開催、大変にありがとうあります。それから、当日は、フロアからの質疑もやられると思うんですが、そのときに、当然、しかるべき区の方もそこに加わって、なるべくフロアの方の質問に、しかるべき担当の方が正確にお答えしていただくことは最低限必要かなと思いますので、その態勢を、ちょっと確認します。","respondent":"工藤品川区保健所生活衛生課長","answer":"当然、いらっしゃる方は区民ですので、区でやっている測定についての質問という部分も想定されるかと思いますので、そういった部分では、しっかり対応できるように態勢を整えたいと考えています。","voiceIndex":92,"id":"exchange-033"},{"speaker":"若林委員","kind":"質問・要望","question":"正しい知識って、今、どれが正しいのかというのを含めて、いろいろな数値が出てきて、私もどれが正しいとか、安易に言えることではないのですが、少なくとも、区民の方々は関心を持って、また不安を持っていらっしゃるわけですので、そこら辺の、いわゆる質疑などでの対応、言葉づかいというのは、十分に苦しんでいらっしゃる、不安でいらっしゃる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-034"},{"speaker":"向委員","kind":"質問","question":"数点、お伺いしたいんですが、まずこの講演会開催は、私もかなり長い間待っておりました。一つ、まずお尋ねするとすれば、もう少し早めにしていただきたかったかなという気持もあるんですが、今この時期に開催となった理由。なぜ週末にセッティングしなかったのかとか、そこのあたりをちょっと疑問に思ったので、簡単にご説明いただければと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"直接、職員がいろいろな自治体に行って、講演内容を聞いた中で、この講師がわかりやすく、かみ砕いて説明しているという部分で、ある部分で確かなものがございましたので、お願いするのであれば、この先生にお願いしようということで決めておりました。","voiceIndex":95,"id":"exchange-035"},{"speaker":"向委員","kind":"質問・要望","question":"今回、講師の先生も、念には念を入れてご検討いただいた先生ということで、私も、スケジュールが合えば、ぜひ伺いたいと思うんですが、そのほか、栄養士の先生とか、いろいろ区民の目線で、いろいろな専門家の立場からの話も聞いてみたいという気もしますので、ぜひ、今後ともご検討のほうをよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3314#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":38875,"voices":103}},{"id":"h24-20120123-8","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"建設委員会","time":"午後１時００分～午後４時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を行います。 初めに、(1)「都市計画公園・緑地の整備方針」（改定）","agenda":"を行います。 初めに、(1)「都市計画公園・緑地の整備方針」（改定）","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"今回改定ということで、改めて位置づけについて伺いたいんですけれども、冒頭の説明にあったように防災対策、震災対策の面を位置づけ直したと、重点化したということですけれども、これまでとこれからと、どう評価されたのか、その点を補足していただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"そのことによって区民にとっては、結局は広い公園を使えるという形になりますので、そういったような新たな仕組みについても考えて実施をしていきたいということを示しているものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚副委員長","kind":"質問","question":"地域を限定することなく区内全域に震災対策としての公園、緑地の確保に動き出すべきじゃないかと思うんですけども、その点はいかがお考えか伺います。とりわけ、詳しくは言いませんけど、火災危険度が高いとさまざまな主張で言われているわけですから、区内全域をしっかり見ていくことが必要だと思うんですけども、この点を伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"１１ページの大規模救出拠点等の考え方ですけれども、言葉のとおり救出するための予定ということで、先ほどお話の中にありました林試の森公園等については、広域避難場所というような位置づけにはなってありますけれども、樹木がいっぱいありますので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚副委員長","kind":"質問","question":"私が先ほど言ったのは、そのほかのところはどうなのかと。やらないというわけではなく、考えていくというお話がありましたけど、どう考えていくのか、そこを伺いたいと思っているんですね。都に対しても、補助金をしっかりつけなさいというのも主張していくべきではないかと思うんですけど、ほかのところはどんなことを考えているのか、やっていくべきだと思うんですけど、いかがでしょうか。","respondent":"藤田水とみどりの課長","answer":"１点目と２点目、お答えとしてちょっと一緒になってくる部分もあるのであわせてお答えしますけれども、防災の話をしたときに、一時避難場所にしたり、そのほかの活動ができる拠点にしても、公園だけでなく、学校であったりとか。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"しながわ環境大賞・みどりの顕彰および環境講演会","agenda":"しながわ環境大賞・みどりの顕彰および環境講演会","exchanges":[{"speaker":"井上委員","kind":"質問","question":"ちょっと概要なんですけど、これを始めてどんなふうに変わってきたのかというこの事業の評価と、あと選考委員のメンバーというのはどういう方たちがいるのか。これは自薦他薦の両方で出されているのか、その３点をお願いします。","respondent":"野呂瀬環境課長","answer":"都市環境事業部長が選考委員会の委員長ということで、そのほかに１０名委員がいまして、環境課長、水とみどりの課長、地域活動課長、商業・観光課長、ものづくり経営支援課長、青少年育成課長、保育課長、子育て支援課長、品川区清掃事務所長と教育委員会の指導課長。","voiceIndex":15,"id":"exchange-004"},{"speaker":"井上委員","kind":"意見","question":"平成１８年からの選考のほうで同じ団体が続いているのか、すそ野が広がるためには働きかけとか、広がっていくほうがいいというのも当然なんですが、そういった意味で何度も同じところなのか、それとも広がっていって、区民に認知されていくようになってほしいと思うんですけど、その辺の状況と行政としてこれに取り組んでいく何か目標とか取り組みはありますか。","respondent":"野呂瀬環境課長","answer":"ですけれども、ポイントとしては、昨年漏れたけれども、今年については、いわゆる継続して実施されているか、いろいろな観点から評価をしていますので、いずれにしましてもそういう活動を通じて自主的な活動はいろいろありますけれども。","voiceIndex":17,"id":"exchange-005"},{"speaker":"井上委員","kind":"意見","question":"３４団体ということで応募があったんですけれども、新規なのか、毎年応募されて、１回大賞になったら次はないとか、そういうような要綱で何か定めとか、経験者じゃない人たちというふうにどんどん広げて取り組んでいますか。","respondent":"野呂瀬環境課長","answer":"数年前に受賞した団体については継続してやっていただくということもあるんですけれども、やはり新規で、例えば昨年賞に漏れて、また今年も継続してやっている方、そういういろいろな観点から選考委員会において、ポイント制で選考いたしますので、選考していくです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問","question":"その基準と結局同じなのか、それとも大きく広がっているのか。同じだけど、植えた木に工夫があるのか、何かどういうところを基準に選んでいるのか、１点伺いたいなと思います。どうも何か釈然としないのは、区も参加して、そのビルを区がよくできましたというのは、どう考えたらいいのかなというのは、その点は率直に疑問があったんですけども、どうお考えなのか伺いたい。","respondent":"藤田水とみどりの課長、野呂瀬環境課長","answer":"ただそういう中で、その敷地の中でもいろんな工夫をする、そういったものについては当然評価をしていきたいということで考えてありますので、今回緑化大賞、それから緑化賞というようなことで四つの事業所。２点目のお尋ねですけども、例えば日立ソリューションズ、会社ですけれども、実際私が今お示ししたところで、ちょっと省略して説明しましたけど、実際は社員の皆様が勤務時間外に清掃活動を長年にわたって行っているだとか。","voiceIndex":21,"id":"exchange-007"}]},{"id":"topic-03","title":"地域が主導するＥＶカーシェアリング事業状況","agenda":"地域が主導するＥＶカーシェアリング事業状況","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"新しい技術を進めていくといいますか、支援していく事業だと思うんですけれども、冒頭に「低炭素社会の実現を目指し……地域の低炭素化の推進」とありますけども、そもそもどういう理念としてとらえているのか、何を目標とされているのか、そこを伺いたいなと思うんですね。つまり、品川区から排出されるＣＯ２の総量削減、それをやっぱり目標と掲げているのか伺いたいと思います。これは考え方です。","respondent":"野呂瀬環境課長","answer":"２番目の災害時の対応なんですけれども、通常はこういうＥＶカーシェアリング事業を実施して、何か災害があるときには、例えば電気自動車ですと電源の確保というか、停電になりましても電気自動車の電源は使えるだとか。","voiceIndex":28,"id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"低炭素化社会の実現を目指すと、推進と、この理念とは何かと伺ったんですけれども、地域コミュニティが中心になって地域主導でやると、それが理念なんでしょうか。それと、その関係でもあるんだけども、例えばまずはＥＶカーシェアリングに必要な電力を太陽光発電とか自然エネルギーの活用で賄っていきたいと、そういう考え方があるのか、目指しているのか、そこを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-009"},{"speaker":"武内委員","kind":"質問","question":"だから、大崎エリアマネージメント、直接区とはあれなんだけども、今回区が計画しているわけですけども、今後どんなことを目指していこうとしているのかというのがもしわかれば教えてください。","respondent":"三宅都市開発課長","answer":"したがいまして、今回も地域のまちづくりの一環で、あくまでも大崎エリアを中心にした活動としてやっておりまして、同じカーシェアリングを全区的に展開するところまでは考えておりません。","voiceIndex":33,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"これからの区の関与、区の立場なんですけれども、当初、東京都の補助金を受託するに当たって、区がまず補助金をもらって、支給する相手としてエリアマネージメントと事業委託契約締結ということだというふうに理解をしているんですが、その後それについて、そうすると、事業委託契約というのは、１年の立ち上げ支援だけであるというふうになっていたと思うんですけれども、事業委託契約というのは。","respondent":"野呂瀬環境課長","answer":"今後につきましては、地域コミュニティをどういうふうな形で継続していくのか、それはまた別の検討課題で、先ほどの太陽光発電の今後の拡大も含めてですけれども、少なくともＥＶカーシェアリング事業につきましては、都からの補助金は今年度限りです。","voiceIndex":36,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"事業委託契約は、区とどういうふうな事業を、具体的に事業契約の何を、委託の締結をしたのかということと、エリアマネージメントのところで、「スマートシェア倶楽部・大崎」という事業主体が１個その中に発足したという関係でいいのでしょうかというようなことなんですが。","respondent":"野呂瀬環境課長、岩田都市環境事業部長","answer":"委託はしたんですけど、環境についての取り組み等につきましては、今後も区とは継続して取り組んでいっていただくです。プレミア会員は企業会員ですので、それぞれが特定の資金を捻出しながら、ここに書いてあります「スマートシェア倶楽部・大崎」という会、この中で自主運営を４月以降行う。","voiceIndex":38,"id":"exchange-012"},{"speaker":"井上委員","kind":"意見","question":"事業委託契約を締結というのが、この大崎周辺の社団法人、いろいろなことをやっている大崎エリアマネージメントというところとこれを結んだのは、補助金をそこにやりますよという契約の締結の項目というのはどういうものなのか。","respondent":"野呂瀬環境課長","answer":"大崎エリアマネージメントと契約書を締結したのは、地域主導のカーシェアリング事業支援等業務、この件名で協定書を結んだところです。","voiceIndex":41,"id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"先ほどの部長のお話の中で委託金の件、間接的な補助金というふうにおっしゃったんですが、あくまでも委託であって、間接補助金というのはちょっと表現が適当ではないと思うんですが、もう一度伺いたい。","respondent":"岩田都市環境事業部長","answer":"したがって、やむなく品川区が主体となって地元の組織である大崎エリアマネージメントに対して業務委託をするという形をとったです。わかりやすく一般的に言うと、いわゆる間接補助のような形での制度を活用したというふうに申し上げたものです。","voiceIndex":43,"id":"exchange-014"},{"speaker":"大沢委員","kind":"意見","question":"そうすると、やっぱり委託と補助となると、もろもろのお金、また区のかかわり方がちょっと違ってくると思うんですけれども、そこのところはどういうふうに理解をしたらいいのか。","respondent":"岩田都市環境事業部長","answer":"今申し上げましたように、現実には業務委託という契約です。したがって、品川区の業務をこの大崎エリアマネージメントが受託をして実施をしたという形になってあります。","voiceIndex":45,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、責任の所在というのは、大崎エリアマネージメントであって、品川区のほうは何かあっても一切責任を負わないというような形なんでしょうか。","respondent":"岩田都市環境事業部長","answer":"したがいまして、品川区が業務をエリアマネージメントに委託をしたですので、その業務内容に何らかの問題があった場合は、いわゆる受注者側の非があるのか、発注者側に非があるのかによって、その責任所在は分かれてきますけれども。","voiceIndex":47,"id":"exchange-016"}]},{"id":"topic-04","title":"区営住宅入居者募集","agenda":"区営住宅入居者募集","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今度空き住宅のみの募集ということで、１月、７月で、その違うときにあくところは、ちょっと非効率な気がするんですね。修繕にも時間がかかるということなんだけれども、なるべく早くして、早く解禁をするようにという、改善も必要かという課題もあると思うので、途中であいた分については、どういうふうに対応していくということをお考えでしょうか。","respondent":"柏原住宅担当課長","answer":"ただ、委員おっしゃるとおり、やっぱり何カ月間はあく期間が出てくると思いますので、この方式で何回かやって、そういったところをどういう形で解決できるかというのは、ちょっと新たな課題ということで引き続き検討していきたいというふうに考えてあります。","voiceIndex":54,"id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"そのときに、その方よりもっと大変な方がいるかもしれないというところで、公営住宅の入居というのを排除しなければいけない状況も出てくるのではないかと思うんですが、そういったところの対応の仕方というのは、公平にどういう案を持ってされているんでしょうか。","respondent":"柏原住宅担当課長","answer":"今委員おっしゃるとおり、かといって居住に困っている方たちもいらっしゃいますので、そういったところの不公平感がなるべくなくなるようにということでは、現在もちょっと検討を進めているですので、いろいろ試行錯誤しながらですが、今後進めていきたいです。","voiceIndex":56,"id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問","question":"今回募集の仕方が新しくなったのであれなんですけども、どれぐらいの応募の数を見込んでいらっしゃるのか、お考えを伺いたいと思います。それと、募集住宅がたったの４戸だと。つまり、今あいているのが４戸だということですけど、少ないなと思います。これはそもそも区営住宅が足りないことのあらわれだと私は思いますけれども、それが４戸で十分だと思っていらっしゃるのか、そこを伺いたいと思います。","respondent":"柏原住宅担当課長","answer":"いろんな理由で退去されるんですが、大体１５戸ぐらい年間で出ているというところがございましたので、ちょっとたまたま今回４戸で少なかったんですが、年２回の募集ということで、７戸から８戸ぐらいを年２回で回すような形でできればと思っておりまして。","voiceIndex":58,"id":"exchange-019"},{"speaker":"中塚副委員長","kind":"質問","question":"あくまで見込みですけども、２００人から３００人ぐらいの応募だろうと。今回たったの４戸だと。この間の経過を見ても、年１５戸ぐらいあくと、これで足りているという認識なのかを伺いたいんですね。私はとてもとても足りないと、区営住宅がそもそも足りないことが問題だと。しっかり増設に方針を掲げるべきだとずっと主張してきたわけですけども、改めてそこを伺います。","respondent":"柏原住宅担当課長","answer":"区内には都営住宅もありますし、それから国のほうの動きも民間の賃貸住宅、こういったところをストックがあるというところで大きく活用していこうですので、区営住宅だけでこれを論議するのではなくて、そういったところ全体で論議をしていくべきものだと考えていますので。","voiceIndex":60,"id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"最後にしますけども、だから４戸で十分だと考えているのか。これについてはしっかり伺いたいと思います。今のご説明の中で、区営住宅では対応できないと。大体区営住宅に申し込みされる方は一定高齢者の方が申し込むわけですけれども、古い築年数のたったアパートの退去を求められている。ちゃんと住宅に対する区の責任をしっかり果たしていくべきだと思いますが、いかがでしょうか。","respondent":"柏原住宅担当課長","answer":"区営住宅では対応できないというふうに言っているのではなくて、区営住宅だけで議論すべきものではないというふうに考えているものです。","voiceIndex":62,"id":"exchange-021"}]},{"id":"topic-05","title":"平成２４年２月都営住宅入居者募集","agenda":"平成２４年２月都営住宅入居者募集","exchanges":[{"speaker":"武内委員","kind":"確認","question":"何年か前の建設委員会で聞いた記憶があるんですが、忘れてしまったので、確認させてください。それとも何か一定の間を縫ってスケジュールがあるのか、それについてのお知らせというのは、広報「しながわ」とかで出しているんでしょうか。そこだけ確認したい。","respondent":"柏原住宅担当課長","answer":"地元割ですね、こちらのほうにつきましても、物がまず東京都としましては、物件が出ないとちょっと出せないというところがございまして、なかなか周知が難しいということと、物が来ても、ここ何年かは１件とかという形でございまして、なかなか募集しても。","voiceIndex":68,"id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"地元割についてはわかりました。そうすると、今まで、そうは言っても１物件について２０倍、３０倍と、多くの方が一応知っていて募集があればまだいいんですけど、知らなくてということがあるのかどうか、その辺はどうなんでしょうか。","respondent":"柏原住宅担当課長","answer":"どういうやり方がいいのかというのはありますけれども、なるべく窓口等においてお問い合わせいただければ対応できるようにはいたしますし、そういったところでフォローしていきたいという形になってしまうのが現状です。","voiceIndex":70,"id":"exchange-023"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"単身者住宅が４戸、ポイント式が８戸、余りにも少な過ぎると思います。現在東京都はそこをどう考えているのか、あわせてご説明いただきたいと思います。それぐらい今都営住宅に入居したいという方が増えているあらわれだと思うんですね。もし今手元にあれば、事故物件の申込倍率といいますか、どれぐらいの方がそういうところでも申し込んでいらっしゃるのか、倍率についてもご説明いただきたいと思います。","respondent":"柏原住宅担当課長","answer":"こちらのほうもお話を聞いたこともありますけれども、そういったことについては回答できかねるという返事をもらっています。","voiceIndex":74,"id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"改めて都営住宅の増設をしっかりと東京都に求めていただきたいと思います。事故物件の件については、なかなか言葉を選んでしまうんですけれども、例えばご病気であったり、一人でお亡くなりになったり、さまざまな事情もありますので、ぜひ増設を働きかけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-025"}]},{"id":"topic-06","title":"住み替え住宅（大井林町高齢者住宅）の募集結果","agenda":"住み替え住宅（大井林町高齢者住宅）の募集結果","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"住み替えの募集に当たって、いろいろ役所の調査、事前に調査をいろいろやられて、２０戸という枠を決めて募集されたわけですけれども、この結果について、所管としてはどのような評価をされているのかということと、それからそれぞれ八潮と木造密集地域で今回合計１１世帯の方々が移ってくるわけですけれども、その跡の利用というんですか、それぞれ違うかもしれませんけど、主なところで。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"４件ぐらいは希望されているというところがありまして、引き続き相談センターを通じてＰＲ活動していきたいというふうに考えております。それから今後密集地区のほうについては、単身用１戸、それから世帯用１戸を残していただきまして、まだまだ７月から今までの間に２件というふうになっていますが、少し悩んでいる方も何名かいらっしゃるということで。","voiceIndex":82,"id":"exchange-026"},{"speaker":"武内委員","kind":"質問・要望","question":"通常で八潮のそこに入るよりも有利な条件、例えば家賃が少し安いだとか、何かそういう条件が提示されているのか、それともその辺は相場なのか、そこを教えていただきたいのと、あとは木造密集地域のほうは、ちょっと今質問したところで、除却された跡は、例えば区がそれを購入する場合もあると思いますが、今回のケースは、それを所有者がどこかに売るのかどうかわからないですけど。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"まだ４件といいましても、具体的にどうだというのは決まってはいないんですけれども、例えば家賃を安くするとかということではなくて、相場の家賃で。ただ、八潮はこれだけ住む魅力がありますよというのを大きくＰＲしたいです。その土地の利用ができない場合というのもありますけれども、区のほうで、例えば密集地であれば防災広場とか、そういうものに適した土地であれば買い取りということも考えられるんですが。","voiceIndex":85,"id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"２０戸募集で１１戸だったというところはどういう事情があったのか、状況にどういう特徴があったのか、そこを伺いたいなというふうに思いますのでご説明いただきたいと思います。私の感覚で言うと、まずこの制度は結構複雑だなと思うこともありまして、また家賃の設定が本当にこれでいいのかなという思いもあるんですけれども、実際の状況にどういう特徴があるのか、そこをご説明いただけますでしょうか。","respondent":"柏原住宅担当課長","answer":"事情と申しますと、個々の事情ということですか。","voiceIndex":88,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"住み替えで今回２０戸という枠をとりました。これから１３戸になってしまうんですけど、住み替え住宅は１回だけの施策なのか、その後につなげていくのであれば、２０戸というのはどこかで確保しておかなければいけないんではないかというふうに、そこをあけておけという意味ではなくて、そういう担保も必要かと思うんですが、そこはどういうふうにこれから整理をしていくのか、考え方を教えてください。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"今後についてですけれども、２０戸ということで１１戸入る予定で今考えていますけれども、これについてはこの方たちが基本的には１０年、２０年という形で住まわれると、そういうコンセプトで住み替えの住宅はありますので。密集地のほうにおきましては、確かに先ほど申し上げたとおり、７月から制度を始めたということで、期間が短かったということもあるんですが、この間興味を持たれた方というのは非常に多かったです。","voiceIndex":93,"id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"それと、あと本当に高齢者住宅がすごく希望が多いのに、こういうことというのは条件が厳しいのか、家賃とかそういう問題とか、財産を持っていての移動なのでとても選択するほうもすごいハードルが高いというような理解をするんですが、ちょっと余りにも目算と違ったのかなというところについて、どんなふうにこれをいいほうにちゃんと向けていくのか、その辺の考えはどうなんでしょうか。","respondent":"品川防災整備担当課長","answer":"ただ、今後こういった施策をして、いろいろ課題も出てきましたので、その辺の課題を踏まえながら今後どのようにやっていったらいいかということは検討していきたいというふうに考えております。","voiceIndex":96,"id":"exchange-030"}]},{"id":"topic-07","title":"品川区まちづくりマスタープラン全体計画骨子（案）","agenda":"品川区まちづくりマスタープラン全体計画骨子（案）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"上にどーんとかぶっているんだけども、そういう何となく開発とか大きな建物を誘導してというような、こういう図だとそういうふうに見えてしまうんですけれども、このところはどういうふうに見ていったらいいのかという、この図だけでぼーんとあらわされると、そういうイメージが、見ると感じるんですけど、そこのところはどういうふうに読めばいいんでしょうか。","respondent":"山崎マスタープラン担当課長","answer":"それで、来年度今回検討させていただいている全体骨子案をまとめて、地区別の計画のほうに移るときには、地区別に少し包括を、地図も含めて、その地域ごとに隠れているところ、あるいは商店街等々も含めて、地区別のほうで規定をしてまいりたいというふうに考えてあります。","voiceIndex":102,"id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"もう一つ、品川・天王洲アイルの新拠点と品川シーサイドという、まちづくりだと住民のところからいうと、拠点が企業の活性化みたいなところであると思うんですが、これはどういうふうな形で、品川区全体というと結構端のほうというか、臨海部になっていて、全体としてここに品川区、行政としてどんどん違う部分のものを想像して、イメージして、こういう図になるんでしょうか。今後のまちづくりとして。","respondent":"山崎マスタープラン担当課長","answer":"右側の広域都市構造におきましては、各副都心、都心が並んでございまして、ちょうど品川駅の周辺につきましては、東京都のほうでもこれから新拠点としていろいろ業務の一定の集積ですとか、そうした品川の駅周辺らしいまちづくりをしていきたいというような構想と。","voiceIndex":104,"id":"exchange-032"},{"speaker":"井上委員","kind":"質問・要望","question":"４ページの今後の予定のところなんですけれども、年度末に素案をまとめて、来年に向けて、１０月パブリックコメントというその期間に、やはりこういうところでぜひ自分たちも参加をしていって、パブリックコメントが十分に言えるような、まだ先が長いですから、ここにある程度議論の場を設けるとか、そういった地区別方針素案取りまとめに向けて、地域ごとの、多分、区政協力委員とか。","respondent":"山崎マスタープラン担当課長","answer":"したがいまして、今回お示しのものにつきましては、パブリックコメント等の表示ですけれども、例えば区政協力委員会のいろんなお声を聞く場でありますとか、そうしたところをこれからちょっと住民の意見の反映について検討して。","voiceIndex":106,"id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"法的にパブリックコメントというところがあると思いますが、そうではなくてというところの意味なので、これから検討いただきたいと。どんどん変えていくほうにしていただきたいというふうに思いますので期待をしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-034"},{"speaker":"松澤委員","kind":"質問","question":"１点聞きたいんですけど、３ページです。都市基盤のところで、都市計画道路の整備促進、補助２９号線、補助３１号線と書いてあるんだけど、これをどのように考えているのかお伺いします。","respondent":"山崎マスタープラン担当課長","answer":"今回のマスタープランにつきましては、区の上位計画です区の長期計画等々と整合を図りながらということで考えてございまして、現在の長期基本計画におきましても都市計画道路の整備については整備を促進していくんだと、こういうようなことで補助２９号線。","voiceIndex":109,"id":"exchange-035"},{"speaker":"松澤委員","kind":"提案","question":"補助２９号線は防災的には必要だということですけれども、前期整備計画に入っておりませんので、これから働きかけていくということで、あの件については、品川区の議会の中では３回廃止ということを提案しているんですよね。","respondent":"片田防災まちづくり事業部長","answer":"東京都のほうも、１０年の中の検討の、例えば木造密集地域の特区とか、いろんな考え方を持ってありますので、そういうものと例えば密集事業に入っている計画道路、これを東京都としても今後早目に進めていきたいという考え方もあるようですので。","voiceIndex":111,"id":"exchange-036"},{"speaker":"武内委員","kind":"質問・要望","question":"２ページの地域生活拠点のところで、「より身近な生活圏を支える拠点として育成」と書いてあるんですけど、ちょっとわかりやすく、教えていただきたい。それに対して、プロジェクトというか、考え方を出していくというふうな話になっているはずなんですけど、その中で今補助２９号線という話が出たんですが、それは交換条件なんですか。そういう位置づけなのか、その辺をお願いします。","respondent":"片田防災まちづくり事業部長、山崎マスタープラン担当課長","answer":"先週、部長会のほうでも、そういう考え方の大枠については説明を受けましたけれども、区としてはその中で大きく二つだけありまして、木造密集地域特区のところと、あとその密集地を計画されている計画道路。ちょっと説明になっていない部分もあるかと思いますけれども、基本的には地域生活拠点につきましては、従前のものと考え方は基本的には変わっておりません。","voiceIndex":113,"id":"exchange-037"},{"speaker":"大西委員","kind":"質問","question":"それで、空き家がなぜそんなに多いのか。それと、いったい有効活用というのは、どういう方向での有効活用なのか。それと、ファミリー世帯の定住化に向けた支援というのは、具体的に、定住化といっても、お勤めになっているところの事情で変わっていくこと等々があることであって、区がどうこうという問題じゃないんではないかという認識を持つんですが、そこはどうですか、その３点は。","respondent":"山崎マスタープラン担当課長、柏原住宅担当課長","answer":"ファミリー世帯の住居取得にかかわる支援ということにつきましては、ここはファミリー世帯というところでございまして、今ちょっと検討しておりますが、そうした居住に適した良質な、例えば民間住宅の供給の誘導でありますとか促進。若干補足ですけれども、例えば空き家の数です。今ここに、小さくて見づらくて申しわけないんですが、２万４,８９０戸の空き家がある。","voiceIndex":116,"id":"exchange-038"},{"speaker":"大西委員","kind":"質問","question":"今の３点目のところは大体わかったんですけど、１点目の今ある住宅の住みやすさの維持・改善と有効活用、これは耐震に対する補助をするということですか。","respondent":"柏原住宅担当課長","answer":"そういったところに対しても、何らかの例えば助成になるのかどうかはちょっとあれですけれども、何らかの形でバックアップできるものはないかなとか、それからあと、普通の一般の住宅でも、今も住宅改善事業というのを住宅部門でやっているんですけれども。","voiceIndex":119,"id":"exchange-039"},{"speaker":"大西委員","kind":"質問","question":"これからもますます高齢化を迎えるということと、２番目の高齢者等が住みやすいものと空き家の有効活用、だったら、住むべき高齢者住宅がない。おそらく公営住宅に入りたいのは高齢者の方が多いんじゃないかというふうに想像するんですけど、それとあわせて、空き家の有効活用、治安の問題もあって、そういう方向で少し品川区も考えていく視野を持ってもいいんじゃないかと思うんですが、その辺どうですか。","respondent":"柏原住宅担当課長","answer":"加えて、ハードの面で例えばバリアフリーであるとか、先ほどちょっと申しましたけど、住宅改善事業のほうでそういったところを包括的に、中を改善したようなときに助成金を出すとか、ハード、ソフト、両面でそういったところを大きな視点として進めていこうとしています。","voiceIndex":121,"id":"exchange-040"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"資料の冒頭にポイントとありますけども、改めて伺いたいんですけど、太字で書かれている部分ですね。二つ目の拠点形成や土地利用の方向性、下の今も若干議論がありました量から質、建設からストック活用への転換、これはどう目指しているのかそこを伺いたいと思います。それと、補助２９号線、補助３１号線の問題ですけれども、これは削除すべきだと思います。伺いたいのは、なぜこの路線が必要なのか。","respondent":"山崎マスタープラン担当課長","answer":"もちろん目指すべきおおむね２０年後を見すえた品川区の将来都市像を考えるに当たりまして、今日的な課題になっている防災面から見たまちの安全、これをいろんなまちづくり分野を包括した計画ということですから。","voiceIndex":123,"id":"exchange-041"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"もう一つですけれども、防災上とご説明がありますが、この際その前に伺いたいことがあるんですけれども、まず災害時でない、平常時の場合、火災が発生したときに、住宅に向けて当然消火活動を行うわけですけども、補助２９号線、補助３１号線の周辺だけでなく、品川全体を見たときに、火災が発生したときに、消防隊が消防活動をできない、住宅に放水活動ができない。","respondent":"岩田都市環境事業部長、山口防災安全担当課長","answer":"屋上屋になって申しわけないんですけども、まず道路とは何ぞや、都市における道路とはどういう役割なのかというところから少しご説明したいと思います。消防活動のことの２点についてお答えいたします。","voiceIndex":125,"id":"exchange-042"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今部長のほうから３月１１日を受けてというお話もありました。整理して改めてご説明いただきたいと思います。４年以内に７０％という、いろんな経過があります。てんぽについて、どう合理性を説明するのか伺いたいと思います。その中で、果たして消防車は駆けつけられることになるのか、延焼を遮断するための役割を果たせるのか、そこをどうやって防災上考えていらっしゃるのか、改めて伺いたいと思います。","respondent":"岩田都市環境事業部長","answer":"ただ、国の機関が正式に述べているようなものについては信憑性が高いということで、区も区の防災計画の中に生かしながら直下型地震に向けて鋭意努力しているわけですけれども、昔、昭和４０年代、川崎の地盤沈下を中心に６９年周期説というのがまことしやかに言われました。","voiceIndex":128,"id":"exchange-043"},{"speaker":"中塚副委員長","kind":"質問","question":"少なからず明日来てもおかしくないと言われている中で、こういう補助２９号線、補助３１号線の道路計画を中心とした防災対策が果たして現実的なのかと私は思います。もう１点、道路をつくっても実際に消防活動はどうなのかというお話がありました。地域の方々に話を聞くと、この道路計画は、要するに自分の家も含めて近所が家事になったときに消火活動がしやすいと、そういうふうな説明をよく伺っていると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-044"},{"speaker":"中塚副委員長","kind":"質問","question":"そこをしっかりとやっていかなければならないと思いますが、消防能力の向上と住宅耐震化、そこを位置づけ直すべきだと思うんですが、いかがかということ。最後に、住民の方々に対してこの道路の説明をするときに、あたかも消防車が来やすいでしょうみたいな、そういう説明というのは今の説明と違うじゃないかと、どう考えているのかを伺って、この計画はやめるべきだと思います。","respondent":"岩田都市環境事業部長","answer":"道路がない都市というのは、都市であり続けることはできません。都市の基盤は道路なんです。先ほど言いましたように、東京２３区は残念ながらその道路が諸外国から比べると未整備である。さまざまな都市問題を抱えてしまっているのが、この東京の実態であります。","voiceIndex":132,"id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"防災フェアで参加団体が主にライフラインの関係者ということで、目的がそういう大きなハードの部分というものなのかなと思うんですが、こういう機会で今回特に震災、３・１１のその後でやっぱり避難する、１,５００人ぐらいの方が来るといったときに、一般の人たちをどう取り込むかという部分で目的がちょっと違うのかもしれないのであれですが、今回は展示物だとか。","respondent":"中山防災課長","answer":"それぞれ水道局だとかガスだとかというところが、それぞれブースを持ちまして、いろんな危険物の啓発等々をやってあります。今ご提案になりました視覚障害者、それから聴覚障害者の訓練等については、別の機会に設けたいと思ってあります。","voiceIndex":138,"id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"これの対象者はどのぐらいいて、どのぐらいの参加を見込んでいるのかということと、あとはこれにかかわるこれを推進したいという並み並みならぬ意欲はよくわかるので、経費はどれだけかけてやろうとしているのか、その費用対効果も含めてちゃんと把握をしておきたいというふうに思いますので、その辺をちゃんとした数字で教えてください。","respondent":"品川防災整備担当課長","answer":"経費に関しましては、こちらは日本大学のほうにマニュアル制作費として２００万円費用をかけております。それから、この講演会に関する費用に関しましては、区の庁舎でやるということ、それからほとんど職員が対応するということで経費はゼロです。","voiceIndex":144,"id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"こういった講師の方というのは、どのぐらいの講師料を払ってお願いしているんでしょうか。","respondent":"品川防災整備担当課長","answer":"こちらは日本大学に２００万円をマニュアル作成費用というふうに出しております。その中でやっていただくというふうになっております。","voiceIndex":146,"id":"exchange-048"},{"speaker":"武内委員","kind":"質問","question":"ちょっと私が勘違いしているとあれなんですけど、そうすると、今まで品川シェルターは２件か３件の施工がありますけども、これを施工できる業者というのは品川でどれぐらいいたんですか。","respondent":"品川防災整備担当課長","answer":"こちらは、昨年度までにトータル１件、それから今年度２件ということになっているんですが、３件とも一つの業者に日本大学と協力してつくってもらっているというような状況、現在はそういう状況です。","voiceIndex":148,"id":"exchange-049"},{"speaker":"武内委員","kind":"質問","question":"私はあらあらマニュアル化されて、既に幾つかの業者ができると思っていたんですけど、できなかったのでということですか。ただ、そうなると、わずか１日２時間だけで本当に習得できるのか。","respondent":"片田防災まちづくり事業部長","answer":"今回は業者が実際に、区内業者ですけれども、設置した例なんかも一応紹介をしながら、どんな苦労があったとか、どんなことを工夫したとか、ちょっとそういう技術的なところ、あと相談の受け答えができるような対応を考えていきたいと考えています。","voiceIndex":150,"id":"exchange-050"},{"speaker":"中塚副委員長","kind":"質問","question":"なので、進まない理由をどう考えているのか改めて伺いたいと思います。私はいろんなアイデアだったり技術だったりを駆使して、これはシェルターですから住民の命を守ろうということそのものはやっぱり大事なことだし、しっかり進めていかなきゃいけないとは思うんですよね。","respondent":"品川防災整備担当課長","answer":"まだ区としても広報が足りない点もあるかと思います。今後そういった講習会を開きまして複数の業者が品川シェルターに関心を持ってもらって、その業者からまた品川シェルターを広げていただくというような形をとっていくためにも今回講習会を考えております。","voiceIndex":152,"id":"exchange-051"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"シェルターの説明をする中で、やっぱりシェルターよりも住宅の耐震のほうがいいと。むしろ本当にそれはよいことだなと思うんですよね。今、若干ご説明がありましたけれども、しっかり位置づけて改善策を進めていくというふうにぜひ位置づけていただきたいと思うんですけど、もう一度いかがでしょう。","respondent":"品川防災整備担当課長","answer":"委員おっしゃるとおりいろいろ品川シェルターもまだまだ課題はあると思います。いろいろそういった課題を踏まえまして、今後制度等研究はしていきたいというふうに考えております。","voiceIndex":154,"id":"exchange-052"}]},{"id":"topic-08","title":"武蔵小山駅周辺地域街並み誘導指針（案）","agenda":"武蔵小山駅周辺地域街並み誘導指針（案）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"商店街はなかったことになるんですが、それに加わったんでしょうけど、ここはもう少し幅広く声をかけていただく機会を設けてほしいと思いますが、これについてはお願いしたい。お願いする問題じゃなくて、すべしという意見ですが、どうですか。","respondent":"三宅都市開発課長","answer":"２点目ですけれども、こちらは先ほどのまちづくりマスタープランの地区別の方針というところでもございましたけれども、ちょっと周知の方法については議論していきたいと考えていますが、まちづくりのビジョンにつきましては。","voiceIndex":160,"id":"exchange-053"},{"speaker":"井上委員","kind":"質問・要望","question":"ビジョンであるから示すというんですけど、６ページの例えば(2)の「拠点性を象徴するスカイラインの形成」とか、ほかのところで言えば、「複数の高層建築物群により地区の拠点性を象徴し」とか、そういうふうに、そうではないいろいろな議論があって、なぜだろうというときに、そういう意見が反映されないで、こういうふうに区の考えとして、そのスカイライン。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-054"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"伺いたいのは、それが住民要望の反映だと区は考えていらっしゃるのか、この点を伺いたいと思います。それともう一つ、この資料の１１ページに先ほどイメージ図という説明がありましたが、そこをちょっと伺いたいんですけども、今ある建物というのは、一番ねずみ色が濃いと言ったらいいんでしょうか、住宅だけのことなのか、後ろにあるところですね、６０ｍ、１００ｍ、１４０ｍなんでしょうか。","respondent":"三宅都市開発課長","answer":"具体的にどんな建物にして段階的に建て替えをしていったらいいかというような商店街の検討もありますし、そういった意味で住民要望といいますか、そういった動きをどのように誘導していったらいいかという考え方を示したものでございまして、一定の内容。","voiceIndex":163,"id":"exchange-055"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"１４５ｍ、航空法いっぱいの高層ビルが住民要望の反映なのかと伺ったら、くみ取ったものだとご説明がありました。どうくみ取ったらこうなるのか私は聞きたい。武蔵小山に住んでいる方々は、１４５ｍ航空法いっぱいの超高層ビルではなくて、人の声が息づくといいますか、会話ができるといいますか、わいわいと住んでいる、人の生活が息づくというんですかね、こういうまちを願っているわけですよね。","respondent":"三宅都市開発課長","answer":"２点目のほうからご説明いたしますと、これはあくまでもイメージですが、白いところからいくと図面上は１４０ｍ程度です。それから、その次の薄い色のところが約６０ｍ程度となっています。その次は４５ｍ前後であります。","voiceIndex":165,"id":"exchange-056"},{"speaker":"中塚副委員長","kind":"質問","question":"今数えたら１４０ｍ級が３棟、６０ｍ級が３棟、４５ｍ級が１２棟から１３棟、こういう武蔵小山に私は変えてほしくない。そういう幻想をいまだに現実的にお考えなのか伺いたい。例えば、サラリーマンの平均年収だって、今から１５年前に比べて５５万円も減っているんですよ。本当にそういう中でポテンシャルが高いから人が集まると、そういうのをどういう根拠でお考えなのか。","respondent":"三宅都市開発課長","answer":"このまま手をこまねいているというのではなくて、どういった形で更新をしていったらよいのかと、そういうことを踏まえて、こちらの計画をつくっておりまして、そこは地元と協働で。","voiceIndex":167,"id":"exchange-057"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"前回の説明会のときの区民の方たちのご理解、どんなことを言われたのか、それについてと、１６区で説明会を開催ということは、大田区と品川区の調査結果で拡大をするということは決定をしたということなのか、それはどこで決定をされたのか、そこを教えてください。","respondent":"太田品川区清掃事務所長","answer":"ただ、現地での焼却試験結果、それからそのデータをもとにして一部事務組合で安全であるということは確認をしていますけれども、さらに区民の皆さんの不安感を払拭しようということで、大田清掃工場と品川清掃工場で実際に災害廃棄物を持ってきて焼却をして。","voiceIndex":175,"id":"exchange-058"},{"speaker":"井上委員","kind":"意見","question":"１点、一部事務組合のホームページで公表されるというのは当然なんですけれども、それを区のほうでリンクを張って、区でもちゃんと見られるようにということはやっていただけるのかどうか。","respondent":"太田品川区清掃事務所長","answer":"現在でも私どもも１１月２４日のときからホームページで掲載しています。それから東京都、清掃一部事務組合、それから環境省のほうに必要な部分についてはリンクを張ってありますので、当然焼却の部分についてもリンクを張っていく方向で考えているところです。","voiceIndex":177,"id":"exchange-059"},{"speaker":"井上委員","kind":"質問","question":"当然リンク先にはあるんですけれども、特に東日本大震災に関連してとか、ああいうところにちゃんとわかるようにしていただいたほうがいいというふうに思うんですが、そういう形でしょうか。","respondent":"太田品川区清掃事務所長","answer":"それからもう一つは、新しく試験焼却が出て、清掃一部事務組合でアップしましたら、同時に区の新着情報の真ん中に新たに張ります。そこで、資源リサイクルのところに飛ぶように、こういうリンクの張り方をしています。","voiceIndex":179,"id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"区が独自にやった以外に区民の方から、例えば八潮で、八潮はちょっと高かったことは事実だと思います。それで、はかっていただいたという事例があるので、区民の要望で、はかられたところというのは何件あって、データがどのぐらい違って、ちゃんとご報告できたのか、その辺をちょっと確認させてください。","respondent":"野呂瀬環境課長","answer":"あくまでも区の方針は１ｍの高さではかりました。今委員がおっしゃった私どものほうで、はかったより高いところは、私どものほうからもう一度測定に行きますということで行ってまいりました。やはり、１ｍの高さでは同じです。","voiceIndex":184,"id":"exchange-061"},{"speaker":"井上委員","kind":"意見","question":"今は落ち着いているので今の状況だと思いますけれども、まだ完全に終わったわけではないので、これでよしということではなくて、アンテナを張っていただいて対策のほうをよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":186,"id":"exchange-062"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"１,１４１カ所測定したというご説明ですが、そのすべてがホームページに出されているんでしょうか。ぜひ今後も測定したら速やかに公表していただきたいと思いますので、その点だけ確認します。","respondent":"野呂瀬環境課長、稲川委員長","answer":"それから先ほどのことですけど、八潮の方から今後もよろしくお願いしますということで、それについては区のほうとしても今後もこれでおしまいということではなくて、それから感謝の言葉もいただいているところです。ほかになければ、本件を終了します。その他でほかになければ、以上でその他を終了いたします。以上で、本日の予定はすべて終了いたしました。これをもちまして、建設委員会を閉会します。","voiceIndex":187,"id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4028#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":69226,"voices":189}},{"id":"h24-20120123-9","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"文教委員会","time":"午後１時００分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"区民委員会でも報告ということなんですけれども、ちょっとまだよくポイントがわからないんですが、とりあえずこの東京ケータリング株式会社という会社はどんな会社なのか。今、杉並区で移動教室の経験があると伺ったんですが、全体像がわかると、特に杉並でやっているから大丈夫というものなのか。ちょっとその辺の審査の中身、あと決定理由とかがわかったら教えてください。","respondent":"和氣学務課長","answer":"決定理由は、基本的には一番この事業者が安定的に、さまざまな区民に活用されるように施設を使っていただけるという判断に基づいて決めたものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"他の施設も同じように請け負っているという、この裏面に載っています民間借上げ施設に代わる利用というのは、これも東京ケータリングが行っているというところですけれども、１から８までというのは、どういう、これも皆さん貸付の施設なんですか。そうでもないんですか。ちょっとその辺を教えていただきたいのと、移動教室など校外学園の利用にあたって、今後どのように仕様書とか内容的に結んでいくのか。","respondent":"和氣学務課長","answer":"移動教室に関しましては、借上げをしますので借上げの契約をします。それから、移動教室について、もしくは林間学園における現地での活動についても若干委託する部分がありますので、そういうことで仕様書で詳細に定めてまいりたいというふうに考えてあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"仕様書を交わしていくということです。ちょっと今の移動教室の委託の部分で、この施設管理をするところに具体的に移動教室で委託をするということは、具体的にどういうふうな感じですか。","respondent":"和氣学務課長","answer":"具体的には例えばテントの管理であるとか、キャンプファイアーの補助であるとか、こういう組み立てをするということです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"木村委員","kind":"質問","question":"これは区から民間にあれするわけですけれども、これ、契約内容となっているのは毎月いくらかという感じでやるんでしょうか。それとも売り上げでやるのか。そういうのはわかりますか。","respondent":"和氣学務課長","answer":"区民委員会でのご議論になるかと思うんですけれども、基本的には貸付ですので、契約ではないんです。貸付でその際に覚書で、例えば利益があがった場合にそのうちの何％をもらうとかという、そのような覚書を交わすようになってあります。","voiceIndex":12,"id":"exchange-004"},{"speaker":"木村委員","kind":"質問","question":"ちらっと控室でそういう話があったんですけれども、一応無料で貸し付けるという形ですよね。利益が出れば５０％をいただくという形だと思うんです。それで間違いないでしょうか。","respondent":"和氣学務課長","answer":"パーセンテージについては今まだ交渉中だと思いますので、それも地域活動課のほうで今取り組みをしているところだと思いますけれども、基本的にはそういうことでございまして、あくまでも無料貸付になりますので、その範囲内でということになります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"株式会社ヒューマンサポートについて教えてください。ちょっと調べたら人材派遣会社となっていたんですけれども、保育所に関する実績とか、質の担保がどういうところでされるのかを教えてください。ここの開設までの経過、どういう経過でここに決まったのかということと、このほかのところも今検討中なのか、認証に関してですけれども、教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"ほかの計画ですが、来年度につきましては、ただいま認証保育所の開設を検討中のところですので、まだはっきりとここでという形ではお伝えできるものではございません。","voiceIndex":21,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"確認","question":"最後のところですが、いくつか検討しているということで、発表にまでは至っていないということですね。わかりました。今、クリニックの２階があいている。３階建ての建物で２階があいている。１階は埋まっているんですか。ちょっと環境を聞きたいのと、近くに子どもが遊べるような公園とかが確認されているのかどうか、その辺も教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"これは確認はしておりませんが、そういう環境にありますので、かなり友好的というか、好意的に対応してくださるところとは聞いております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"開設に当たっての補助金がどんな項目があるのか教えてほしいのと、あと、今後の周知について教えてください。","respondent":"伊崎待機児童対策担当課長","answer":"開設の補助金ですが、こちら最終補正でご提案する予定ですので、詳細はこの場では控えしますが、内装経費のほうの補助金を計上しております。それから、周知ですが、２月１日号の広報で周知をする予定です。","voiceIndex":25,"id":"exchange-008"},{"speaker":"阿久津委員","kind":"質問","question":"けいひんファミリークリニック、よく使わせていただくので非常にいいところにできるなというふうに思っています。もしおわかりであればで結構なんですけれども、募集の時期と保育料、年齢によって変わってくると思うんですけれども、わかる範囲で教えていただければと思います。","respondent":"伊崎待機児童対策担当課長","answer":"保育料についても、まだこちらのほうに認証の申請のときに上がってくるものですので、数字のほうはいただいていないんですが、当然上限８万円という規定の中でやっていきますし、こちらも区の保育料補助の対象となる施設です。","voiceIndex":27,"id":"exchange-009"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"具体的にどのくらいの位置にあるのかわかりましたら教えていただきたいということと、小山台小学校が一日中英語の授業をやったという、そういう話もこれからそれは広げていくのか、どのような方向性をもっていらっしゃるのかをお聞きしたいということと、不登校に関しても、数値的にわかれば、減ったということに関して具体的にわかれば教えていただきたいのでお願いします。","respondent":"冠木指導課長","answer":"今後、例えば授業の中の英語だけではなくて、日常会話ができるような取り組み、イングリッシュタイムと呼んでいますけれども、そういった取り組みを各学校全体に広めることによって、さらに英語の力をつけるように進めてまいりたいというふうに思っているところです。","voiceIndex":34,"id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"今、ご説明いただきました第IVステージの重点のところで、いくつか補足といいますか、もうちょっと詳しくお伺いしたいことについて、外部評価制度の充実ということで、児童・生徒評価の導入で、アンケートを児童・生徒にとるというようなお話でしたが、どのような内容について児童・生徒に、逆に児童・生徒も１年生から９年生までいる中で、どの辺の子どもたちにどのようなアンケートをされるのか。","respondent":"冠木指導課長","answer":"モデル校につきましては、７グループ１１校ということで学校と今、調整をしているところでございまして、分離型、一体型、連携型、それぞれにバランスよく指定をする予定です。","voiceIndex":36,"id":"exchange-011"},{"speaker":"渡部委員","kind":"確認","question":"今、最後のほうの質問のところで、じゃあ、今後は本当に分離型一貫校というのと、連携型一貫校というのが分かれて考えられていくというスタンスでいいのかという確認と、保幼小の連携校も実はこの連携型一貫校か分離型一貫校かに入ってきているということで、ここ、ちょっと４つ独立な形に見えてしまったので、確認だったんですが、そういう考えでいいのかどうかをもう１回お願いいたします。","respondent":"若月教育長","answer":"今、委員のご質問、特にこれから第IVステージに臨んで大体どのぐらいの期間を展望してというようなご質問だろうと思いますが、それをご説明するに当たって、先ほど来のご質問に関連づけてお答えをしたいと思います。","voiceIndex":38,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった生活ができているのかどうかというのがすごく重要。先日、特別区の議員研修のところで、講演があったんですが、日本の子どもたちは世界の子どもと比べると、極端に自己肯定感がないというあたりをすごく重視して見られていたので、その辺のところはどうなのかなと思って、この２点をお伺いします。","respondent":"冠木指導課長","answer":"それにはどういったカリキュラムのマネジメントをしていく必要があるかといったところで、今後進めてまいりたいというふうに考えているところです。","voiceIndex":40,"id":"exchange-013","title":"議員研修会の内容と所要時間"},{"speaker":"飯沼委員","kind":"質問","question":"でも、実際的にはいろいろな問題も起こっているわけですよね。特に、私たちなんかは、地域だと町会の皆さんと接していることで本当にこの間、学校選択制の問題は広くご意見をいただいているところです。私はいろいろ出てきている問題点を一つ一つ丁寧に答えていきながら、改善をしていくことが必要なんですが、やはりそういう姿勢が欠けているのではないかなと、私は端的に思うんですがいかがでしょうか。","respondent":"若月教育長","answer":"何をやっても、どんなことをやっても、教育あるいは教育だけじゃないんですけれども、常に課題というのはあるんです。ある１つのことをやったら全部なくなるなんて、そんなおとぎ話みたいな世界はないわけでありまして、新しい課題というのは常に出てきます。","voiceIndex":42,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"力を入れて言っていただいたんですけれども、今の私の質問に対しても、何かとにかく頑張っているんだから見ててほしいというのでは、それこそ外部評価制度の充実とかにはならないと思うんですよね。これを問題なしと言って先に行くのではなく、やはり数字であらわれたり、声の出ている部分をしっかりと受けとめて改善をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-015"},{"speaker":"須藤委員","kind":"質問・要望","question":"うちの品川の教育というのも、やはりそこに１つ面を見ていなければいけない。そういう本当のエリートみたいなのをつくる仕組みというのも、この間の質問の中には自分の意識の中には入っているんだけれども、第IVステージ云々といったときに、この間は今後の検討課題ですで終わっているんだけれども、そういったことも考えてもらえたらどうかなというふうに見ているんですけれども、いかがでしょうか。","respondent":"和氣学務課長、若月教育長","answer":"これは不公平じゃないかということで、このようになっておりまして、そこに象徴的なように、その一方で兄弟枠で優先的に入れるというのは不公平だという声もありますので、十分そこら辺も含めて検討させていただきながら。したがって、エリート教育といったようなものもそのうちの１つということで、重要な視点であるという認識は持っておりますし、本区の場合もそういった点も視野に入れて、小中一貫教育の充実に努めていきたい。","voiceIndex":45,"id":"exchange-016"},{"speaker":"須藤委員","kind":"質問・要望","question":"エリートという表現をしちゃうと、また怒られちゃうかもしれないんだけれども、本当に品川の子はどこへ行っても、世界へ羽ばたく子どもになってほしいよというのは、どこへ言っても物おじしない、どんな場面でも外国人と対してもというようなこともあるので、前からうちはインターナショナルスクールを区でもってきてやってくれという話をしているんだけれども、そういったような仕組みができて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-017"},{"speaker":"阿久津委員","kind":"質問","question":"委員のお話も、理事者のお話もそのとおりだなと思うんですけれども、私がやはりお母様たち、保護者の方たちとお話をすると、この『プラン２１』、向かう方向性がちょっとよくわからないという、それはもちろん各それぞれの関心とか勉強の仕方にもあるんでしょうけれども、やはりそういうお話を伺うものですから、教育長の先ほどのお話もそのとおりだと私も思いますし。","respondent":"若月教育長","answer":"今、ご指摘いただいたこと、これは私たちは謙虚に反省しなきゃいけないと思います。私たちは１４年余、この『プラン２１』に必死になって取り組んできました。","voiceIndex":49,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"にもかかわらず、今度は平成２４年度から、毎月２度の土曜日の授業が増えますよね。それと、そのときに以前、教育長のほうからゆとり教育をやってきたばっかりに、今現在の学力はあるというようなことを言われたと思うんですが、今、そのようにして成績がいい方向に行っているにもかかわらず、どうして月に２度の授業が増えるのか。これをもう一度はっきりと教えていただきたいと思います。","respondent":"冠木指導課長","answer":"私ども、品川教育を進めていく中で、ゆとりと言われていた時期においても、そこはそんなに削っていいものかというような私どもの判断もございまして、品川の教育の中身については、小中一貫教育要領というのをつくって、当時削られていた部分も当然その時代。","voiceIndex":51,"id":"exchange-019"},{"speaker":"渡辺副委員長","kind":"質問","question":"重なる部分もあるかと思いますが、特に、最初ちょっと自分の思いとこちら整理されている中で、よく地域で伺う中で、この第Ｉステージの開かれた学校、あるいは学校選択でものすごく重なる評価が多いなと思っています。それを伺いたいと思います。もう１点、学校、地域、家庭というくくりの中で、保護者の方との共通理解、先ほど阿久津委員がご指摘のように、皆さん、思いは思いであると。","respondent":"冠木指導課長、若月教育長","answer":"そういったところで地域の力を貸していただいて、より充実した学校教育をつくり上げていきたいと。第IVステージにおいてもその考え方には変わりはございません。イベント的にいろいろな方に来ていただいて、それが結集して１つの目標に近づくという、必ずしもそういうものではなかったわけです。したがって、ある程度呼べば、これで一応面目は立つなと、簡単に言えばですね。","voiceIndex":53,"id":"exchange-020"},{"speaker":"浅野委員長","kind":"質問","question":"すみません、私のほうから２つ、３つお伺いしたいんですけれども、最初のほうの質問の中で学力の話が出てきまして、全国平均よりも上だというような話をいただいたんですけれども、学力のほうはある意味では点数で出てくるところでわかりやすいんですけれども、例えば今の質問にも関連してくるんですけれども、人間性の部分、これは市民科等と密接なかかわりがあるのだと思いますけれども。","respondent":"冠木指導課長、田村教育次長","answer":"それに加えて、先ほど地域とのつながりというのがありましたけれども、例えば８３運動であるとか、ああいった地域を一体とした取り組みによって、子どもたちが基本的な生活習慣についても非常に前向きな姿勢で取り組んでいるというのは。先ほど教育長のご答弁でもあったんですが、第IVステージについては、あくまでスタート時があれなので、おおむね教育長の私見ですが、二、三年を１つの計画期間と考えております。","voiceIndex":56,"id":"exchange-021"}]},{"id":"topic-03","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"前のまとめのときに、ぜひ行程表を載せていただきたいと希望したんですが、なぜ載っていないのか。日程とどういう行程で動いたのかというのが最初のページにちょこっとでも入ったら、後で見直したときにとても役に立つと思ったんですが、他委員会では入っているようなんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"入っているところがありました。全部とは言いませんが入っていました。ぜひ次に活かしていただきたいと思います。","respondent":"浅野委員長","answer":"誤字とか簡単な文言の訂正等ございましたならば、これは修正して議長に提出をしていきたいと思います。大幅な変更、今、飯沼委員から指摘がございました部分につきましては、しっかりとまた正副委員長のほうで検討していきたいと考えておりますので、よろしくお願いいたします。","voiceIndex":64,"id":"exchange-023"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"児童センターのことなんですけれども、１０月から大規模改修が行われている中での休館ということなんです。ちょっと記憶がなかったので、これはバリアフリーとかエレベーターとか、そういうので考えられていたんでしたっけ。ちょっとその辺。","respondent":"安井子育て支援課長","answer":"こちらについてはエレベーターのほうはちょっと。もともと基本的には内部にしかつけられないものなので、もう園庭をどうこうする以外には、なかなかエレベーター等はつけられないような状況なので、こちらについてはそこまでの大規模改修は組んでございません。","voiceIndex":72,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"児童センターとかの改修で大規模のときとかは、基本的にはそういった面は検討されるんでしょうか。これは検討されたけど無理だったということなのか。もう１回そこのところをお聞かせください。","respondent":"安井子育て支援課長","answer":"基本的に児童センター自体は、これができた段階のときに、保育園と併設するところがほとんどでございまして、３階、４階というところを使っているというのが非常に多いので、そういった面では前に検討したことがあるんですけれども。","voiceIndex":74,"id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4750#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":28749,"voices":80}},{"id":"h24-20120123-5","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"総務委員会","time":"午後１時００分～午後３時２３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の「地域主権改革」による権限委譲等への対応","agenda":"の「地域主権改革」による権限委譲等への対応","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"３ページの第１回定例会に上程を予定しているということで法令が出ているわけですけれども、主に大体かかわるのは業界の方に関しての法律のようですけれども、これはここで４月に成立をすれば、いろいろな形で今までと違う動きというか、今まで例えば都庁に出向いたときでも、国に行っていたものが区の窓口に来なければいけなくなるとか。","respondent":"榎本企画財政課長","answer":"それとあと、窓口につきましては、東京都からの事務処理特例条例というものがありまして、委任事務として都のかわりに受け取って都へ渡していたという一面も入っておりますので、そういう形であれば、窓口自体は変更がないという形で。","voiceIndex":9,"id":"exchange-001"},{"speaker":"塚本委員","kind":"質問","question":"ということですと、基本的には権限が委譲されるんだけれども、法律の中身そのもので縛られる側にとっては、そんなに変更はないというふうに、基本的には、この委譲の中で新しく条例を制定する中で、じゃあ、ついでに区として今まであった基準をもっとこうしようああしようとか、そういうことはあんまりないと考えればいいですか。","respondent":"榎本企画財政課長","answer":"ただし、１番目の墓地、埋葬につきましては、初めて条例制定化するものですので、これにつきましては、２３区の中でも検討会が開かれまして、どのような形でやるかということで、この部分はやはりこの基準自体の中では、経営主体ですとか、構造の設備ですとか。","voiceIndex":11,"id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"今、塚本委員からもお話があったように、逆の見方で、ある団体なんかからは、条例化しろというような意見が出てくる可能性もあるのかなと思うんですけれども、その辺についてお考えがあれば教えてください。","respondent":"榎本企画財政課長","answer":"要望等いろいろありますけれども、それが現状、都が持っている条例と、区が定めるといった場合の条例の理由がきちんと成り立つかどうかとか、その辺を検討した上で条例の審議にさせていただきたいというふうに考えています。","voiceIndex":13,"id":"exchange-003"},{"speaker":"原委員","kind":"質問・要望","question":"まだ具体的な話という形ではなってきていないのでしょうけれども、あまり硬直化しないように、またそれだけではなくて、権限関係のほうも強くなり過ぎないようにということも配慮していただきたいので、その辺をもう一歩何かご意見があればお願いしたいと思います。","respondent":"榎本企画財政課長","answer":"基本的には、全体の流れから行きますと、権限の委譲ということで、自治体が定められるということではありますけれども、規制を強化するとか、そういう形ではなく、きちんと実情に合ったものを実情の中で運用していくということができるようにというのが基本だと考えていますので。","voiceIndex":15,"id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"ですから、もちろん区内のニーズに従ってですけれども、やはり品川区らしさというのは今後出てくるべきであろうかとは思うんですが、そこら辺、区行政側としてのお考えはいかがなんでしょうか。あくまでもこれまでどおりを旨とするということなのか、やはり今後よい品川の主体性というのを出していこうという思いも少しはあるのでしょうか。","respondent":"榎本企画財政課長","answer":"それで、どちらかというと、この４月にできるもののほうが影響が少ないものと、区として権限移譲を受ける中でのまず準備ができているという形でございまして、来年度、平成２４年度以降につきましては、もう少し影響が大きいものが出てまいりますので。","voiceIndex":17,"id":"exchange-005"},{"speaker":"阿部委員","kind":"質問・要望","question":"私たちも、もちろん立場上、行政に求めるだけではなくて、積極的に発言をしていきたいと考えています。今後、介護保険法等々、やはり少しずつ品川として主体性を強く出していくべき必要性があるかと思いますので、また今後とも、私たちも、私自身もいろいろと勉強していきたいと思いますし、ぜひ品川区としても検討を進めていってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"今までは東京都に任せていたんだけれども、今度は区のほうでしっかり法律も専門職も、専門的な勉強、そういう法律をしっかり熟知してやっていかなければならない、それに見合った対策というか、相談も受けなければいけないとなると、その辺、メリットもあると思うんですが、どうなんでしょう、区へ対する負担増という問題点というのはあるんでしょうか。","respondent":"榎本企画財政課長","answer":"それにつきましても、今後、都と協議をしながら、どういう事務量が増加するのかという、今まで区がやっていないものにつきましては、東京都がどれぐらいの事務量でやっているかということがはっきりわからないと、それが各区におりた段階で、１つのＡ区ではいっぱいあっても。","voiceIndex":20,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけなんですけれども、どれだけの量かわからないですけれども、区に負担がかかるということは間違いないので、その辺は東京都との、国とやられることもあるのかもしれないですが、やはり応分の負担は、権限は任せましたよ、でも、あとは市区町村でやってくださいというのも、それも大変なことだと思いますし、その辺、要望要請はよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点で、品川区としては、住民が地域の主権者だという点で、そしてまた、この地方分権というのもそういうことを大事にする流れの中で出てきているというふうに思うので、やっぱりきちんとした住民の意見反映をする努力というのはするべきだというふうに思うし、品川区もその立場に立ってきたから、今までもパブコメも含めていろいろと聞いてくる場面を大事にしてこられているわけですから。","respondent":"榎本企画財政課長","answer":"やはり実際に今後、今度の第１回定例会、それから平成２４年度中の条例、規則を改正していく中で、やはり人事的に必要なものであれば、その部分は対応していかなければいけないというふうに考えております。","voiceIndex":23,"id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"それとあと、冒頭の説明でちょっと気になったところをさっき言い忘れてしまったんですけれども、この資料の２ページ目のところの上から五、六行目のところに、1)の義務付け・枠付けのアの部分のところで、「条例事項については、いずれの法令においても各区対応と整理した」ということで、「各区対応」というふうになっているんですけれども。","respondent":"榎本企画財政課長","answer":"ただし、今まで東京都が２３区全部同一で基準を定めていたものがあまりにも急激に変わるというのは、やはり影響がありますので、そういうものについては整合性を図りながらということになりますけれども、各区対応というのは、基本的には各区で変わることもあり得ると。","voiceIndex":25,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"今の各区対応というのは、自立性を高めるものでというのがバックにあるんだということは、それはそれとして理解したんですけれども、個別に出てきた問題で、確認のこの内容をそのまま受けとめるという場合と、それはできないよという場合とあると思うんですけれども、個別にこれから具体的に出てくる、そのときにやっぱりきちんと報告もいただいて、意見を聞いていただく場面をしっかりとっていただければ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今までいろいろ質疑が出ている中で、品川区に地域主権改革によって区の独自性というお話の中で、現実的に法的部分、条例等、２３区あまり変わらない条件なんじゃないかなという気が非常にしています。区の独自性は本当に出せるのでしょうかというのが１点。その辺で独自性はどこまで可能性があるのかなという点を先に１回教えてください。","respondent":"榎本企画財政課長","answer":"それらにつきましては、十分今度の第１回定例会の審議の中でご説明する予定です。","voiceIndex":28,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"墓地、埋葬なんていう場合だと、例えば地域的にこの辺の地域であるとどうだよとかということが出てくるのかなというに思っていたんですけれども、全体的に厳しいかなと考えています。これが平成２４年度予算においては一切ゼロになるということで、一切というか、この事務に関してはゼロになるということでよろしいんですか。","respondent":"榎本企画財政課長","answer":"その他の権限につきましては、平成２５年の財調協議に向けて、きちんと実態を踏まえて、どういうふうにしていくかを検討するという状況です。","voiceIndex":30,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"平成２４年度の財調算定にその分は入っているというふうに考えてよろしいのでしょうか。","respondent":"榎本企画財政課長","answer":"入っているものです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"財調の話で行くと、枠の中、５５対４５の中での話ですよね。ですから、その分が費用がどのぐらいになるかわからない、２３区の総体がわからないですけれども、それを今までも区のほうで都に申請をしているのでしょうけれども、同じ基準の中でやっていったら、区としては算定が減るわけですよね。その辺のところもこれからもご努力をお願いしたいということで、その辺ちょっともう１回お願いします。","respondent":"榎本企画財政課長","answer":"やはり財調協議の中でもかなり議論があったんですけれども、基本的にこの権限移譲の部分で、例えば財調交付金の１％を超えるものであれば財調交付金の配分率自体を変える検討というのができるだろうという議論はあったんですけれども、今回の権限移譲は。","voiceIndex":34,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"全体像はもうわかりました。ただ、いろいろやっぱり東京都との件で、先ほども話が出たあり方の問題についても、いろいろとまっているところもありますし、区のほうでまたしっかりした対応のご努力をお願いしたいと思います。要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"品川区に限らず、１つの自治体の特性というのと、どういうふうにイメージしたらいいのかなというのがちょっとわからなかったので教えていただければ。だけどやっぱりその地域の地理的な状況とかいろいろなものがあって違いはあるけれども、それはわからなくもないけれども、地域の特性というのはどういうイメージをして発言なさったのか、ちょっと教えていただけると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"確認","question":"特性と最後におっしゃったとおり、地域ごとによって違いがあるじゃないですか。そこの部分。さっき課長のお答えの中で、墓地の中で、お寺の墓地が多いとか少ないとか、そういうところでいろいろ差がある、特性があるじゃないですか。その特性を生かした上でこういう全体の設定ができるでしょうかという意味を含めて話をしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"急に済みません。そういう関係でこちらに質問なんですけれども、独自性というのと、一律の行政サービスという、そこのバランス、その辺はどんなふうに考えていこうというふうにしているのかなというのを聞きたいなと思って。","respondent":"日下部企画部長","answer":"それによって全国の約１,７００の自治体が同じようなやり方でサービスを提供するということが、かつての日本の地方自治の１つのやり方だというふうに言われていましたけれども、ただ、この間の大きな流れとしては、地方分権とか地域主権とか。","voiceIndex":41,"id":"exchange-019"},{"speaker":"金野副委員長","kind":"質問・要望","question":"先ほどもご説明ありましたけれども、３ページの(2)番です、４月に条例・規則の制定を予定している法令ということで、これは第１回定例会に上程をされてくるものかと、それが１点確認をいただきたいのと、あと、これによって、今後、各条例によって、あるいは法令によって、各所管の常任委員会等々でこういうのは条例の審議をされていく、定例会によって上程されて、そしてしていく。","respondent":"榎本企画財政課長","answer":"今後の流れにつきましても、平成２４年度以降、まだまだ今後詰めていかなければいけない法令等ありますので、それにつきましては、それぞれどの定例会かも含めまして、準備ができたものから順次条例を上程する予定です。審議を行うものです。","voiceIndex":43,"id":"exchange-020"},{"speaker":"金野副委員長","kind":"意見","question":"そこら辺のところで、先ほども何回か独自性というお話が出ていますけれども、再度というか、もう一声というか、そこら辺のところの決意というか、この一括法に関しての今後の品川区の独自性というところの出し方というか、細かい具体的なことでなくても、決意というか、お願いしたいと思います。","respondent":"日下部企画部長","answer":"ただ、中身については、やっぱり、例えば今、２３区を見ましても、さっき、墓地、埋葬に関しても出ましたように、置かれた条件にいろいろ違いはありますけれども、ただ、やはり大半は都市としての集積みたいな状況というのがそんなに大きくは変わらないとか。","voiceIndex":45,"id":"exchange-021"}]},{"id":"topic-02","title":"の公共施設のコスト表示","agenda":"の公共施設のコスト表示","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"年度別実施施設というところで、平成２３年度からとなっているんですけれども、今年度はあと二月ちょっとぐらいなんですが、それでもここに書いてあるこの施設はやっていくという、そういうことかどうかが１点。最後は、こういう表示をすることによって区民の皆さんがどのような反応をするというふうに考えておられるか、予想でいいんですけれども、そのあたりをちょっと教えていただきたいと思います。","respondent":"榎本企画財政課長","answer":"平成２３年度のこの施設ですが、５０施設、今、準備をしておりまして、平成２３年度の今年の３月に施設に掲示をする予定で準備を進めております。その予算につきましては、６０万円ほどです。","voiceIndex":51,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"高い測定器とおっしゃったんです。意見があれば、ぜひ伺わせていただきたいと思います。そこをどういうふうに、３つに分けてやるというお話なんですけれども、その辺のいわゆる誤解を解くような努力というのはしておかなくてはいけないし、その数字、金額がひとり歩きしていくということは、これは避けていかなければいけないという思いがしますので、その点について最後に一言伺っておきたいと思います。","respondent":"榎本企画財政課長","answer":"それで、３年間の掲示ですので、それほど丈夫なものでなくても３年間であれば掲示できるかなと思いますので、３年に１回、データ等を入れ替えなければいけませんので、その辺も踏まえて工夫を図っていきたいというふうに思っております。","voiceIndex":53,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"意見です。そういう点で、やっぱりこれを出すということで、新たな誤解とか曲解みたいな、そういうことが起こらないようにしなくてはいけないのではないかなというふうに私は思いますので、ぜひそういうところも踏まえて対応をしていただきたいということをあえて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-024"},{"speaker":"阿部委員","kind":"質問・要望","question":"ただ、今回のやり方については、幾つか質問あるいは意見があります。あれはあれで地価の高い品川区のことですから、非常にお金をかけて取得をしているわけで、そこを有料で、かなり反復的にわりと一部の方々が使用されているとすると、考え方から言えば、建物としてはそんなになくても、やはりコストというのは非常に考えていただきたい部分ではあるんですよね。とりあえず以上の項目をお願いします。","respondent":"榎本企画財政課長","answer":"今後の予定ですけれども、平成２６年度以降は、この平成２３年度に対象とした施設を今度新しいデータでやっていくという考え方なので、平成２６年度は、児童センター、シルバーセンター、図書館のデータを新しくしたものをもう１回入れ替えるということを考えております。","voiceIndex":56,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"それぞれありがとうございました。ステッカーのところは、とりあえずまだ詳細は未定というふうに受け取りました。それでよろしいでしょうか。それから、障害者施設や高齢者施設を入れないというのもわかりました。次にお伺いしたいのが、例えば保育園、幼稚園ということですけれども、これは認可保育園に限るんですか。教えてください。","respondent":"榎本企画財政課長","answer":"ただ、費用としてはかなり出ているものがあるですので、その辺はまた計算データ等の中身を見ながら、どういう形で、施設に表示というのはなかなか難しいかなというところもありますので。","voiceIndex":58,"id":"exchange-026"},{"speaker":"阿部委員","kind":"質問・要望","question":"次の質問を言おうかと思って、いみじくもご答弁で表現があったんですけれども、道行く人たちにこの数字が大きく目立つようなパネル表示が現段階で必要なのかと言ったらちょっと言葉が強いですけれども、まずは、ご答弁の中でも最初にありました。その中で１つのことにお金をかけることに、他の住民の方から、やはり違和感を感じる方もいらっしゃると。その辺の検討はされましたでしょうか。","respondent":"榎本企画財政課長","answer":"やはりこういうコストの表示というのは、個別にやろうと思えばいくらでも個別にやらないと中身がはっきりわからないということになりますので、それをわかりやすさと個別の説明の部分をどこで調和させてこのコスト表示をするかということになりますので。","voiceIndex":60,"id":"exchange-027"},{"speaker":"阿部委員","kind":"確認","question":"といいますのは、これ、海抜表示ステッカーを張るという、ここは未定だということなんですけれども、もしこれをするのであれば、やはり利用者だけではなくて、むしろそれは地域住民の方に見えなければあまり意味がないわけですから、これを張りつけるということは、公道に面してこのパネルを張るのだろうと私は理解してしまったんですけれども、この海抜を張るのであれば。","respondent":"榎本企画財政課長","answer":"今、委員ご指摘あったように、まず初年度やってみて、その反応を見ながら、どういう形でよりわかりやすいコストを表示できるかということは検討していきたいというふうに思っております。","voiceIndex":62,"id":"exchange-028"},{"speaker":"阿部委員","kind":"質問・要望","question":"長くなって済みません。最後は要望に近いものです。この財源の内訳の中で税負担とあります。これは職員の方に研修をされるということなので間違いはないと思いますけれども、ぜひこの施設を利用しているのにこれだけ税金を入れてあげているのよという意識に結びつかないようにしていただきたいと思います。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"この年間経費の合計なんですが、行政コストということを考えると、１年間に施設を維持管理する上で必要な費用を表記するということが建て前だと思うんです。この中に減価償却費、あと、大規模な改修分とかというものもここに入ってくるんでしょうけれども、減価償却は、区のほうは別に法人税をおさめているわけではないですから、ここに減価償却費、これ、一括で建物は償却しているはずですよね。","respondent":"榎本企画財政課長","answer":"１点目のどこまで出すかということなんですが、その地域ごとに違う形ではなく、例えば地域センターであれば、多分区分としては２種類ぐらいと考えております。","voiceIndex":65,"id":"exchange-030"},{"speaker":"須貝委員","kind":"意見","question":"今お話を聞いたんですけれども、建物なんかはやっぱり単年度決算でやっている。実際、民間企業でも減価償却費、もうからないときは０円にする、でも、区としては、いや、これ、建てたからこれだけかかっているんだ。２０００何年に建てました。ここ、どう見たって。その辺はちょっとおかしいと思うんですが、もう１回ご答弁願えますか。ちょっと私は納得いかないんだけれども。","respondent":"榎本企画財政課長","answer":"職員給与費につきましても、当然区職員が１人どれぐらいかかっているのかというのを改めて認識をしてもらって、そういうものがきちんと納税者の負担になっているということも改めて認識をほぼ具体的にさせていきたいというふうに考えています。","voiceIndex":67,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほどのほかの方も言いましたが、何か誤解されたり、何でこんなものを出すんだというような、やはりその辺、私はもう誠心誠意、小出しでもいいじゃないかと思うんですけれども、内訳を出すにしても、何か誤解を受けないように、また、お互いにそれが区民の間で常に話題にあんまり乗り過ぎないように、おまえはどうだ、こっちはどうだというようなことがないように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-032"},{"speaker":"原委員","kind":"質問・要望","question":"私ももう１回整理しますと、まず、ステッカーの件なんですけれども、これはまだ、阿部委員からもお話があったように、全く異次元の問題だと思いますので、もう１回整理をしていただきたいと、これはお願いです。","respondent":"榎本企画財政課長、日下部企画部長","answer":"例えば、財政状況の公表につきましても、問い合わせしてくる方は、これはどうなっているんだという形で問い合わせが何件かありますけれども。私どももやはりそれにしっかりこたえていくという観点で事務事業評価も実施してまいりましたけれども、ただ、おそらくこの先々、財政環境がいい方向に向かうということは、今の経済状況を考えますと。","voiceIndex":70,"id":"exchange-033"},{"speaker":"原委員","kind":"意見","question":"お話は非常にわかるんですけれども、やはりいま一度。それともう１点、再度申し上げますけれども、やはり教育と福祉というのは、いくらコストだと言っても、これはちょっと別かなというところ。特にこの２点、感じるので、この辺の項目、やることはいいと思うんですけれども、この辺をもう少しご検討いただければなと、意見とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":73,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の給与という関係でいくと、委託している部分なんかもありますよね。委託の部分の給与をどうとっていくのかというのが１点。それと同時に、例えばシルバーセンターはシルバーセンターとしたときに、本庁の事務の担当部署がありますね。この分の人件費というのは乗ってくるのか。それともそこだけの部分なのか、そこら辺を教えてください。","respondent":"榎本企画財政課長","answer":"委託の部分につきましては、人件費ということではなく、事業等経費の中で委託費の部分で一括で入ってくるという形です。それから、本庁との部分については、その部分は計上しておりませんので、それぞれの独立した施設ごとをグループ分けしてという形になってあります。","voiceIndex":74,"id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問","question":"シルバーセンターだと、大体がシルバー人材センターの方の委託が多いのではなかったかなと私は思っているんですけれども、そういう方たちがこれを聞かれたときに、どう対応できるのかなというのが非常に疑問があります。そこで今、人件費が出たときに、その人たちの人件費が乗っかっていると見られたら、また困るなということもちょっと感じたのでお伺いしました。","respondent":"榎本企画財政課長","answer":"区の職員の平均値で載せるということで、実際にそういう説明の部分につきましては、これから説明会等やりますけれども、現場での対応というか、問い合わせ先としては、対応できる問い合わせ先等を準備をしていきたいというふうに考えております。","voiceIndex":76,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"窓口の人たちが責められるわけではないですけれども、何か質問を受けたときに非常に気になるなということが今の現状だと思いますので、だれもシルバー人材センターにはほとんどいないですよね。１人か２人、たしか何人かいるはずだけど、その人たちが常にいるわけではないですし、やり方についてもうちょっと検討していただきたいということで、もう１回お答えいただければと思います。","respondent":"榎本企画財政課長","answer":"窓口の対応につきましては、今後どういう形でできるかというのは、所管も含めてこれから検討していきたいというふうに思っております。","voiceIndex":78,"id":"exchange-037"},{"speaker":"塚本委員","kind":"確認","question":"今いろいろお話をずっと伺って、最後にもう一度確認したいんですけれども、目的の公共施設の現状と今後のあり方について、今後のあり方というところで、どういったことを想定されているのかということで、実際の「施設をご利用の皆さまへ」というのを利用される方も見るという中で、内訳と財源とあるんですけれども、要するに、財源がどうなっているかということで。","respondent":"榎本企画財政課長","answer":"やはり使用料等がどれぐらいの負担の比率になるのかというものもきちんとお示しした上で、実際に税でご負担いただいているものがどれぐらいなのかということも含めて考えているところなので、今。","voiceIndex":80,"id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"簡単に質問します。右側のイメージの中で、「○○○○○（施設名）」とありますけれども、これは施設名というのはすなわち、例えば「シルバーセンター」と書くのか、「五反田シルバーセンター」と出てくるのか、どちらなんでしょうか。","respondent":"榎本企画財政課長","answer":"この施設名は、「シルバーセンター」で、（東品川を除く）という形で、東品川が本館で大きくなりますので、東品川だけを規模的には別扱いをして、残りの地区館を同じ扱いで「シルバーセンター」という形で載せたいと思います。","voiceIndex":82,"id":"exchange-039"},{"speaker":"阿部委員","kind":"提案","question":"先ほどの部長答弁の中でも、自分が使っている施設、あるいは区民の方にコスト意識を持っていただく、利用者の方に、区民の方にということがありました。振り返って今日の議論の中で、これだけ行政側の報告事項に対して各会派から、異論ですとか、提案が出てくるというのは、むしろ私、近年にない異例なことかなと思います。","respondent":"日下部企画部長","answer":"今回、区としてこういう形でやらせていただくということでご報告するわけですけれども、実は私ども、さっきも申し上げました事務事業評価とか、一連のそういう取り組みの中で。","voiceIndex":84,"id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"図書館は別棟であるんですけれども、児童センターと併設になっている。そういう場合の表示というのはどういうふうになるのかなというのが、ちょっと聞いていて１つわからなくなったので、そこについて教えていただきたいと思います。そういうところに対して、あえてここに保育園、幼稚園を入れるというところは、もう１つ伺っておきたいというふうに思います。その３点をお願いしたいと思います。","respondent":"榎本企画財政課長","answer":"これについては、まだ一応平成２５年度と最終的になっているのは、やはりいろいろ課題があるだろうというのは認識をした上での最終年度ということになっておりますので、その部分につきましても十分検討をして、どういうやり方がいいのか、要は、実際に示すにしても。","voiceIndex":88,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点でどういうふうに考えたらいいのかということを聞きたいのと、やっぱり１回これぐらい個別に知っていただきたいという話で、よしんば１回掲示したりしても、あるいは、「広報しながわ」なりでここの施設はこうですよああですよというのを出すにしても、通年でこうやって目にさらすというふうなことというのは、やっぱりやめるべきだと私は思います。では、南大井のところを。","respondent":"榎本企画財政課長","answer":"入り口１カ所ですけれども、それぞれの施設の利用者にわかっていただくということで、施設の入ったところ、入り口ではなく、それぞれの施設の一歩踏み入れたところというか、そういう形でそういう施設については検討していく、そうでないとなかなかこのビル全体なのかどうかとか。","voiceIndex":90,"id":"exchange-042"},{"speaker":"金野副委員長","kind":"質問・要望","question":"さらに区民サービスに向上してまいりますというような一文も入れていただきながら、いわゆる経費はこれだけかかっているけれども、さらにそこへ区民サービスの向上に努めていくというような決意文も、決意文だけではない、その思いも加えながらというところはどうなんでしょうか。","respondent":"日下部企画部長","answer":"私の発言に対するご質問ということですのでお答えをします。この表現については、何もこれでがっちりもう１００％固まっているというわけではございませんので、今の副委員長のご指摘の点も含めて、表現についてはまたいろいろ工夫をさせていただきたいというふうに思います。","voiceIndex":92,"id":"exchange-043"},{"speaker":"金野副委員長","kind":"質問","question":"イメージですから、これが固まっていないということは理解していますが、そういったところも含めて、ただコスト意識を皆さんにお知らせするというのではなくて、したからには、こちらも、区民側も、また理事者の皆さんも、やっぱりこのコストで税金によってさせていただいているとか、お仕事させていただいてる、さらに向上をするためにという意識のあらわれが出ないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1904#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":49555,"voices":99}},{"id":"h24-20120124-14","meetingId":"h24-cm01","date":"2012年1月24日","dateIso":"2012-01-24","committee":"行財政改革特別委員会","time":"午後１時００分～午後４時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、特定事件調査を行います。 初めに、(1)の区の組織と関連団体に関すること","agenda":"の１、特定事件調査を行います。 初めに、(1)の区の組織と関連団体に関すること","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この前、質問をして一定のやりとりがあったので、質問は特にないので、ある意味で意見だけになってしまうんですけれども、前回の議論のときにも指摘しましたけれども、品川文化振興事業団、スポーツ協会、国際友好協会などさまざまな外郭団体について、改めて自主事業を見ましても、なぜ外郭団体をわざわざつくらなければこの事業ができないのかと、それが一番の疑問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"質問で１点だけ。品川文化振興事業団、スポーツ協会、国際友好協会、３件に共通して伺います。だから自主性があって、そういう特色を出して青少年ホームステイ事業をやっているのかどうかということの参考にしたいものですから、大まかな部分で構わないので、そのような把握の仕方、結構気にされているかどうかを、この３団体という視点で、雑駁で構わないので伺いたいと思います。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"都との関係ですけれども、スポーツ分野で言いますと、品川区のスポーツ協会の上部団体として、東京都のスポーツ協会、体育協会などそういうところといろいろな連盟とか、共通の事業とか連携事業等も実施しています。友好協会は日本語教室等をやっておりますが、この日本語教室は区内では２カ所ほど日本語を教えているところがありますが、例えば夜間に日本語教室をやっているところというのはなかなか少なくて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"国際友好協会のところで、類似というか、国際化といっても対象とする国や文化というのが無数になる中で、どういうふうに集約をして事業を絞っていくのかというところで、この辺がはっきり見えると、今日の行革の主題である品川区とのかかわりという点で、私たちも理解がしやすいのかなと思うので、もう１点伺うと、現状があって、あと今後という中では、それぞれの議会でのやりとりの中でも。","respondent":"今井協働・国際担当課長、安藤文化スポーツ振興課長","answer":"国際的な運営につきましては、今、品川区としましては、３都市との交流という形でやっておりますので、３都市との交流を、実際に事業をどういうふうに工夫して進めていくかにつきましては。そんな中で高齢者に合ったスポーツというものを拡充しています。","voiceIndex":10,"id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"委員間で話し合いをということで委員長からお話があったんですけれども、まず基本のそもそも論なんですけれども、この３団体、前にも質問したことがあるかと思うんですけれども、公益法人法との関係で、基本的に管轄と公益の財団法人を目指すのか、一般の財団法人を目指すのか、そこだけスタートの段階でもう一回お教えください。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"そして東京都の審査会より、文化振興事業団は９月、スポーツ協会が１０月に、内容について公益財団に値するという答申をいただいております。そしてこの平成２４年４月を目標に、今、準備を進めているところです。ですので、ほかの財団と同様に、平成２４年４月１日には財団法人への移行という予定です。","voiceIndex":13,"id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"そうすると、平成２４年４月１日以降は内閣府に移るという解釈でよろしいですか。","respondent":"安藤文化スポーツ振興課長","answer":"４月１日以降も東京都の所管になります。","voiceIndex":21,"id":"exchange-005"},{"speaker":"原委員","kind":"確認","question":"そうしたら、委員間で話していく上で、今後は先のことを考えるとすれば、５０％以上の公益目的事業を持ったというところをもう一回確認します。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"公益目的事業につきましては、文化振興事業団については、申請当時７２％以上の公益目的事業を、スポーツ協会につきましては９２％以上の公益目的事業です。品川区国際友好協会につきましては、公益目的の事業比率は８６.１％ということで、評議員会のほうでも報告しております。","voiceIndex":25,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど意見を述べさせていただいて、補足をしたいなと思ったんですけれども、先ほど言ったのは、区と関連団体のかかわり方といいますか、その視点で述べたもので、今、行っている自主事業そのものは、むしろもっと重視すべきだなという思いだったので、そこだけ補足させていただきたいと思って意見を述べするんですけれども、例えば文化振興事業団が行っておりますメイプルセンターや美術館やコンサートなど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"１点だけ質問を。聞き方が難しいんですが、行革という視点で、また３団体で聞いていきます。今、指定管理あるいは業務委託となっています。年月がたったときに、現状で事業も大分変わってくるときに、直営で行政が本来やるべきことだけれどもという算定、それと指定管理と業務委託をやるから、こういうコストなりサービスの質という点で、比較的なことというのは、そういう算定はしているのかどうか。","respondent":"安藤文化スポーツ振興課長","answer":"文化振興事業団においても、ここの自主事業に書いてありますように、クラシックや軽音楽というものを区民に低廉な価格で親しんでもらうためにも、ここには書いてありませんけれども、事例で言いますと、ゴスペルの音楽がありますけれども、そこではワークショップをやって。","voiceIndex":30,"id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"細かい数字という求めではなくて、これは区からの助成金も含めての、本来、公益性のあるサービスだからという視点で、指定管理ないし業務委託をしているコスト的なメリット、あるいはサービスの質の向上というメリット、これは直営であるケースを想定しているかどうか。でも現状、５年、１０年たっている中で、既定路線的になっている。","respondent":"榎本企画財政課長","answer":"そういった中で、導入当初は、サービスをどういうふうにしていくかということと事業展開で、区職員が直営でやったほうがいろいろなものに対応できるということでやってきましたけれども、ある程度定例化してくるものについては、区職員でなくても。","voiceIndex":32,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせていただきんですが、この表の見方と考え方をお聞きしたいんですけれども、まず文化振興事業団の区からの助成金というのがあって、その区の助成金という意味から考えると、指定管理、区からのやっていただきたいという内容、業務委託というのがありますね。国際友好協会を見ると、平成２２年度の表のところには、指定管理、業務委託がないんですが、区からの助成金がありますね。","respondent":"久保田行財政改革担当課長","answer":"表の全体のつくりの問題なんですけれども、これは以前、私ども企画のほうで７月、８月等のご説明した表をもとにつくらせていただいておりまして、この区からの助成金というのは、財団とか事業団等に助成金を出して。","voiceIndex":34,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"ということは、本来であるならば、民間でできることは民間にという考え方で言うと、この自主事業のあり方として、採算性のあるものとしてやってほしいよということなのか、それとも区としてもこれらの事業に対しては採算性が合わないが、何かしらの区にとっては有効的な事業の一つになるので、お金をかけて、助成金という形で渡すので自由にやってねということでの意味合いなのか。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"基本的には両方とも受益者負担でやっていって、できない発表会とか、そういう質の高いコンサート等については、低廉な価格で区民の方に楽しんでいただくという考え方です。友好協会の事業のほうも参加者の負担金という形で受講料等をとっておりまして、例えば先ほどご説明申し上げました括弧に入っている英会話教室などは、これは区からの助成金がなくて。","voiceIndex":36,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"そこを押さえていかないと、多分どこにどういうお金を入れなければいけないかというところがはっきりしなくなってしまう。多分いろいろなところで問題というか、指摘されている部分があると思うんですけれども、この考え方は何かはっきりしている、こういう明確な考え方があって助成しているんだよということがあるならば、ちょっと教えていただきたいと思います。","respondent":"今井協働・国際担当課長","answer":"日本語教室ですとか生け花教室につきましては、日本語教室は、やはり品川区の基本方針のほうにも外国人に開かれた社会ということがありますので、補助金という形では多めに助成している形になっております。","voiceIndex":39,"id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"さっきの渡辺委員と似ているところがあるんですが、この３団体において、設立当初は行革の経費削減だったり、あとは民間のノウハウを活かしていく、民間の活力を活かして事業を進めていきたいという、主にその２つがテーマだったのかなと思うんですが、改めてこの団体がやっていて、区が直営でやっていないからこういったメリットがあるんだよというのを、今回、担当課長もいるので。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"スポーツ協会におきましても、総合体育館、戸越体育館について、スポーツ協会の設置目的であります品川区民のスポーツ・レクリエーションの向上のために、スポーツ協会が推進していくという条件が整っておりますので。友好協会につきましては、交流事業というのは、ただその年の事業がうまくいくということではなくて、それまでの交流の経緯を踏まえて、いかにこの事業を効果的にやっていくかというところで。","voiceIndex":41,"id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"この３団体が行って事業をしているから、こういったメリットがある。区民の皆さんに説明をするときに、こういった団体がやっているからこういったメリットがありますよと。だったら直営でもいいんじゃないのという話になってしまうわけで、そういった部分で、例えば設立当初の行革の一環でこれだけ削減できました。はこれからそういった対照をやるつもりがあるのか、改めてお聞かせください。","respondent":"久保田行財政改革担当課長","answer":"一方、こういった文化振興事業団とかスポーツ協会等に指定管理をする等のメリットですけれども、やはり専門性があるといったことと、品川区の状況をよくご存じだということもありますので、一律に事業を展開するのではなくて。","voiceIndex":44,"id":"exchange-014"},{"speaker":"石田（慎）委員","kind":"提案","question":"先ほど西本委員が助成金のことで少しお話をしていましたが、業務委託はあくまで区がその団体にこういった事業をしてくださいよとお願いをして、その事業についてお金を区のほうから助成金として出しているという認識でいいのかなと思うんですが、そうなると、ちょっと先ほども出ていましたけれども、国際友好協会においては、あくまで国際友好協会がこの事業を進めていきたいから。","respondent":"今井協働・国際担当課長","answer":"友好協会と区とのこういう事業の役割分担となると思いますけれども、先ほど申し上げましたとおり、どの都市とも、区と市がそれぞれの方針を立てて合意をした内容に応じて、それぞれの団体にこういう事業のスキームといいますか、大きな枠を示しまして。","voiceIndex":46,"id":"exchange-015"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうなると、友好協会が例えばこの事業はなかなか採算性もとれないといった部分で、やめますと言ったときに、区としてはどのような対応になるのでしょうか。","respondent":"今井協働・国際担当課長","answer":"現状では３都市との協議の中で、公益財団法人の移行に伴って、さまざまに交流のあり方を協会とともに協議してまいりました。","voiceIndex":48,"id":"exchange-016"},{"speaker":"石田（慎）委員","kind":"質問","question":"ということは、その協会がこういった事業は見直しが進んでやめていこうといったときに、区は業務委託じゃないので、そのことに対してどうこうというのを、助成金を出しているのである一定の権限はあると思いますけれども、その辺のやりとりにおいて、区のかかわりというのは、この３つの団体の中で、ほかの２つの団体とは業務の内容が違うからこそ変わってきてしまうのかなと思うんですが。","respondent":"久保田行財政改革担当課長","answer":"補助金については、例えば事業団とか協会からこういった事業をやりたいんだけれども、これに対して助成をしてもらいたいということがありまして、それに対して区が助成をするかどうかというのをきちんと審査をしますし、予算査定の中でも。","voiceIndex":50,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"スポーツ協会がやっている事業についてもそうです。それを単に受益者負担という言葉だけで片づけられては、自主事業ですけれども、本来の目的とは一体何なのかというのをしっかり据えた上で議論していかなければいけないんじゃないかなと思いますけれども、意見を言ってばかりではあれなので、この国際友好協会と品川区スポーツ協会、それぞれご意見を伺いたいと思います。","respondent":"日下部企画部長","answer":"そのことによって文化・スポーツ活動の発展を図っていくということが、これはおそらく区議会の委員の皆様方にもご同意いただけると思いますけれども、これは行政として本来あるべき姿ではないかと考えているところです。","voiceIndex":56,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"そんな乱暴な議論になってきたら、そもそも事業を抱えている交流事業でも、スポーツでも、そのものが成り立たなくなってしまうじゃないですか。冒頭言った部長が言ったのはそのとおりで、本来の事業の目的をしっかりと達成するためにどういう環境をつくっていくのか、その視点をぜひ踏まえていくべきじゃないかという意味で言ったんですけれども、ご理解いただけないでしょうか。お伺いします。","respondent":"日下部企画部長","answer":"それとあともう一方で、すべてご負担いただけない部分については、もちろん税負担も含めて、どこでどうバランスをとっていくか、これが非常に重要な課題であると認識をしております。","voiceIndex":58,"id":"exchange-019"},{"speaker":"西本委員","kind":"提案","question":"今までのご意見を聞いていると、協働事業との違いは何なんだろうということをすごく疑問に思ったんですね。多分国際友好協会の先ほどのご答弁から考えると、以前は協働という考え方がなくて、ここ数年に出てきた話ですよね。そうなると、枠組みはありますよと。じゃあ、それをやってくださいね、やっていろいろな意見を言ってよ、提案してくださいよと、今の協働事業は提案型なんですかね。","respondent":"久保田行財政改革担当課長","answer":"友好協会とやっているこの自主事業については、区の相手側の姉妹都市とか友好都市と交流していきましょうといった中で、公式の交流と、あとは区民と向こうの相手側の市民の友好、草の根運動的なものを担っているという役割分担がありますので、広い意味で言えば。","voiceIndex":60,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"そうなると、やっぱりこれも整理していかなければいけない部分、その上で、なおかつ行政側としては、これについては基金というのではなくて、ちゃんとした助成金という位置づけでやっていきましょうというものが出てこらざるを得ない状況になってくるのかなと思って、今、ここで答えを求めるつもりはないんですけれども、そういう意味では、今、やろうというこの事業の、ほかの団体もそうですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-021"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その視点から考えて、対象者の数、今、明確に何人ですかという答えを求めているんじゃないんですが、３つを比較していったときに、文化振興事業団のやっている事業というのはすごく見えるんですね。品川区とのそれまでの団体のかかわりであるとか経緯もあることながら、それぞれ例えば品川区がどうしても助成金を出してこだわりというか、特色というか、政策的に意味をまず再確認したいのが一つ。","respondent":"今井協働・国際担当課長","answer":"お国自慢料理教室のほうは全体で１００人程度という形になっております。","voiceIndex":63,"id":"exchange-022"},{"speaker":"渡辺委員","kind":"確認","question":"これをよしあしというよりは、先ほど言った政策目的で強い必要性があるかどうかで、事業自体は当然大事だと思うんですね。最初に伺った類似事業という視点もあると思うんですね。その中で、品川区国際友好協会がやることが大事だという視点を確認で伺えればと思っています。その辺、今、国際友好協会の取り組み、区が助成金を出す意味合いを再度強調していただけたらいいなと思って、質問としてお聞きします。","respondent":"今井協働・国際担当課長","answer":"友好協会の日本語教室や区内での事業は、啓発普及事業ということにはなっておりますが、この事業を通して他文化ですとか異文化の地域のことを理解するという形になりまして、ただ日本語教室や英会話教室、そしてホームステイ事業がばらばらに存在するのではなくて。","voiceIndex":65,"id":"exchange-023"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"質問だけ先に。どうしても国際友好協会だけは聞きたいなと思うんだけれども、質問で、課長の感覚でも結構です。国際友好協会の方がいらっしゃるわけじゃないので、課長の感覚でいいんですが、自主事業の１番と２番から話をします。でもやっぱり縮小してきているなと思っていらっしゃるのか、それをぜひ課長の感覚でお聞きしたいのが１番と２番。どうもこれが利用されているとは肌で感じられない。","respondent":"今井協働・国際担当課長","answer":"ですので、今、委員ご指摘のとおり、区としては、地域の国際化、そして国際交流事業、多様な国際交流推進という大きな２本の柱をもって長期基本計画を進めているところですので、このような長期基本計画の中で、区としてもこういう事業が今後ふわさしいということは。","voiceIndex":67,"id":"exchange-024"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"そういう意味では、意図をもって拡大するとか、そういうことをすることを見せていかないと、私が見る限りでは、どうも区長をはじめ縮小だろうというふうに見えるから、何をやっているの国際友好協会、というように私は見えるような気がしてならないので、それはぜひお願いしたいということだけ言っておきます。答弁は求めないけれども、私はそう思っているということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"副委員長からお話があったので、私も、全部が全部ではないんですけれども、同感なんですね。ちょっと確認をさせていただきたいのは、先ほど受益者負担というのは、ある程度さきの２団体に関しても当然ありますし、国際友好協会ということで言ってしまうならば、端的な話をしますと、今回、行財政改革特別委員会ですからはっきり言ってしまえば、助成なんか少なくしていったほうがというのが私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-026"},{"speaker":"西本委員","kind":"意見","question":"ただ１番と２番については、１番は縮小ですよね。むしろやるんだったら、もっと区民の人たちに声をかけていくべきだし、もっと巻き込んでいくべきだと思うんですよ。だけど何か少なく少なく。なので、そういうことではなくて、いろいろな人たちが受け入れるべきものだろうなと思うんですね。３番目の啓発普及事業は、日本語教室っていっぱいいろいろなところでやっていますよね。安いんだと思うんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-027"},{"speaker":"原委員","kind":"確認","question":"確認なんですけれども、委員間ではなくて行政に聞いちゃうのかもわからないんですけれども、区が助成をしているということは税金が入っているということですから、区の関係者には費用が出ていない。会合とかに行っても、逆に団体は持っていないというのは当たり前の話ですよね。","respondent":"久保田行財政改革担当課長","answer":"区の関係者には出ておりません。","voiceIndex":74,"id":"exchange-028"},{"speaker":"原委員","kind":"質問","question":"そうしましたら、さっき副委員長もお話ししていたように、公益性をどんどん目指していくのであれば、今後においてはこういう団体はどんどん独立性を持って、ドネーションを集めるとか、そういう展開をされていったほうがいいような気がするんですけれども、いかがでしょうか、というのが私の考えです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-029"},{"speaker":"山元委員","kind":"質問・要望","question":"それから国際友好に関しては、いろいろお話があって、確かに小さくなっているのかなというのは実感していますが、本当にどんどん拡大していただきたいし、特にこの２番の高校生の夏季語学研修なんかは、これからどんどん海外に出て行くとか、そういう語学に対しても肌で感じるということは大事なことなので、そういう意味では拡大をしていくことがとても大切なんじゃないかなと感じましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-030"},{"speaker":"鈴木（博）委員","kind":"意見","question":"僕も大分年をとってしまったんですけれども、まだ高校生のころに、よく外国との交流で交換事業とかという話がありまして、実際に今、話題になっている国際友好協会なんですけれども、１番とか２番というと、ちょうど僕がまだ若い、中学生とか高校生のころに盛んにやったようなイメージがあって、何かそれをまだ随分引きずっているみたいな感じだなという気がするんですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-031"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"今、鈴木（博）委員がおっしゃったところ、まさに私はここを拡大しろという意味なんだけれども、今、トロントにいらっしゃったというお話でした。それが国際都市品川だと思う。受け入れるほうももちろんそうだけれども、出て行く人の部分は、必ず私はそういう意味で、結果は後になってわかるだろうけれども、拡大していくべきだなと。今、鈴木（博）委員のトロントの話を聞いて余計そういうふうに思った。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-032"},{"speaker":"沢田委員","kind":"意見","question":"３番の啓発普及事業は、いろいろなことをやられているみたいですけれども、交流に関しては、日本語教室は海外から来ている方向けだと思うんですけれども、今はすごく英会話教室も充実していますし、民間でできることは民間でできるという部分もあると思うので、そういったところは民間で、またインターネットでも結構いろいろな英会話の授業とかをやったりしているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-033"},{"speaker":"沢田委員","kind":"意見","question":"無料というのがちょっとどうなのかと思うんですね。使う以上はある程度負担していく部分というのは必要だと思うので、これは区民全体で負担するということになってしまうので、ある程度の負担を、減額していくという部分はいいと思うんですけれども、ある程度の負担はしていかなくてはいけないんじゃないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-034"},{"speaker":"阿久津委員","kind":"確認","question":"担当課長が帰られてしまったので、もしおわかりになれば確認をしたいと思います。各委員にもお聞きしたいことがあるんですけれども、１番と２番に関しては、２５周年とか、オークランド市は１５周年派遣をやっておりますけれども、人数的には増減というのは、増えているんですか、減っているんですか。","respondent":"桑村総務部長","answer":"これは先ほど担当課長が言っていましたけれども、５年ごとにやっていますので、それが５年なのか１０年なのかはまた別として、一定の両市・区の話し合いで、どういう対応するかということが決められるのだと思います。","voiceIndex":86,"id":"exchange-035"},{"speaker":"阿久津委員","kind":"質問","question":"先ほど副委員長からお話があったんですけれども、拡大という点についてなんですけれども、人数とか規模拡大とかを区民に投げかけをした場合に、先ほど原委員のほうからもありましたけれども、ドネーション、寄附ということがあったと思いますけれども、現状ではこれは受けられるのかということと、もし拡大路線となった場合には。","respondent":"榎本企画財政課長","answer":"寄附金は例年いろいろな目的でいただいておりますので、国際友好のために使ってほしいということであれば、その目的に応じた寄附を受け入れて、その事業のほうに充てていくという形ができております。","voiceIndex":88,"id":"exchange-036"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"私の答は、拡大路線はさっきも言ったけれども、区の意識を持って、さっきちょっと剣道の話が出たけれども、私のイメージでは、もし間違っていたらごめんね。たまたまそれはきっかけがあったから。仕掛けるというのは、国際友好協会なり行政側も必要であって、私はそういう民間交流の仕掛けが増えていったときには、もしその助成金が増えるのであれば、拡大で増やしていくべきだと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-037"},{"speaker":"阿久津委員","kind":"意見","question":"行革という場で、海外の方を受け入れる、受け入れないという話、またここから行くという話、増やしなさいという話がなじむのか、政策判断が行革の場でどうかというのはちょっとわからないんですけれども、私も基本的には副委員長がおっしゃっている路線には賛成なんですが、ただ、現状でも何千万円という助成金が出ている中で、これはもう一歩先の話になるのかなということがありますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-038"},{"speaker":"石田（慎）委員","kind":"意見","question":"なぜこれだけ議論になるかというと、やはり中身がいまいち見えてこないんですね。行政も協働・国際担当課長を設置して取り組むのかなとちょっと期待をしたいんですけれども、何かあると友好協会にと、全部友好協会で事業を進めていながらも、実際にそのイベントに行くと、課長が一生懸命頑張っているというのは、どうしても矛盾に感じてしまい、だったら区独自でその事業は進めていけるんじゃないか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-039"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"ちょっと話を変えて、ずっと国際友好協会ばかりじゃ悪いから、文化振興事業団を大きくとらえて、ハコモノの話をしていいですか。ここでも２億５,０００万円なり、これが３億円ぐらいになるのかは別として、そうすると、６億円なり何なりのものがずっとかかってくると。そのときに、じゃあ、どこの段階でどういう方法を打って変えていくのか。おれはつくっているんだろうと思っているけどどうなんですか。","respondent":"日下部企画部長","answer":"区民の皆さん、利用者の方のいろいろなニーズというのも当然出てきますから、それに合わせて、中長期的に、どういうふうに中身を改修するか、あるいはまた、利用しやすいように、区民ニーズの変化に応じてどれだけ利便性を高めていくかとか。","voiceIndex":95,"id":"exchange-040"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"私は、そういう意味であるならば、今すぐやれと言っているのではなくて、４０年ぐらいのスパンで１つの部分を見ていく。それにはこれだけの経費がかかっている。だから、６億円なら６億円ずっとかけていくんですかと。では、その中のあと１５年で７０億円、８０億円。それも、１つの行革の財政的な部分も含めれば、そこに目を向けるべきじゃないのかなと私は思っているということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-041"}]},{"id":"topic-02","title":"の「財政に関すること」","agenda":"の「財政に関すること」","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"１点だけ質問。伺いたいのは、この旧第一日野小学校の跡地の問題です。要するに、新たな進展はあるのか、ないのかということだけですけれども、この間、ＴＯＣの本格的な計画について議論をしてきましたけれども、その後、現在まで品川区に示されたのか、何か連絡的なものはなかったのか、そこだけ、ちょっと伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"第一日野小学校の貸付に関してですけれども、私どもはＴＯＣと協議、連絡はとって、きちんと話し合いはしています。ただ、今の段階でそういう具体的なものをお示しする時期ではないですので、この場では具体的なお話は控えさせていただきたいと思います。","voiceIndex":104,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"この点は、繰り返しになりますので、計画が示されていないＴＯＣの建て替えに協力するよりも、暫定貸付期間が切れます今年の９月ですか、その後は特養ホームとか、認可保育園とか、防災活用も含めた活用を進めるべきだし、１日も早い具体化を求めたいと思います。この大崎や五反田のまちなかは、この地域は認可保育園がとても少ないですから、設置に向けた検討を進めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-043"},{"speaker":"中塚委員","kind":"提案","question":"現状の暫定措置の有効利用についてはもっと積極的に検討が必要だと思いますし、その後については、今の段階では住民要望や行政需要を踏まえながら、引き続きの活用方法も検討を進めていくべきじゃないかなという程度にとどめたいと思います。この場所的、地理的位置で考えると、大崎の駅前ということで、認可保育園の設置を求める声も強い。こういう活用方法で検討を進めていただきたいと思います。","respondent":"武内委員長","answer":"抽象的なお話ぐらいしかできない状況になっております。そういった面で、今回は今出た２つの跡地と、東品川清掃作業所と、この３つに絞って跡地についてはちょっと議論をしたいと思います。","voiceIndex":108,"id":"exchange-044"},{"speaker":"渡辺委員","kind":"提案","question":"質問はないです。税外収入という点で、やはり金額的なもの、小出しなものだったら結構アイデアもあるかもしれませんが、本当にそれが意味をなすかどうかというところで、２つの考え方をあわせ持ったほうがいいと思っています。そんな考え方で、次回ぐらいまでには個別の具体例として何か議会として、個人としてもそうですし、提案ができたらなという思いでおります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問","question":"ほかのフィルム・コミッションでは、それを、いわゆる本当にお金の形では出てこないんですけれども、それをＣＭ効果換算ですか、そういうものに置きかえて出しているフィルム・コミッションもあるというようなことを台東区のフィルム・コミッションの方は言っていたんですけれども、１つそういう考え方もあるのかなということで、先ほどの渡辺委員の話ではないですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-046"},{"speaker":"渡辺委員","kind":"質問","question":"場つなぎ的に。先ほどの中塚委員のところで質問をします。検討会の必要性を説いていらっしゃいましたが、私は真逆で、まず１つ、どうお考えになるのかということ。そもそも、議会は区民の代表者であるという大原則のもと、やはりその意向を聞いて、議会で発信していく役割を放棄するような、区民の声を聞く場をなんて言うこと自体がとてもナンセンスではないかと考えていますので、見解をお知らせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"趣旨としては、前回のご質問と同じなのかなと思うので、回答します。近隣の方々の要望と、全体の行政需要と、ここをしっかりとらえて、跡地活用を考えるべきだということはこの間言ってきたつもりなんですね。もう１つ、品川区はいろいろなツールで動いているという話ですけれども、僕のほうで説明するのも何ですけれども、区政協力委員会だったり、濱野区長になってからは、タウンミーティングですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-048"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"中塚委員に、質問をします。議員同士で討論します。それは、今の現状を生かしていくならそういう意見。現実の部分を区民に任せてばかりいて、「区民の声がこうだから」と言うのは、大義名分、大上段にそういうことをおっしゃるけれども、私は、それこそ、そういうつらいことも議員が言っていくべきだろうと。そこら辺のところのお考えがあれば、ぜひお聞かせいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"半分ぐらいわかっているとは思うんですけれども、とりあえず、そういう住民要望があると。やはりそういう住民要望に沿って検討した結果こういう結果でしたというところまで、まだ詰めていない、議論が始まったばかりだと私は思っています。今の段階でしっかり住民要望を取り上げて、その実現のためにその検討を求めていくというのは、私は正しいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-050"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"ここでお願いしますと。本当は提案権は行政側にあって、その検討はもうされているから、擁壁の部分、下の土地を買う部分、そういうことを含めて非常にお困りになっているし、あれはなかなか手を入れるのは難しいと言っていることをまるっきり信じてない。そこは今、３点言ったのだけれども、そういうふうに思って行政の発言を聞いてらっしゃるかどうかだけ教えてほしい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":118,"id":"exchange-051"},{"speaker":"中塚委員","kind":"意見","question":"この旧大崎第二地域センターに、品川区は小規模特養と、実際はこのグループホームとか複合化でないと運営上とありますけれども、その検討をしたという説明は、区からはありませんよね。特養ホームじゃなくても、認可保育園でも、つまり行政需要にこたえるために検討したというところまで、まだ来てはいない。今、暫定活用として若干使っておりますけれども、その時点をとらえただけであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-052"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"だから、もう１回よく聞いてくださいよ。擁壁をやり変えなくてはならない。下のお宅も買わなくてはならない。それを、先ほども言っているように、信じていないのか、そんなことは聞く耳持たないのか、それは区民要望を吸収していないから、まだそこの部分は後で何とかなるだろうと思っていらっしゃるのか、そこはどうとらえているんですかと聞いているの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言で言えば、もっと何とかならないのかという思いですよ。それは、僕らは執行機関ではありませんし、何か周辺のデータを持ちそろえているわけでもありませんし、あくまで議会ですから、やっぱり、そうは言ってもこの強い住民要望で何とかならないかと。もちろん、今、副委員長が言ったように擁壁の問題で、簡単には何ともならないという説明があるわけだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-054"},{"speaker":"中塚委員","kind":"意見","question":"説明があったわけだけれども、それを踏まえていても、何か知恵はないかと、進めることはできないのかと。では、仮に、必要だけれども進められないとなれば、必要性はあるわけだから、では、近くで何とかならないかと、いろいろな議論の広がりもあるとは思うけれども、今の時点では必要かどうかもあまり発言がない。知恵はないのかという意味です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-055"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"もう、これでわかったけれども、最後、「何とかならないのか」という発言で、議員として発言をされている。わかった。こういう考えをもし違うところでお思いなら違うところを探しましょう」とか、そういう区民の声を吸収して上げてくるのが議員の仕事であって、ただ区民要望を聞いたから行政側に「何とかならないか」と、そういう感覚で中塚委員が思っているということがわかっただけでよかったです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問","question":"特に特養ホームについては、これはあくまでも公益的な施設であって、地域ごとに考えるものではないというのが従来の区の考えですから。でも、私は、お年寄りの方々にもお話を伺ったり、家族の方からもお話を伺ったり、いわゆる生活圏というものがあるだろうと。それぞれの生活圏の中につくる必要があるだろうと。だから、この地域、この地域って大崎第二地域センターの周辺の方々に、できないかと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"だから、この大崎第二地域センターでできないかと。必要性についても、必要性はあると。でも、事情があるのだという話になれば、それは何とかならないのかと簡単に言ったわけであって、必要性があるとわかってくれたならば、では、どうしようかという話に次は臨むわけで、ぜひそこはわかっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-058"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"周りでできないかと。それは議論が大分違ってきていることであって、それは意見を聞いて、今は行革委員会として大崎第二地域センターのこの跡地をどのようにしていこうかという話をしている中で、区民要望がここにあるから、この場所につくれ、それは何とかならないのかと。そういう話を私は委員としてするべきではないと思っている。本末転倒だよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":128,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"個人のために品川区の財産をどうのこうのと言ってくる方がたくさんいらっしゃると思うので、そこのやり方については考えなければいけないと思いますけれども、でも、品川区の狭い地域の中で、昔は建てられたけれども、今は建てられないというところがたくさんあるならば、ここはもう、思い切って、品川区の思いとしては、政策上は無理だというのであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-060"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"そういった意味で、この税外収入に関しては、意識の持ち方というか、それをもっと持っていただきたいなと。その中で渋谷区と品川区を比較した場合に、品川区で同じことをやって、果たして事業主がそれをやってくれるかどうかというのはわからないですが、しかし、品川区においてもそういった部分に関してトライをしてみるといった姿勢も必要なのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-061"},{"speaker":"沢田委員","kind":"意見","question":"いろいろ跡地を見てきて思ったんですけれども、例えば、特養とか老健という施設がこれから区で必要だというのはすごくわかるんですけれども、今ある跡地というのが、それに合っている土地の形だったり、立地条件だったり、そういうものなのかと考えたときにそうじゃないところもあって、それを無理やりそういうことに利用していく、どうにかして利用してということはなかなか難しいのかなとも思っていて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-062"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"無理して採算のとれないものをつくるべきじゃない。多分、民間なり社会福祉法人なり、どういう形のところがくるのかは別として、その方々が、採算が合わないものを選択する。やっぱり、そこは行政目的があったとしても、その跡地を活用して、それに見合う区民サービスというのは多分たくさんあるはずで、そこの選択肢を選んでくるということだけは考えてほしいなというのはお願いだけしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-063"},{"speaker":"渡辺委員","kind":"質問","question":"今日、先ほど、公益法人のところで、公益法人の移行も含めて、３団体、１つの絞った形で伺っていたんですが、最近、会派内でも、地域でも、品川観光協会の話題が、それなりに、聞く機会が多いなと思ったので、これはもう絞ってきた途中なので、ちょっと状況を知るために、所管の委員会もおありでしょうが、やはり同じ流れだと思うんですね。可能かどうか、正副委員長で検討いただければと考えています。","respondent":"武内委員長","answer":"正副でちょっと検討します。次回でいいんですけれども、税外収入のところで、駐車場の貸付を中小企業センターと区のほうが始めて半年ぐらいになりますか。その状況なんかも、もしある程度出ているのだったら、ちょっと教えていだたきたい。","voiceIndex":137,"id":"exchange-064"},{"speaker":"西本委員","kind":"質問","question":"区民の方々が、駐車場を利用したときに、何か意見がきているのであれば、それもあわせて出していただけないですか。お願いします。","respondent":"武内委員長","answer":"また、次回以降そういうのを含めて、ちょっと税外収入等も、検討していきたいと思います。では、ほかになければこれで、「財政に関すること」について終了したいと思います。これで「特定事件調査」を終了いたします。","voiceIndex":139,"id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5916#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":54432,"voices":142}},{"id":"h24-20120125-17","meetingId":"h24-cm01","date":"2012年1月25日","dateIso":"2012-01-25","committee":"震災対策特別委員会","time":"午後１時０１分～午後３時４２分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やっぱり要援護者というのは、命をみずから守ることがなかなか困難だというところで、要援護者の命を守るために行政がどう役割を果たしていくのかということについて、どう考えられるのか、お聞かせいただきたいと思います。品川区の要援護者に対しての全体計画というのは、どういうものを指すのかということについても、お聞かせいただきたいと思います。","respondent":"高山防災計画担当課長","answer":"２点目の総務省の調査、全体計画につきましては、現在、先ほど、ご紹介いたしました要綱の制定をもちまして全体計画としたというような考えでおります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、ここの中身とこの要綱というのが、かなりかけ離れているんじゃないかなと思うんですよ。この国のガイドラインにしても、さまざまな分野にわたって、市町村がこういうことを責任を持って進めてほしいということが書かれていると思うんですが、このガイドラインに沿った、そしてマニュアルというのを、区としてもぜひつくるべきだと思うんですけれども、その点に関しては、いかがでしょうか。","respondent":"高山防災計画担当課長","answer":"具体的な個々人に合わせました避難の計画などを実現化していくといった、取り組みで、災害時要援護者の問題につきましては、対処してまいりたいと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの中では、まず第一に、こう書いてあるんですね、情報伝達と体制の整備というところでは、災害時の要援護者支援班を、市町村が設置をして、平常時と災害時に、こういう活動をしてほしいということを求めているんですけれども、その災害時要援護者支援班というのは、防災部局と福祉関係部局で横断的なプロジェクトチームをつくって、平常時は活動すると。","respondent":"高山防災計画担当課長","answer":"こういった対象者の範疇でありますとか、また、情報の提供のあり方なども含めまして、福祉部門と、障害部門等との会議につきましては、この間、繰り返してまいったところですので、そうした意味での連携というのは、庁内においてとっているという認識でおります。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして災害時には、避難準備情報の伝達業務を、この支援班が行う、そして避難誘導、安否確認、避難情報の把握、避難所の要援護者班をつくって、そこと連携するということになっているんですが、こういう体制というのも、区としても、とられているということでいいんでしょうか。","respondent":"高山防災計画担当課長","answer":"福祉部門との関係におきましては、防災にまつわる広報ということで、要援護者に必要となるような情報を、「障害のしおり」などに載せたりといった形で、情報の共有と、情報の発信に努めているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう形でガイドラインができ、さまざまな分野にわたって要援護者を、どう支援していくかということが示され、また、東京都のほうでも示されているわけですから、これを具体化するために、区として、ぜひこういう形でまとめて、要援護者に対して、こういうふうな形で支援していきますというものをつくっていただきたいと思うんですけれども、そこの点については、いかがでしょうか。","respondent":"高山防災計画担当課長","answer":"震災を受けまして、先ほど、答弁申し上げたとおり、福祉部門と防災部門の定期的な打ち合わせなども、この間、進めてきておりますので、こういったものを明文化できるものについては、方針なり、マニュアルなりの中にうたっていきたいと、そういった考えはあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そしてちょっと、具体的なところでお聞きしたいんですけれども、まず、災害時の要援護者の登録なんですけれども、少しずつ伸びてはきているんですけれども、現在、３,１００人ということで、この内訳は、要介護者と、身体障害者のところも、肢体不自由、聴覚・視覚のところが何人ぐらいになっているのかという内訳がわかったら、教えていただきたいのが１点です。","respondent":"高山防災計画担当課長","answer":"名簿を作成する段階で、対象ということで、重複する部分もありますので、正確な数字ではございませんが、１万人程度に郵送による登録の呼びかけをしまして、その中から応答していただいた３割程度の方が登録した結果、この３,１００人といった数字になってあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区が考える対象者としても、１万人いるということなんですけれども、１万人の中の３,１００人というと、ちょっと少ないのではないかと思うんです。この質問に対しても、一般質問のときは、区長のほうから、研究するという答弁だったと思うんですけれども、そのことに関しては、その後、どういう状況になっているのか、ぜひ拡大していただきたいと思うんですけれども、いかがでしょうか。","respondent":"中山防災課長、高山防災計画担当課長","answer":"ただ、行政側が一方的に対象を広げたといっても、実際には、防災区民組織を中心とした町会・自治会の方にいろいろお願いをするという形になっておりますので、慎重に検討を進めて、門戸を広げるなら、どの部分だというようなことで。逆を返しますと、残りの半分は、こちらからの郵送による意向調査に回答をいただけないような方ですので、その部分は個人情報の関係でありますとか、身近に支援者がいるということもありますので、何とも正確な内訳は。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"対象の拡大というところでは、障害者団体の方々からも、知的や障害が対象に入っていないということを知らなかったと。入っていない要綱を見て、すごく驚いたということで、これはぜひもと入れていただかないと困るということもお聞きしていますので、ぜひ、拡大という方向でご検討をよろしくお願いしたいと思います。","respondent":"原高齢者福祉課長","answer":"そういう中で、３.１１の当日、あるいは翌日の対応のみならず、そういった経験をきちっと検証するということで、私ども、事業者に参加してもらい、またケアマネージャーに参加してもらい、また、特に今回は停電ということもございましたので。","voiceIndex":20,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"今、災害要援護者の議論がされていましたので、私は端的にお伺いするんですが、要援護者の現状把握について、今もいろいろ指摘があったんですけれども、東京都が平成１８年に推定した区の避難者は１５万７,０００人となっているわけですよ。その中で、要援護者登録名簿の対象が３,１００人とは、あまりにも少ないと、私は思うんです。お願いいたします。","respondent":"原高齢者福祉課長、永尾障害者福祉課長","answer":"そういった中で、ひとり暮らしの方については、今、１万人を超えていらっしゃいますし、今後、高齢者はどんどん増える中で、ひとり暮らしの方についても相当数増えていくということで、委員ご指摘のとおり、ひとり暮らしの方を含めて。手帳の所持者数から判断しますと、まず、身体障害者のほうでいけば、１級から３級までを、内部障害も含んだ形で積算をして、あとは愛の手帳の所持者数、精神障害者保健福祉手帳の所持者数、全部合わせますと。","voiceIndex":22,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"確認","question":"そうすると、単純に１万６,５００名以上の方々と推測されるわけです。これは防災の担当の方にお聞きしたいと思うんですが、非常に難しい言い方だと思いながら質問するんですけれども、でもそれが現実なわけですから、その中で、震災対策がまとめをしていくにあたって、品川区の考え方はどうでしょうかということをお聞かせください、お願いいたします。","respondent":"高山防災計画担当課長","answer":"そういった意味で、よい事例を広げて、また町会の加入などを促進するような形で、防災区民組織自体がもっと体力のある若い組織になっていけばと、そんなようなことも含めまして、防災を一つの切り口としまして、防災区民組織の活性化などが図られればと。","voiceIndex":25,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それからもう１点、医療・衛生・福祉の話で、福祉のところで、例えば品川総合福祉センター等々が二次避難所の開設指定になっています。そうすると、万々が一、津波が来ることが予想されるようなところにわざわざ避難所につくるとか、そんなことはしてはいけないわけであって、そのことを含めての見直しは、どう考えていますかということの確認を、お願いいたします。","respondent":"高山防災計画担当課長","answer":"そうした意味で、広域的な津波の想定などは、当然、注視していくということにはなるんですが、この間、区の取り組みとして進めてまいりました区内の標高といったもので、これまで避難所として指定された場所の標高なども明らかになってまいりましたので、そういったものと、今後。","voiceIndex":27,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめますけれども、ずっと私たちが言ってきました自助・共助・公助、これはぜひ、円滑に進めていっていただきたいんですよ。どこが欠けてもいけないと、私たちは思っています。だからといって、税金を全部かけてやれということは、私たちも言いません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"本多委員","kind":"確認","question":"聞きたいことは、２ページ目の名簿登録対象者で、要介護の方を対象に、高齢者などの施設入所者以外の者が名簿登録者で、その中から、希望者であったりで抽出されると思うんですが、この施設入所者とか、施設の管理者が、自分の責任がなくなったとか思わないように、あくまでも名簿登録は、施設に入っていない方が対象だというか、その辺の確認とか、災害が起きたときにどうのこうのではなくて、平時から。","respondent":"原高齢者福祉課長","answer":"しかしながら、いざ今回の３.１１を受けて、お店に物がなくなってしまうといったことなど、なかなか実際に経験しないとわからないようなこともございまして、今回、そういう反省をする中で、買い出しは日常的には必要ですけれども、何かあったときのために。","voiceIndex":30,"id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"高齢者ということで、シルバーセンターを利用しているときに、もし災害とかが発生したときの対応で、それはそれとして、今日の議題とはまた別なので、シルバーセンターにいたときにどうするかというのは、別にしっかり、その視点でちゃんと対策をやっているというのであれば、それで結構なんですが、例えば、２０秒後に地震が来ますと鳴るではないですか、あれがシルバーセンターにいたときには。","respondent":"原高齢者福祉課長、高山防災計画担当課長","answer":"そういった意味では、現在の２０秒後に地震が来るといったところについても、そういった部分で、もし足りない部分があれば、もう１回徹底をする形で、みんながそれに応じて注意できるようにしていきたいと考えています。緊急地震速報の関係につきましては、防災課のほうで予算化しておりまして、そういった意味で、もしも、委員ご指摘のような、案内として不十分な点がありましたら、確認をして対処したいと考えております。","voiceIndex":32,"id":"exchange-014"},{"speaker":"塚本委員","kind":"確認","question":"最初に、ちょっと細かいことで申しわけないんですが、先ほどから、災害時要援護者の名簿のところで、名簿登録の対象者に対して、郵便で通知するという答弁があったかと思うんですけれども、ちょっと念のために確認しますが、例えば視覚障害者とか、そういう方には、それなりの形できちんと伝わるようにしているんですよね、最初に、それをまず確認させてください。","respondent":"高山防災計画担当課長","answer":"本日の資料にはございませんが、要援護者向けの通知につきましては、平仮名表記でありますとか、それぞれの障害の方に判読できるような工夫をしていますので、そういった部分の対応はとれております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。１点確認をいたしたいのは、例えば、現場で負傷者がいて、重篤なので、運べる医療機関に運ばなきゃいけないとか、いろいろなことが起こってくるかと思うんですが、そういったさまざまな事態に対応する命令の指揮系統、現場で、だれがさまざまな手配や、人に対する指示といったことを行うのか、権限者というか、指揮者というか、こういったものはどのように定められているのか、教えてください。","respondent":"高山防災計画担当課長","answer":"それぞれの救護所におきましては、こういった医療救護班の派遣とともに、区の職員も参りますので、そういったものと連携をとりながら、病院等への搬送について、計画を進めるといった対応をとる予定でおります。","voiceIndex":37,"id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういった点も、しっかりとしていただければと思いますので、この点を要望させていただいて、終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-017"},{"speaker":"山内委員","kind":"質問","question":"医療のところについて、伺いたいと思います。なぜそういった質問をするかというと、今回は防災まちづくり事業部、それから、健康福祉事業部、この二つの事業部の理事者の方々がここにおそろいであります。それから、この４師会の先生方と、どのような話し合いをし、それからどのような形でシミュレーションを組み、その組織といったものを整備をしているのかといったところを、教えてください。","respondent":"中山防災課長","answer":"委員おっしゃられるとおりでございまして、今、地域防災計画の見直しの真っ只中ですけれども、その辺が一番弱いところでございまして、もうこれは決まっているんですけれども、今後、医師会との話し合いを進めようということで予定をしています。","voiceIndex":40,"id":"exchange-018"},{"speaker":"山内委員","kind":"意見","question":"今、医師会の方々と話し合いをするといったことでした。僕は不十分ではないかと思います。なぜ医師会だけなのか。歯科医師会、接骨師会、それから薬剤師会、薬を扱うのは薬剤師さんです、お医者さんではありません。その辺は、これから懇談を持とうという中で、なぜその４師会と話し合いができないのか。","respondent":"中山防災課長","answer":"失礼いたしました。４師会と会合を持ちたいと考えています。ただ、今、医師会との話し合いの日程が決まっているです。当然のことながら、４師会と調整を図ってまいりたいと考えています。","voiceIndex":42,"id":"exchange-019"},{"speaker":"山内委員","kind":"質問・要望","question":"は医師会と話し合いをし、そしてその後に、４師会と、という形で理解をしますので、それはちゃんと、そういった懇談がされたというときには報告をいただきたいと考えています。つまり、１３カ所に設置をされるといったこと、これがこのままいくのか。２カ月経ちますと１年になります。この二つの事業部をまたいで、どういった話をされてきたのかということを、もう１回、説明いただきたいと思います。","respondent":"高山防災計画担当課長","answer":"ただ、現段階でお示しできませんというところで、震災を受けまして、庁内においてもそれぞれが主体となって動く必要性は大変感じておりますので、そういった意味で、継続的な打ち合わせというものを持っていきたいと考えております。","voiceIndex":44,"id":"exchange-020"},{"speaker":"山内委員","kind":"質問・要望","question":"先日、３師会の先生方の会合に出ました。ですから、その辺はしっかりと、早急にやらなきゃいけないと、先生方も思っているんですよ。そういったところもありますので、その辺はほんとうに早急にやっていただきたいと思いますので、これは要望いたします。こんなふうに簡単に書いていますけれども、できるんですか。だって、東京全体なんですもの。","respondent":"中山防災課長","answer":"その後で、今、申されました都へ協力を要請するという形になろうかと思いますので、何日間かは、私どもが十分にストックしている医薬品で事足りるのではないかと考えています。","voiceIndex":46,"id":"exchange-021"},{"speaker":"山内委員","kind":"質問・要望","question":"薬といったものは非常にウエートを占めるところなので、そのあたりはしっかりと、品川区のほうで把握をし、そしてしっかりと提供できるような基盤整備といったものを整えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-022"},{"speaker":"渡部委員","kind":"質問・要望","question":"災害時要援護者名簿の作成の部分について、ちょっと前段のお話を少し聞かせていただきたいんです。毎年、更新されていますね。毎年、１万人に調査をしているのか、どうなのかを、まず聞きたい。今日、こういう議論ができる場でしたので、一番最初の取っかかりのときの内容を教えてほしいです。それから、町会に対しても、どのような形でお願いをしているのか、教えてください。","respondent":"高山防災計画担当課長","answer":"そのときに責任の問題などがあるのかといった心配事などは伺う機会がありますので、それにつきましては、そういったことではないといった旨のご説明と、要援護者名簿に登録される方については、そういった旨の丁寧な周知文を添えてお送りするように。","voiceIndex":49,"id":"exchange-023"},{"speaker":"渡部委員","kind":"意見","question":"そうしましたら、一番気にしているところなんですけれども、名簿に載せますか、載せませんかというときに、必ずしも、命の安全、だれかが助けてくれることを保障されているものではないということが明記されているか、されていないかだけ、もう１回、お願いします。","respondent":"高山防災計画担当課長","answer":"非常に直接的な表現にはなるかと思うんですが、趣旨としましては、命の保障をするものではないというような趣旨の文言が添えてあります。","voiceIndex":51,"id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"じゃあ、それ以外は、となる。しっかりと町会にお渡しして、町会でこれをやってくれではなくて、町会どうですかということまでも戻していただいて、例えば、２０５町会ある中で、もしここがおもしろいことをやっているというようなことがあれば、またいろいろな町会に逆に発信をしていっていただきたい。どうやって使っていいかもわかりませんという部分も多いですので、それは要望としてお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-025"},{"speaker":"向委員","kind":"質問・要望","question":"私は、防災アドバイザー研修について、教えていただきたいんですけれども、今、手元にいただいている資料によると、平成１８年度から、年間１００人前後の修了生が出ているということなんですが、これは１回研修を２日間受けて、翌年にフォローアップ研修とか、定期的な再研修があるのかどうか。","respondent":"中山防災課長","answer":"１３０名近く集まりました。ステップアップ研修は、６０名募集しましたところ、やっぱり１５０名ぐらい集まりました。今後は、毎年、防災アドバイザー研修を受けた方が５００人以上いらっしゃいますので、何年間か続けてやってまいりたいと考えています。","voiceIndex":54,"id":"exchange-026"},{"speaker":"向委員","kind":"質問","question":"男女比は、ちょっと気になるのが、避難所のこととかにもかかわってくると思うんですが、町会にいらっしゃるアドバイザーの方であれば、さまざまな区民の声とかも吸い上げやすいかと思うので、男性だけが多いとか、女性だけ多いというわけでもなく、高齢のアドバイザーだけではなく、できれば、三、四十歳代と、若い方もいたらいいなと、ちょっと思ったので、お尋ねしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"先ほど、町会のお話もありましたけれども、まずやってみないと、問題点等も、それでぼろぼろ出てくるのを、また改善するようなこともいいのではないかと思うし、登録者のことに関しても、まず３,１００人ということですが、やっているんだということで、どんな状態なのかということもわかって、また郵送だけではなくて。","respondent":"高山防災計画担当課長","answer":"個別支援プラン、最終的には、全町会でと考えているところですが、なかなかその取り組みが進まないというところで、一昨年度からモデル町会を３町会選定いたしまして、熱心な取り組みをしている町会・自治会の中から、ノウハウでありますとか。","voiceIndex":57,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"できれば、そういう内容等も、我々は知りたいと思うんですよ。どういうモデル地区があって、それはどういう問題があったのかとか、そういう話もみんなで支えていくという意味でも、経過報告等もしていただきたい、そういう要望です、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"ごめんなさい、それはやっぱり質問にさせていただいて、できれば、それをしていただけるのかどうかということをお聞きしたいと思います。","respondent":"中山防災課長","answer":"災害時要援護者につきましては、今度の２月の町会長会議、全地区を回りまして、再度、説明をすることになりました。今日の所長会でお願いをしたところです。渡部委員がおっしゃいましたように、非常に重たいというような感想を持っている方がかなりいらっしゃるです。","voiceIndex":61,"id":"exchange-030"},{"speaker":"金野委員","kind":"確認","question":"私は、まず医療に関してお聞きいたします。防災計画の中の医療体制、医療救護班、これは先ほど、ほかの委員もおっしゃっていました。医師が１名、看護師が１名、歯科医師が２名とか態勢がありますけれども、１３地区それぞれで救護班があって、この人数がある程度確保されるという想定のもとに、このそれぞれの救護所に配置されるものなのか、まず確認をさせてください。それが１点。","respondent":"高山防災計画担当課長","answer":"今後の話し合いの中で、１３地区の班編成でありますとか、交代要員も含めた医療の体制につきましては、順次、詰めてまいりたいと考えております。２点目の助産師のお話につきましては、現在のところは、まだ検討の項目には挙がってございません。","voiceIndex":64,"id":"exchange-031"},{"speaker":"金野委員","kind":"質問","question":"１点目のほうは、これから体制をきちんともう少し詰めていくということですけれども、いわゆる、医師会とか、会に所属をしていない医療機関もあるかと思うんです。そういった医療機関は、言葉は適当でないですが、どういうふうに取り扱っていくのか、どういう協力をしていただくのか。それが１点。災害時には、こういった方々への支援の手も必要かなと考えますけれども、いかがでしょうか。","respondent":"高山防災計画担当課長","answer":"１点目の、医師会に加入していない医療機関の数というのがございませんので、そういうことも含めて研究して、そういった機関に対する効率的なといいますか、働きかけがどのような方法が考えられるかということについては、研究してまいりたいと思います。","voiceIndex":66,"id":"exchange-032"},{"speaker":"金野委員","kind":"質問","question":"ぜひ研究をお願いしたいと思います。次が、難病の患者への支援体制は、どうなっていますでしょうか。いわゆる地域防災計画の中には、難病患者の支援体制というのは、たしかなかったと思うんですが、そこら辺の体制は、どのように考えられていらっしゃいますでしょうか。","respondent":"福島荏原保健センター所長","answer":"現に３月１１日には、呼吸器のついている患者が、現在６名いると、それは東京都と東京電力との連携体制ができているということです。この名簿は、今、３保健センターでしか持っていませんけれども、あとはこれをどういうぐあいに利用していくかというところです。","voiceIndex":68,"id":"exchange-033"},{"speaker":"金野委員","kind":"質問","question":"せっかくそのような体制がとられているのならば、きちんとここにうたっていくべきだと思いますし、また、当然、お考えになっていらっしゃるかと思いますが、発災時には、知っている方だけが知っている体制では支援にはなりませんので、横の連携というところも、もっと強固にされることをお願いしたいと思いますが、その点は、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"そういう中で、それぞれの職場での難病の患者を扱っている、あるいは高齢者、あるいは要援護者を扱っている所管がありますので、そういうところとも十分に連携をとりながら、それぞれの支援者に対して、具体的にどのような支援ができるのかといったところも、事業を継続して。","voiceIndex":70,"id":"exchange-034"},{"speaker":"高橋委員","kind":"意見","question":"町会などに入っていないマンションに住まれている方の中に、３,０００人の中のどなたかがいらっしゃると、しかし、町会長とは日ごろかかわりがない。万が一のときには、やはり助けに行かなきゃいけないと思われている方がいらっしゃった場合は、この辺の名簿の扱いというのは、どうすればいいかわからないので、お尋ねしたいんです。","respondent":"高山防災計画担当課長、片田防災まちづくり事業部長","answer":"ただ、しかしながら平時のつき合いがないということで、なかなかそういう部分でハードルが高いということは承知しているところではありますが、そういった町会加入の促進も含めまして、防災のもう一つの切り口として、地域の活動に興味。やはりプライバシーの問題と合わせて、自治会がまだできていないところが課題だと考えていますので、そこのところについては、逆に自治会への加入とか、設立とか、私どものほうも、そういうことも啓発しながら。","voiceIndex":72,"id":"exchange-035","title":"町会・自治会支援"},{"speaker":"高橋委員","kind":"質問","question":"ということは、管理組合があって、理事長とかがいらっしゃって、今、修繕計画等をやっているところには伝えられるということですか。お尋ねすれば、という話ですか。","respondent":"片田防災まちづくり事業部長","answer":"ご本人のご了解が得られるのであれば、そういうことはできると考えています。","voiceIndex":75,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう方に対して、５,０００人もいるわけですから、ケアマネージャーとか、そういう日常的にかかわっている方を通して、それこそフェース・ツー・フェースで要援護者名簿に登録するということについて、どうかということで、一人ひとりやっていくことが必要なのではないかと思うんですけれども、そのことを一つお聞かせいただきたい。","respondent":"高山防災計画担当課長","answer":"一人ひとりにあたってみては、というご提案につきましては、なかなかマンパワーの限られる中で、どこまでできるかというところもありますので、その点については、できる得る限りの範囲内で対応していただくということが重要かと考えております。","voiceIndex":77,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところで、その方をどう支援していくかというところでは、今回は、ここでは町会とか、消防とか、民生委員とか、そういうところが中心ということなんですが、もっと広い範囲で、福祉分野のサービスを提供している方々とか、そういうところも含めて、一人ひとりに対してどうかかわっていくのかというあたりを検討して、昼間であれば、サービス提供のここのところが支援をしていくとか。","respondent":"中山防災課長","answer":"個人支援プランですけれども、福祉関係では、それぞれの関係で、見守りネットワーク的なものをつくっているです。私どもでやっている災害時要支援者の名簿登録につきましては、それ以外の一般の方々です。","voiceIndex":79,"id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっと今の防災課長の言われ方だと、そういうふうに、ただ名前を書くということではないので、ほんとうに難しい。ただ、現実、じゃあ、どういうふうにしていったらいいのかという議論をしていくというのはすごく大事なことではないかと思っています。そうではないですか。そこら辺のところを、ちょっともう１回、教えてください。","respondent":"中山防災課長","answer":"そういう意味で、私は申し上げたのではございません。福祉部局で見守る人間以外の方々を対象にした、私たちの名簿ですので、その方を対象にして個別支援プランを作成するところまで実施していこうです。","voiceIndex":81,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"福祉分野で見守る方以外のところが、防災課でやるということなんですか。３,１００人というのは、要介護の方が２,４００人も含まれているので、２,４００人は要介護なので、福祉分野になると。それ以外のところは、また身体障害者のことなので、防災のほうで名簿をつくっていくというのは、それ以外のところというのはどうことなんだか、ちょっとよくわからないんですけれども。","respondent":"高山防災計画担当課長","answer":"決してそういった介護の部分と切り離すようなお話ではございませんで、あくまでも名簿登録者に対しましては、先ほど来、ご説明申し上げております防災区民組織、町会・自治会を中心とした個別支援プランの作成といった部分については、変更といいますか。","voiceIndex":83,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者の方が集まって、厚生労働省の委員会の中で話されているところに書かれていたんですけれども、そういう点では、このガイドラインの中にも、市町村の災害時要介護者班が中心になって、各避難所に要援護者用の窓口を設置するように、ということで書かれているんですが、そういう点については、品川区としては、どういう方向になっているのかを、ちょっとお聞かせください。","respondent":"高山防災計画担当課長","answer":"したがいまして、全部の避難所でそういった支援班をつくれるかということにつきましては、マンパワーの関係もございまして、なかなか難しい問題だとは考えております。","voiceIndex":85,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところに対して、やっぱりこれを教訓にしながら、障害者の方々の相談に応じる、また安心して居場所をつくれるというところでの相談窓口をつくって対応をとるべきなのではないかと思うですけれども、そのことについては、いかがでしょうか。","respondent":"中山防災課長","answer":"それから二次避難所なり、福祉避難所へ、今、福祉避難所として、福栄会、品川総合福祉センター、三徳会、さくら会、春光福祉会という区内の５法人を福祉避難所と呼んでいますけれども、ここへ行っていただくということにつきましては、そこでのリーダーなり何なりが指示をして。","voiceIndex":87,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一般避難所では、なかなか生活するのが困難だという方については、あらかじめどういう福祉避難所があるということでお示ししていただいて、そこの中から、はじめからそこの福祉避難所に避難できるという体制をとっていただきたいと思うんですが、そのことについては、いかがでしょうか。","respondent":"中山防災課長","answer":"相談窓口で福祉避難所へ入りたい、移動したいというようなことを……そうではないんですか。そうでないとすれば、相談窓口は相談窓口としてつくって、福祉避難所は別な話ということでいいわけですね。","voiceIndex":89,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害を持った方には、地域の方と一緒に過ごしたいということで、一般避難所で過ごしたいという方もいらっしゃると思うんです。だから、一般避難所に行く、または福祉避難所に行くというのを選択できるようにしていただきたいということなんです。だから、そのためにも、相談窓口をつくっていただきたいということで、質問をさせていただきました。","respondent":"原高齢者福祉課長","answer":"ですから、何かあれば、私どもは福祉避難所に行って、そこで福祉避難所を開設して、福祉的なことが必要な方については、私どもが受け入れ体制をつくるというような仕組みになっておりますので、そういったところで、私ども、あるいは障害者福祉課のほうが。","voiceIndex":91,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、よろしくお願いしたいと思います。それから、福祉避難所では、おおむね要援護者１０人に対して１人の生活相談職員を配置するということで書かれていたんですけれども、これに対しては、生活支援や心のケア、相談を行うということで、専門的な知識を有する者ということで書かれていたんですけれども、品川区としては、どういう職員を考えているのか、お聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"これは時間との状況もあります。最初からすべての体制がとれるわけではございませんけれども、なるべく早い段階で体制をつくっていくといったところが、当然必要ということで認識をしています。","voiceIndex":93,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"質問・要望","question":"端的に質問いたします。医療・衛生のところで、医療衛生班の編成がありました。これは、まず要望ですけれども、医療衛生班の中に、ぜひ女性医師を入れていただきたいという話も聞きました。だけれども、一朝有事の際には、そんなことは言っていられないということもあるわけですから、やはりその辺は、品川区がしっかりとした覚悟を持って対応すべきであると思うんですが、いかがでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"あるいは、防災とかそういう関係機関との協力の中で、どのような対応ができるかということを、まず研究させていただければと考えています。","voiceIndex":95,"id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問","question":"でも、こういう現実の課題が、今、見えてきているわけですよ。もちろん、今の法体系の仕組みを変えることはできないことはわかる、だけれども、もっと踏み込んだ形で、あの３.１１を踏まえたうえでやっていくのであれば、研究ではなくて、さらに具体化していくとか、さらに検討していくとか、そういうふうな答えはいただけないのでしょうかということで、再度、答弁をお願いいたします。","respondent":"片田防災まちづくり事業部長","answer":"確かに、人の生命とか、身体、あるいは財産の保護のために、必要なことはそういう判断ができると認識していますので、そのような場合については、そのような対応をとらせていただきたいと考えて、整理をしていきたいと考えています。","voiceIndex":97,"id":"exchange-047"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もし、そういう位置であるならば、福祉部門だけではなくて、いろいろな部門が関係してくるわけではないですか。そんなことをやっている暇はないわけであって、そのことを議会として変えていくためにも、震災対策特別委員会を設置して議論をしているわけであるので、そのことについて、品川区の改めての考え方と、方向性をお聞かせください。","respondent":"片田防災まちづくり事業部長","answer":"逆に、防災対策、緊急時には全庁の職員を対象とした体制を、区としては組みますので、この計画がきちっと連携がとれるように、今、その課をまとめているのが、私どものほうの防災まちづくり事業部ですので、そこが中心となって調整を図って。","voiceIndex":99,"id":"exchange-048"},{"speaker":"伊藤委員","kind":"意見","question":"もちろん、さまざまな事業が展開されているから、細部については各担当部署なのかもしれないけれども、相当部分については、今まさに、防災まちづくり事業部長がその立場になるのかもしれないけれども、防災まちづくり事業部長のところで情報を集約するなり、仕組みに対処していくなり、そのようなことをして、危機管理課とは言わないけれども、そういう対処をしていく必要があると思うんですが。","respondent":"片田防災まちづくり事業部長、岩田都市環境事業部長","answer":"一朝有事のときは、そういうピラミッド構造の中できちっと指示を流して、情報を集約していくといったような体制をとってまいりますので、計画を作成するにあたっても、そのような体制がとれるように、私どものほうが、今。実態は、全部長級で、区長がトップとなりますので、職員は同じなんですけれども、体制が違うということで、これからもこの体制でいきたいというのが、区の考えになります。","voiceIndex":101,"id":"exchange-049"},{"speaker":"井上副委員長","kind":"意見","question":"一番最初に、防災課で枠組みをされているこの部分とか、そのことをちょっと見ていきたいんですが、まず、名簿というよりも、災害時要援護者の状況把握という意味で、私は、名簿対象者として聞いているのではなくて、どういう方たちが要援護者だと、区として、健康福祉課と防災課のほうで思われているのか、明確な答弁を、どなたかにお願いしたいと思います。","respondent":"岩田都市環境事業部長","answer":"要援護者に対する支援というのは、発災直後から、時間を経由して、内容が大きく変わってまいります。","voiceIndex":106,"id":"exchange-050"},{"speaker":"井上副委員長","kind":"質問","question":"そうなると、防災課が情報をもらって粛々とやる以前に、もう少し広い範囲で、福祉部門のほうでつくっていって、町会の受領証とか、誓約書までを書いた重い仕組みになる前のものを、もっと広げていくという仕組みを、一段階前につくるべきだと思うんですけれども、その点については、いかがでしょうか。","respondent":"岩田都市環境事業部長","answer":"いざ発災したときに、避難所へ避難するのに、自立避難は、どう考えてもできない方、人の手助けを加えない限り、避難所へ行けない方、まず、この重たい方たちを何とか救う方法がないかということで、地域の皆さんといろいろ考えながら、こういう仕組みをつくってきたわけです。","voiceIndex":108,"id":"exchange-051"},{"speaker":"井上副委員長","kind":"提案","question":"助ける人ありきで、ここまで制限しますみたいな名簿づくりでは、やっぱり本来の趣旨には沿わないと思っています。今、そういう団体との協議をされているのかどうか、私も聞いていますけれども、具体的に要望があったからしていくのか、それとも全体の団体とそういう協議が必要という認識を持たれているのか、その辺、２点、伺います。","respondent":"中山防災課長、片田防災まちづくり事業部長","answer":"対象を広げるには、慎重に協議をしていくです。それから、助けてくださいという形ですけれども、こちらがそう申さなくても、町会の方々は、十分にそれを承知されていると思ってあります。そういう時系列の中で、ほんとうに震災時に、その場の中で対応をしなきゃいけないという中では、地域の人とのきずなを含めた共助の体制づくりが必要だと考えています。","voiceIndex":110,"id":"exchange-052"},{"speaker":"井上副委員長","kind":"提案","question":"そこで、思いもよらない声とか、気がつかなかったことというのは、当然あるので、上から目線で助けてあげますよワークショップではなくて、ぜひ、実施をしていただきたいと思いますので、これは要望で、やっていただければと思います。もう一つ続けて質問しますが、先ほど、３.１１で、安否確認を、これもヒューマンネットワークを使って、福祉部門の方たちがされているかと思うんですが、その報告というか。","respondent":"高山防災計画担当課長","answer":"今年度実施いたしました安否確認訓練ですが、安否確認の対象となった方も、訓練の対象者として、後日、記念品を贈呈するなどということで、参加意識を高めてきたところです。","voiceIndex":113,"id":"exchange-053"},{"speaker":"井上副委員長","kind":"確認","question":"そこで、生活保護の方で医療で受給されているような方が、抱えている人数が多いので、そこがちゃんと連絡を取って、今回、安否確認ができたのかどうかというのが、ちょっとほかからも不安の声が聞かれたんですが、そこら辺は、どんな感じになっているんですか。把握されていないのでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"今後の展開の中で、逆に学校避難所への具体的な運営とか、避難とか、そういうところの中にも、訓練の中に、より具体的な中で、もうちょっと深めた形での対応ができるように、今後、工夫をしてまいりたいと考えております。","voiceIndex":115,"id":"exchange-054"},{"speaker":"井上副委員長","kind":"質問・要望","question":"最後に、前回が避難所だったんですけれども、いろいろとお伺いする中で、避難所の中に入って、自分が情報収集困難者であるという方たちにとって言えば、例えば聴覚障害の方たちだと、手話が欲しいとか、手話ができますとか、リバーシブルになったバンダナが欲しいとか、支援を求めていますとか、そういうゼッケンとか、言わなくてもわかるようなものをそろえて、そこに置いておいてくださいというよりも。","respondent":"永尾障害者福祉課長、高山防災計画担当課長","answer":"そうはいっても、情報伝達は必要ですので、区では、聴覚障害者のために、ホワイトボードなんですけれども、磁石になっていて、字を書いてすぐに消せるようなボードを、この間の６月補正のときに幾つか用意してありますので。全員への配付ということにつきましては、費用の面を十分に検証しまして、検討してまいりたいと考えております。","voiceIndex":117,"id":"exchange-055"},{"speaker":"井上副委員長","kind":"質問・要望","question":"どういう形がいいのかというのは、当事者の意見を反映して、それぞれ意見があると思いますけれども、その中でお願いしたいということ。それから、腕章なんですが、５色で各１０枚とか、もう決まってはいるんでしょうけれども、そういうときに、色で違うよりも、もう少しわかったほうがいいのではないかというふうに思うけれども、課題はないのでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"腕章については、これまでも避難誘導ワークショップ等を行っておりますので、その中で、やはり地域の住民の方もきちっと理解していただかなきゃならないでしょうし、協力していただける方に、その中でいろいろどういう出し方がいいのかというところも含めて。","voiceIndex":120,"id":"exchange-056"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"ちょっと情報収集のお願いなんですけれども、先日、都知事の話を聞く機会がありまして、そのときに、知事が言うのには、専門家が言っているんですが、１０分弱に１度の体に感じない地震が、今、起きているということらしいんです。別に見解というと難しいと思いますので、情報収集だけできないかなと思うんですが、もしできれば、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-057"},{"speaker":"伊藤委員","kind":"提案","question":"もちろんまとめることは必要だと思うんですが、これは委員長に聞けばいいんでしょうか、要は、当委員会の提言が、防災計画にちゃんと反映されるタイミングが合うかどうか、これは非常に気になります。私どもがただ提案だけして、それがほとんど反映されてないというのは、それはあまりにもむなしいことでありますので、これは委員長に聞くのが正しいのでしょうか、まずその確認をお願いいたします。","respondent":"飯沼委員長、中山防災課長","answer":"計画とタイアップすると、なかなかどこまで何がわかってということで、非常に難しくなると思うので、とにかくこの議論が有効に生かされる方向でまとめていきたいと考えております。ご提言をいただくために、この委員会をやっているわけですので、当然のことながら、皆様方のご提言を新しい地域防災計画に反映させていくということで、日程的にも、十分に可能です。","voiceIndex":130,"id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6402#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":47230,"voices":137}},{"id":"h24-20120224-3","meetingId":"h24-c-budget","date":"2012年2月24日","dateIso":"2012-02-24","committee":"予算特別委員会","time":"午後３時４７分～午後３時５４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=962#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":2000,"voices":17}},{"id":"h24-20120227-6","meetingId":"h24-cm02","date":"2012年2月27日","dateIso":"2012-02-27","committee":"区民委員会","time":"午前１０時００分～午後０時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１７号議案、品川区印鑑条例の一部を改正する条例","agenda":"第１７号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"実態的なことをお伺いしたいんですけれども、この改正によって利便の増進とと書いてあるんですけれども、具体的にどういうところが利便性ということになるのかということが１点と、もう１点は、これをやることによって事務的な金額がどのぐらいかかって、お金はどういう形で入ってくるのかということと、それと、今、国のほうの法律がもとだと思うんですけれども。","respondent":"梶戸籍住民課長","answer":"そのほかに、多言語対応のために、届出書とか、印刷等を行いますので、その関係で私どものほうでは５９０万円ほど予算を立てさせていただいてあります。","voiceIndex":8,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"今のとちょっと重複するかもしれないんですけれども、住民基本台帳としては、調査をしやすくなるとか、メリットの部分を今聞きましたけれども、この法律改正で外国人登録制度が廃止されるということに対する、これは品川区とか地方自治体から見て国に対してなんですけれども、何か登録制度が廃止されること自体に対する課題だとか、デメリットだとか。","respondent":"梶戸籍住民課長","answer":"ただ、外国人登録法で規定されていました住居とかそういったものの管理については、こちらの住民基本台帳法のほうで管理するのでという形です。そして、もう１つ……。","voiceIndex":10,"id":"exchange-002"},{"speaker":"本多委員","kind":"確認","question":"もう１つ聞きたいのは、これ、どなたでも、日本人でも、例えば何々区から何々区へ転居した場合のデータというのが残ると思うんですけれども、外国人の方たちも、この住民基本台帳の、例えば２３区から転居が何年間のうちにあったりとか、そのデータの保存というのは、自治体ごとにはっきりデータというのが残るものなのでしょうか。日本人同様で扱いが同じということでいいのかどうか、その確認。","respondent":"梶戸籍住民課長","answer":"外国人の方も同じように今度は品川区にいらっしゃった方がほかにいらっしゃった場合については、住民票の除票という形で日本人の方と同じようになります。それは一緒です。","voiceIndex":14,"id":"exchange-003"},{"speaker":"石田（慎）副委員長","kind":"意見","question":"基本的に品川区のほうでパソコン等、全部整備をされて、あとは対象になる方が住民票が必要なときに来て、そのまま日本人と同様の手続をして住民票を取るのか、対象になる方の何か特別な手続が必要なのかどうかが１点。それが要は、今後、１つになると思うんですけれども、その辺の人員配置がどのようになされていくのかが１つ。以上３つお聞かせください。","respondent":"梶戸籍住民課長","answer":"ただ、この事業の内容で、また来年度につきましては、それなりの事務に応じた人員にしてまいります。その予定です。","voiceIndex":16,"id":"exchange-004"},{"speaker":"石田（慎）副委員長","kind":"意見","question":"人員配置のところなんですけれども、これから住民票を外国人の方が取られるときに、もちろん日本語で手続ができない方もいると思うんですけれども、そういった場合の部分での人員配置というのはどのようになられる、今までだったら住民票のところに外国語を話せる人がいなくても、基本的には日本人を対象としているわけで大丈夫だったと思うんですけれども、これからそういったケースが出てくるのかなと。","respondent":"梶戸籍住民課長","answer":"ただし、今後、届出に関しまして、例えば、１、４、８の地域センターも行ってまいりますので、そういった意味合いでは、私どものほうで平成２４年度の１年間につきましては、コールセンターというところと、あと、電話で対応できるようなところ、三者間コールと呼びまして。","voiceIndex":18,"id":"exchange-005"},{"speaker":"石田（慎）副委員長","kind":"質問","question":"仮住民票を郵送する際というのは、それはその対象の方の対象の言語で手紙を送るんですか。それとも英語のみとか、言語のあれはどのような形で郵送されるのか、そこだけちょっと教えてください。","respondent":"梶戸籍住民課長","answer":"つけ加えますけれども、リーフレットのほうも置いてございまして、そちらのリーフレットのほうは、例えば中国語、韓国語、英語、あるいはタガログ語等のリーフレットもありますので、そちらもあわせてご覧いただければという形で対応してまいります。","voiceIndex":20,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっと初歩的なことかもしれないんですけれども、特別永住者というのはどういう方がなられるのかということと、あと、ちゃんとした手続をせずに不法に滞在されてくる方もいると思うんですけれども、今までそういう方も登録はできていたんでしょうかということをお聞きします。","respondent":"梶戸籍住民課長","answer":"ただいま２つのご質問がございまして、特別永住者はどのような方かと申しますと、これ、特別永住者の法律がございまして、簡単に言ってしまうと、第二次世界大戦、戦後日本にいらっしゃった方が、今度は平和条約を結びまして。","voiceIndex":22,"id":"exchange-007"},{"speaker":"山元委員","kind":"意見","question":"すみません、本当に私も初歩的で。品川区の印鑑条例の一部改正のところで、外国の方の印鑑条例ということなんですけれども、何か自分たちの印鑑登録のイメージと外国の方の印鑑登録はどういうことなのかということと、それから、この最後のほうの「氏名等の登録事項に変更が生じた場合の印鑑登録の取り扱いを定める」と、具体的にお話ししていただくといいんですけれども。","respondent":"梶戸籍住民課長","answer":"もちろんお一人１つだけなんですけれども、これはどういった方が、例えばビジネス等で会社を立ち上げるとかいろいろなときに印鑑を登録しないといけない。印鑑証明を出さないといけない、そういったときがあります。","voiceIndex":24,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"意見","question":"賛成。態度表明。いろいろ把握や管理でしっかりされるというところではいいと思うんですけれども、あまり人権とかプライバシーの侵害という声も今のうちからちょっと出始めているのかなと思うので、でも、この印鑑登録については賛成です。大もとのところがちょっと気になります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-009"}]},{"id":"topic-02","title":"第１１号議案、品川区地域センターの設置に関する条例の一部を改正する条例および(2)第１２号議案、品川区立区民集会所条例の一部を改正する条例の２議案","agenda":"第１１号議案、品川区地域センターの設置に関する条例の一部を改正する条例および(2)第１２号議案、品川区立区民集会所条例の一部を改正する条例の２議案","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"荏原第三地域センターと荏原第五地域センター、それぞれ、先ほどは倉庫を地域のものを置くのに使うというお話だったんですけれども、防災用の物資とかというのは、この中だったらどこに置かれているのか。","respondent":"武内地域活動課長","answer":"それについては、今後、地域住民の方と相談しながら、建物の空きスペース等に倉庫等ができればというふうに考えておりますけれども、現在の予定では防災の倉庫はありません。","voiceIndex":37,"id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"これから考えられるということでしたけれども、この倉庫は限られた広さだと思うんですけれども、やっぱり防災用物資というのは、今、区も分散してこれから備蓄していくというお話をされていて、この区の施設にはそうやって細かく分けて置いていくという中で、倉庫が地域のものだけというのではちょっと少ない気もするし、これから相談して決められるということですけれども。","respondent":"武内地域活動課長","answer":"もちろん言われるとおり、防災の備蓄につきましては、本当に近々の課題でありますし、また、今、防災課のほうで早急に地域防災計画を改訂している中で、その辺の備蓄倉庫についても大きな課題になっておりますので、今後。","voiceIndex":39,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"私も防災に関連してしまうので、所管が違っていたら、わかりませんとか、答えられませんでいいんですが、まず、大きい地震が来ると言われている中で、この施設、新しいので大丈夫だと思うんですけれども、耐震に関しては、数字的にどういう、どのぐらいのマグニチュードとか、そういうのが来ても耐えられますという構造になっているか教えていただけますか。","respondent":"武内地域活動課長","answer":"この施設の建築に当たる概要について、その他地域の特性ということで、新たな防火制度の対象区域ということに指定されておりますので、また、特別工業地区ということになっておりますので、私のほうで具体的にどこをどういうふうにしたのかという説明はできませんけれども。","voiceIndex":41,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"いろいろ会議をしたり。昔、私が議員になったころは、地域センターという呼び名ではなくて、出張所と呼んでいたじゃないですか。だから、その辺も踏まえて、これだけのスペースを、今回出てきた２つはとったわけですし、ちゃんと備蓄もし、その辺のことは、もうそろそろというか、緊急課題で考えておいたほうがいいと思うんですけれども、その辺についてはいかがでしょうか。","respondent":"武内地域活動課長、中川原地域振興事業部長","answer":"それと、今後、防災の考え方としましては、言われるとおり、建設の計画というのは２年前ぐらいから話がある中で、その当時も防災については重要事項ですけれども、昨年の３・１１の震災が発生したということで。地域活動の地域センターの所管としては、現状の予定といいますか、こういうふうになっているというレイアウトをお示ししているところでありまして、これを今後どう使っていくかということは。","voiceIndex":43,"id":"exchange-013"},{"speaker":"藤原委員","kind":"意見","question":"基本的な備蓄は各家庭でやるべきだと思っているんですけれども、その辺は各家庭で備蓄をしなくてはいけないですよというか、各家庭で備蓄は今から備えをしていてくださいというような広報というか、そういうものはしていかなくてはいけないと思っているんですけれども、あんまりここをあれしてしまうと、防災課だろうとか、広報広聴課となってしまうからあれなんですけれども。","respondent":"中川原地域振興事業部長","answer":"今、ご意見出ましたとおり、できることとできないことがありますので、やっぱり区としてもここまでは区の役割で頑張るけれども、区民の皆さんにも起きたときは町会が中心になって、とにかく３日間は耐えられるような体制をつくってもらうとか。","voiceIndex":46,"id":"exchange-014"},{"speaker":"山元委員","kind":"質問・要望","question":"それからもう１つは、住所的に荏原第三地域センターは平塚一丁目から三丁目に移ったわけなんですが、その辺、地元の方たち、移転するに当たって、何かご意見というか、それはいろいろな事情があって移るのでそれなりに理由はあると思いますが、意見が出ていれば教えていただきたいと思います。","respondent":"武内地域活動課長","answer":"住所が平塚の変わるという部分ですけれども、平塚一丁目のこの場所については、従来から仮移転している場所については荏原平塚中学校という京陽小学校の前のところの場所ですけれども、ここの場所は従来からある施設ですので。","voiceIndex":48,"id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、駐輪場の質問がありましたけれども、それぞれ何台ぐらい置けるようになっているのかというのと、あと、荏原第五地域センターのこっちに移る前は、新耐震基準だったのか、ちょっとそこをお聞きしたいです。","respondent":"武内地域活動課長","answer":"駐輪場の荏原第三地区につきましては、従来８台が２４台というような形になっています。","voiceIndex":50,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"意見","question":"やっぱり防災の面だとか、道路を渡らないと校庭に行けないとか、そこは教育施設ですけれども、そのときに旧耐震ではなかったものを今のところに持ってこなくてはいけなくなったというのは、やっぱり合築、複合施設にするからだということですので、荏原第五地域センターのところについては共産党は反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-017"}]},{"id":"topic-03","title":"第１５号議案、品川区中小企業事業資金融資あっ旋条例の一部を改正する条例","agenda":"第１５号議案、品川区中小企業事業資金融資あっ旋条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"融資は一般質問でもさせていただきましたのでもう１回しますが、改めて予算特別委員会でもみっちり伺います。改めてなんですけれども、１０年以内という形でやった背景を教えていただきたいのと、こういう長期の融資というのは、２３区で他区はどういう状況でやっているのかということと、それと、この利子補給１.２％というのは、どういうところから来たのか、この数値を教えていただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"１.２％をどういう負担割合にするかですけれども、ほかの区で持っています融資あっ旋のものですとか、３年間０％の緊急融資あっ旋、その辺のところを相対化しまして、一番いい割合にしたです。","voiceIndex":64,"id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"この１０年物ですけれども、予想でどのぐらいの方が借りに来るという形で、予算はどのぐらいを考えているのかということをお伺いしたいのと、それと、また、いつものパターンで信用保証協会がという形になると思うんですけれども、そういうような手続上のことは、この融資も１０年であるというロングというか、長期以外は、ほとんど事務的というか、保証協会で、まず役所に行ってご相談をして。","respondent":"福島ものづくり・経営支援課長","answer":"予算ですけれども、一応、予算上で想定いたしましたのは、平均２,５００万円の融資あっ旋で８８０件ということで予算措置をしているものです。","voiceIndex":66,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"予想で８８０件という形ですけれども、今日は軽く聞いておきますが、この融資、１０年という形にしても、こげつきが出ると思うんですが、改めてお伺いしたいんですけれども、最初からこのぐらいこげつくだろうというような予想というのは、区としては立てるのでしょうか。リーマンショック以来、やっぱり景気が落ち、その前もありましたけれども、その中において、３・１１もあった。","respondent":"福島ものづくり・経営支援課長","answer":"といいますのは、区としてもそれはまず立てることは難しいだろうというふうに思ってあります。信用保証協会のほうでは、それがないようにということで十分な審査もしているというふうに聞いてありますし、そのとおりだと思っています。","voiceIndex":68,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"その辺については予算特別委員会でやりますので、私もそういう意味では、ちょっと複雑じゃないですか、保証協会がといってグラフを見ると、すごい複雑で、どういうふうにお金が流れていくかわからないので、そこを徹底的に勉強してまた質問しますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-021"},{"speaker":"本多委員","kind":"質問・要望","question":"課題についても、今、藤原委員が述べたとおりで全く同感ですので、慎重に進めていただければと思うんですけれども、この目的というものは、もう十分にわかっているんですけれども、文字どおり経営支援をさらに強化するということで、もちろん中小企業の経営が安定することなんですけれども、それ以外に例えば、８８０件を事業を執行した後に、区内の経済がこうなるとか。","respondent":"福島ものづくり・経営支援課長","answer":"今回は１０年物ということで強調していますけれども、実はこの３,０００万円まで限度額を引き上げたということで、いわゆる借り換えをしたにしても１,５００万円の真水が入っていくということになりますので、そうなると、それがまた賃金支払いですとか、物を買ったりですとか。","voiceIndex":71,"id":"exchange-022"},{"speaker":"石田（慎）副委員長","kind":"確認","question":"１点だけ。先ほど、課長の答弁の中にあったと思うんですけれども、これは今まで経営支援を実際に受けている方で、こっちのほうが有効的にできるなという判断をした場合に、借り換えというか、５年物を今回のこれに切り替えるというのは、できるということでよろしいんですか。そこだけちょっと再確認。","respondent":"福島ものづくり・経営支援課長","answer":"そのとおりです。それをねらっております。今まで借りていた人が１０年物にすることによりまして月々の支払いを少なくするということで、しばらく続くかもしれないこの不況を乗り切っていただきたいというふうに願ってあります。","voiceIndex":75,"id":"exchange-023"}]},{"id":"topic-04","title":"第１６号議案、品川区立工場アパート条例の一部を改正する条例","agenda":"第１６号議案、品川区立工場アパート条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"改めてなんですけれども、平成４年のときに開設したわけですけれども、このときは、どういう目的で工場アパートをつくって、そのときに考えていた投資対効果はどういう形で、当たり前ですけれども区の予算が入っています、区民の税金が入っているわけですから、どういうところで投資対効果というものをはかるかということと、あともう１点、２０年、すごく長いですよね。","respondent":"福島ものづくり・経営支援課長","answer":"平成４年につくられたときですけれども、やはりなかなか中小製造業の作業環境が厳しくなってきていると、住宅街が増えまして、従来、工場があった周りが住宅になってしまって、なかなか操業できないというようなことがありましたので、経営基盤の強化および従業員の確保ですとか。","voiceIndex":88,"id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"一般質問でさせていただきましたけれども、特に町工場、商業ではない工業についての支援というのはという話をさせていただきましたけれども、中小零細企業の工業に関しては融資等はありますけれども、この２社のためにすごい手厚いですよね。２社。そしてもう１つなんですけれども、２０年で終わりますよというお話をしたときに、ほかの新規での募集というのは、ちゃんとかけたんでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"ですから、そういう意味では、今この状況で募集して、すぐ殺到して埋まるかというと、なかなか厳しいかなというのは、感想としては、考えとしてはそういうように思っていますので、ですからこそ、新たに公募してもいない場合は１年ずつ延ばしていいですよというものを。","voiceIndex":90,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"担当課長としては、２つに分かれて商業、工業という意味では、工業を担当している担当課長としては、これは条例を変えるということは最善の策だというふうな思いが強くちゃんとあって、このままこの期間を延ばすことが、いわゆる品川の産業発展のためにもつながるという強い思いがあってこういうふうに出してきたと理解してよろしいのでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"はい、今回の条例のこのパターンといいますか、このやり方が最適であると思ってありますし、このまま何もしないで２０年を迎えて出ていってくださいというのは、やはり当初の目的であります工業振興には逆にならないのではないかというふうに判断いたしましたので。","voiceIndex":92,"id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"ほとんど藤原先生がおっしゃったのと同じだったんですけれども、改めて２０年前の情勢と今の情勢と、また全然環境が変わっているんですけれども、工場の状況は違うというのは、目的も、その当初の状況と変わった中でまた目的も変わってきたのかと思うんですけれども、今お話の流れの中で、新しく入りたいと思う方がいらっしゃらないというのは、やっぱり経済が厳しくて、事業の目的という意味では。","respondent":"福島ものづくり・経営支援課長","answer":"確かに目的をどうするかというのはなかなか難しい問題でありまして、２０年前ですと、まだバブルのにおいがしていたころだと思いますので、そのときに計画を立てて、そのときは、なおかつ工場移転、地方にどんどん移転しているというところで、それも止めなければならない。","voiceIndex":94,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、やっぱり今、家賃の話も、さして変わらないのかも、若干安い程度という話でしたけれども、やっぱりこれをやる以上、ある程度の家賃をもうちょっと安くして、新しくやりたいという方がいらっしゃるのは、本当に中小零細、工場等が厳しいわけですから、新しい方が入れる環境をつくっていかないと、さっきおっしゃっていたみたいに、その２社だけを優遇するみたいな話になってしまうと思うので。","respondent":"福島ものづくり・経営支援課長","answer":"ただ、今後、この日本経済がどうなっていくのか、家賃ですとか、物価がもっともっと下がっていくのか、そうなったときにはそうしたことも検討しなければならないのではないかというふうには思ってあります。","voiceIndex":96,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"は３年間延ばすということなんですけれども、いろいろ現状を見たり、声を聞いたりした中でということなんですが、なんで３年なのかというのを教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"やはりこの経済状況を乗り切っていくためには、初め、１年とか２年ということも想定したんですけれども、なかなかそれで回復するのは難しいだろうということで、３年あれば、それまでに退去の方策をとってくれということでやりました。","voiceIndex":98,"id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"確かにほかの委員が言っているように、なかなか公募が来ない、使う人が増えないというところでは、いろいろ改善がまだ必要なのかなと思うんですけれども、やはりものづくりの町ということでうたっているわけですから、さらにやはり増やしていくというほうが本来なのかなとも思いますし、やはり行政が業者を３年、計５年たちました、じゃあ、もうほかへ行ってくださいとなったら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-030"},{"speaker":"石田（慎）副委員長","kind":"質問・要望","question":"いろいろ課長の答弁の中で出てきたんですけれども、改めて現状が実際今どうなっているのかというのを改めて教えていただきたいなと思います。今、入っている業者の方たちだったり、あと、実予算はどのくらいでやっているのかを含めて、改めて現状をお知らせください。","respondent":"福島ものづくり・経営支援課長","answer":"逆に、歳入につきましても、大体両方合わせまして２,３００万円ほど入ってくるというような仕組みです。","voiceIndex":101,"id":"exchange-031"}]},{"id":"topic-05","title":"第１３号議案、財団法人品川文化振興事業団に対する助成に関する条例の一部を改正する条例および(4)第１４号議案","agenda":"第１３号議案、財団法人品川文化振興事業団に対する助成に関する条例の一部を改正する条例および(4)第１４号議案","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"財団法人、公益法人になるところで、今までがどうで、どこがどう変わるのか。","respondent":"安藤文化スポーツ振興課長","answer":"どう変わったということなんですけれども、従来より、今ご説明したとおり、両財団とも公益の一助を展開してまいりました。","voiceIndex":114,"id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"より公的性を高めていくということなんですけれども、高まったというチェック、税金の使い方のチェックというのは、議会でも報告が変わったりとかはするんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、今後、法律に評議委員会の監査機能といいますか、評議委員会が最高決定機関となるように法律が明記されました。ですから、従来と違って評議委員会は、しっかり財団内部の事業ならびに予算、決算を見ていくという形になります。","voiceIndex":116,"id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"今まで評議委員は、理事の方が選べたということなんですけれども、それはこの間、文化スポーツ振興課長が言われた、もらったときのものを読んだんですけれども、理事が選任できなくて、主務官庁が選ぶということになるのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、今後は、この法律に明記されていますけれども、理事会は選ぶことができなくて、評議委員選定委員会という別組織をつくりまして、そこで選定をして評議委員を選ぶという形になっております。これは法律に明記されたところです。","voiceIndex":118,"id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今まで文化振興事業団、スポーツ協会も、議員が評議委員で入っていたと思うんですけれども、それは変わらず入れるということなんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"その理事会、評議委員会が決定をして決めていくという中で、各それぞれ学識経験者ならびにスポーツ協会でございましたらスポーツの分野からだとか、また、体育指導員の方だとか、それぞれ事業団が選定しているものです。","voiceIndex":120,"id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"意見","question":"より公益性を高めるということですので、より区民が参加しやすくなるというふうに考えると思うんですけれども、いろいろな催しをされていると思うんですけれども、もっと参加しやすくするために料金を下げたりとか、もうちょっと施設を増やしていくとか、また、プールなんかも独占されているような声も聞くので、そういったことも改善されていくのかどうか。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で、今、公益認定を受けた後については、より区民の身近なスポーツだとか、文化芸術に親しまれるような形で事業計画を持ってそれぞれ展開していくところです。","voiceIndex":122,"id":"exchange-036"},{"speaker":"石田（慎）副委員長","kind":"確認","question":"１点だけ確認なんですが、公益財団法人、国際友好協会も公益化をされると思うんですが、これ、文化振興事業団とスポーツ協会、今回、２議案ですけれども、国際友好協会に関してはどのようになっているのか、そこだけ確認させてください。","respondent":"今井協働・国際担当課長","answer":"国際友好協会に関してのご質問ですけれども、品川区国際友好協会につきましては、品川区の補助金交付規則に基づいて、今は財団法人品川区国際友好協会補助金交付要綱で補助金を支出しておりますので、条例ではございません。","voiceIndex":124,"id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やっぱりより区民が参加しやすくなるということが公益性が高くなるということだと思いますので、それとやっぱりチェックもしっかりできる環境をつくれるようにしていただきたいなと思うので、意見として言って賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":131,"id":"exchange-038"}]},{"id":"topic-06","title":"平成２４年陳情第１号、品川区の地域の歴史に親しめるまちづくりを一層推進することに関する陳情","agenda":"平成２４年陳情第１号、品川区の地域の歴史に親しめるまちづくりを一層推進することに関する陳情","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"今、区で文化や歴史を携わって取り組んでいることに対して、江戸開府の４００有余年ではなくて、もっとそれ以前のもっと長い歴史を持って重みを持って取り組んでいっていただいていると思うんです。その辺をお聞きしたいのと、あと、大森貝塚を発見したモース博士、人々の暮らしの歴史の深さというのも全く同じだと思うんです。その辺のところを思いを聞かせていただきたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"１点目、２点目あわせて、品川の歴史の重さという部分です。ご案内のとおり、品川というのは、江戸がメインで前面に出されますけれども、品川は歴史のどこを切っても品川が出てくるというように考えています。例えば、古代より縄文時代の貝塚も、モース博士の貝塚がまずあります。","voiceIndex":140,"id":"exchange-039"},{"speaker":"本多委員","kind":"質問","question":"質問ではないんですけれども、やはり歴史というものはものすごく大切なものでありますので、その趣旨をもって、今、区政が取り組んでいるということは十分認識しておりますので、この陳情については、私としては、理解がもう少し具体的なことが挙げていただければよかったなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-040"},{"speaker":"沢田委員","kind":"質問","question":"その辺のご認識というか、例えばいろいろ事実が書かれていますけれども、「誰もが興味を持てるような史実」というのは、「誰もが」というのは、そういう文言もちょっと微妙なところですけれども、だれでも興味を持つかはわからないですけれども、この辺の事実のことに関してはどういう認識をお持ちでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"もう１つ、史実と申しましょうか、ここにも実地教育とありました。そんな中で、指導課のほうに問い合わせ確認してきたところ、例えば、龍馬とか伊藤博文の部分のくだりはありませんが、史実として小学生の３年生と５年生の皆さんには、歴史のことについては教育をしているです。","voiceIndex":143,"id":"exchange-041"},{"speaker":"大倉委員","kind":"質問・要望","question":"この陳情に関してなんですが、私も品川の歴史、非常に今、学んでいるところでありますが、やっぱり愛着、私も２８年間この品川区に住んでいて、まだ知らない歴史もたくさんある中で、やっぱり品川の歴史というのは、非常に興味深いものと、あとは、やっぱりこれからもいろいろな方に知っていただきたいなという思いがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-042"},{"speaker":"山元委員","kind":"意見","question":"本当にこの方の品川に対する思いはすごくわかります。ただ、今、さまざま課長のお話とか、本多委員のお話とか、いろいろ聞いていて、事実とはちょっと、「うん？」という部分があったりして、そう思うと、ちょっと賛同できないかなという感じがします。逆に、その思いは、いろいろな思いがこの方にあるのであれば、課長、ぜひその話は個人的に聞いてあげていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-043"},{"speaker":"藤原委員","kind":"確認","question":"確認をしたいんですけれども、両課長からのさっきの説明の中を伺っていると、陳情の中でこの方のものが、１、２、３というふうには書いていないです。例えばというのにすべてが来ていて、これに関しては、もう区としてやっていますよというふうに私は聞こえたんですけれども、それでいいのでしょうか。","respondent":"中川原地域振興事業部長","answer":"ですから、この方が言っているのは、区民の声であれば区役所としてもきちんとお答えできるんですが、議会に出された陳情として私どもが見たときには、区の立場とか、区がどう考えてやっているというのをお伝えできないもどかしさがやはりどうしてもあります。","voiceIndex":151,"id":"exchange-044"},{"speaker":"藤原委員","kind":"質問","question":"いわゆる史実といわゆる観光というロマンは別ですよと、区という行政という意味において言うならば、史実というのをちゃんと把握してという形なんですよという意味でとらえたわけだと思うんですが、ただ、区としてこの陳情をという形になると、行政としては難しいものもあるということでとらえてよろしいですか。","respondent":"中川原地域振興事業部長","answer":"先ほど来、文化スポーツ振興課長が繰り返していますけれども、歴史館というのが歴史をまとめる所管とすれば、確認できないことを、この方が言っていらっしゃいますような、今の段階で江戸とか、ロマンの部分については、歴史館としてまとめるのは非常に難しいということです。","voiceIndex":153,"id":"exchange-045"},{"speaker":"本多委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。態度については、陳情願意に沿えないということで、不採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-046"},{"speaker":"山元委員","kind":"質問・要望","question":"今日、結論を出していただきたいと思います。結論的には、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"意見","question":"でも、そういうことでやはり区民のそういった声を、やっぱり個人で私たちに言われたところでは、ちょっと私たちもどうしようもないなと思うんですけれども、こういった形で出されて、私としても歴史を深めていく、そして事実というか、明らかにしていくということはいいことなのではないかなと思うので、共産党は採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":160,"id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2628#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":43567,"voices":169}},{"id":"h24-20120227-7","meetingId":"h24-cm02","date":"2012年2月27日","dateIso":"2012-02-27","committee":"厚生委員会","time":"午前１０時００分～午後６時１６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここで聞くのかどこで聞くのかわからないんですが、新設のサービスが増えますよね。それから、これは法のことなのかどうかわからないんだけれども、第２０号議案を見ていて、地域密着型多機能ホームとグループホームの、ここの部分だけ所在地と名称が書いてあるんですけれども、何でこれだけと思ったんですけれども、これは決まりがあって、こうなっているのかどうかわからないので、それだけ教えてください。","respondent":"原高齢者福祉課長","answer":"そのうち定期巡回・随時訪問対応型訪問介護看護と複合型サービスがありますけれども、品川区のほうで、この４月から実施するのは定期巡回・随時訪問対応型訪問介護看護のほうでございまして、いわゆる２４時間定期で訪問する、あるいは。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"新しく入るサービスの中で、複合型サービスというのも、項目としては入っているんですが、これは、品川区は今回はやらないということでいいんですよね。それでも、条例の中には規定するということなのか、そこのところだけ確認させてください。","respondent":"原高齢者福祉課長","answer":"この条例のつくり方として、根拠法がどこにあるかといったことで、根拠を引っ張ってきておりまして、その根拠となるものが、法改正によって項目がずれてまいりますので、例えば特別養護老人ホームであれば、今までの特別養護老人ホームの項目が２項ずれましたので。","voiceIndex":7,"id":"exchange-002"},{"speaker":"若林委員","kind":"質問・要望","question":"第１９号議案のほうですが、全体として、貸付の対象となる施設は、今までと変わらないという、もし違いがあれば、教えていただきたい。それから、その中に含まれますけれども、新のほうの障害者自立支援法のほうで、※社会福祉法改正に伴う削除項の同等サービスを規定ということで、施設としては抜けたけれども、サービスとして入れたと、ここら辺、どういうふうに理解したらいいのか、大きく２点。","respondent":"原高齢者福祉課長","answer":"先ほどの新のほうの障害者自立支援法ですけれども、こちらのほうも、従前ですと、社会福祉法の第２条第２項の中で規定してございましたけれども、そちらのほうが、障害者自立支援法のほうに移行した関係で、障害者自立支援法で、同じ施設というところで規定し直しますと。","voiceIndex":9,"id":"exchange-003"}]},{"id":"topic-02","title":"第２２号議案、品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第２２号議案、品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"鶴委員","kind":"質問・要望","question":"１ページの改正理由のところの1)で、５０人から７０人というところについて、概算で結構なんですけれども、増加傾向とあるんですが、今、何名そういったものがあって、将来的にどのぐらい増えるという、具体的な数字があれば、それを教えていただきたい。第３段階のところを二つに分けたということは、いわゆるこの層の方が、保険料支払いの中でボリュームが大きいというか、そういう理由だったのか。","respondent":"原高齢者福祉課長","answer":"こちらのほうの推計で、審査件数が１万５,０００件ということで予定しておりまして、現在のところでは、なかなか難しいということで、合議体を増やして審査会を実施するです。２点目の段階のところです。","voiceIndex":25,"id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今、新規、更新までは数字を教えていただいたんですけれども、区分変更がどのぐらいあるかも教えていただきたいと思います。それから、今、新第３段階が４,７００人ということだったんですが、前回の１１月のときも、私は、部分的にはお聞きしたんですけれども、すべての１から１３段階までのそれぞれの人数を教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"区分変更の件数ですけれども、こちらのほうは、大きく状態が変わった場合に更新をするというところでございまして、平成２１年度ですけれども１,６００件、平成２２年度が１,８００件、今年の１月現在で、平成２３年度が１,５００件です。","voiceIndex":27,"id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"基金の取り崩しの問題をお聞きしたいんですけれども、第四期のときの基金の取り崩しが、議事録を見ますと、基金が２３億円あるところを、９億円取り崩して、第四期の最後には１４億円残るという計画だったと思うんですけれども、それが実際、どうだったのかということ。それで、何億円から何億円を取り崩して、現在、基金として何億円あるのかということを教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"新たな基金の取り崩しです。１０億７,０００万円、介護給付費準備基金のほうは取り崩す予定で保険料を計算しています。そうしますと、残りについては約８億円程度ということで、推測をしています。","voiceIndex":29,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そうしますと、第四期の保険料の審議のときには２３億円と言っていましたけれども、８億円取り崩して１９億円余っているということですと、第四期のはじめのときは２７億円基金が残っていたという考え方でいいんでしょうか。８億円残すという考え方も教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"こちらについては、大きな災害等々がありますと、保険料がその分入ってこないというところもあります、一方で、給付というところも当然ございまして、そういったことを考えますと、今、４０億円ぐらいの保険料を見込んでおりますけれども。","voiceIndex":31,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"財政安定化基金も、多分、丸々全額取り崩してしまうというわけではないと思うんですけれども、何割ぐらい取り崩して、積立てが何割ぐらい残しておくという考え方なのかということも、お聞かせいただきたいと思います。それが４,７００円ということで、今回、高いほうの保険料設定になったわけですけれども、その理由というのも、教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"そういった中で、国と東京都、それから区市町村という形になりますけれども、特別区高齢福祉・介護保険課長会のほうでも、保険料の部分ということで、一定要望したところですけれども、東京都のほうでは、現在、そこについては検討しているということで、東京都の部分については。","voiceIndex":33,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところでは、現場で働く人たちへの影響がどうなるのかというあたりも、検討されているところがあったら、ちょっと教えていただきたいと思います。第四期のときには、一人当たり、保険料で言えば７８円ぐらいだという答弁がされていたわけですけれども、やはり同じように、７８円ぐらいの分が市町村特別給付という形で使われていくのか、このことについても、お聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"こちらにつきましては、今までは１万５,０００円といったような仕組みになってございましたけれども、今回は、介護報酬の中でということで、例えば訪問介護であれば、そこの部分で４％の加算というような形で、サービス種別ごとに加算がついているです。","voiceIndex":35,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"処遇改善交付金は、ほんとうに継続してほしいと思っていたわけですけれども、これが今年度末でなくなってしまうというのは、ほんとうに残念です。介護報酬に上乗せといっても、わずか１.２％ですし、これはまたぜひ、現場のほうからも声を挙げていただきたいと要望させていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"市町村特別給付の関係ですけれども、こちらのほうは、制度として、横出し、上乗せ、こういったところは介護保険制度の中で、というところが基本となっておりますので、そういった中で、品川区としては対応しています。ご理解のほど、よろしくお願いいたします。","voiceIndex":37,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここのところでは、少しでも軽減を、というところで、今後ともご検討いただきたいと思っています。これは要望です。それから、保険料率の質問をさせていただきたいと思います。そして、あとは２,０００万円以上ということになっているんですけれども、この段階の区切り方、そして、その一つ一つの料率をどういうふうにして決めていくのかという考え方について、お聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"当然のことながら、先ほど、申し上げましたように、国の基準を前提として、区の中の収入の方々がどのぐらいいるかというところを踏まえつつ、こういった形での１３段階の多段階化をさせてもらったです。","voiceIndex":39,"id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回、２００万円から、国の基準で１９０万円に引き下げるということで、そこのところも、それにあわせて変わっているわけですけれども、国の考え方は、２００万円から１９０万円に引き下げた理由というのは、どういう理由なのか。それから、国の基準でも、８００万円から２,０００万円と一足飛びにこういうふうな形に、その施行令でもなっているんでしょうか。","respondent":"原高齢者福祉課長","answer":"国の考え方ですけれども、２００万円を１９０万円です。こちらについても、負担感ということの中で、この金額を下げてきたということで理解をしています。","voiceIndex":41,"id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それで、後期高齢者医療保険料の場合は、１６８万円までの人は６,０００円で済んでいるわけですけれども、８０万円といえば非課税ですから、本来であれば税金がかからないというところで、こういうふうな形で、後期高齢者医療保険料は、年額４,０００円で済んでいるわけです。１０倍になっているんです。そこら辺のところの考え方については、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"そういったところを、区のほうでは、０.４ということでございまして、制度の枠の中で、それにより難い場合は、ということの中で、０.４ということでの料率を設定させていただき、また、今回の中でも、比較的負担感の高い部分についても。","voiceIndex":43,"id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところでは、ぜひ、この逆進性の強い保険料というところで、今回、品川区としても能力に応じた負担になるように改善をしたということで、１３段階ということで、考え方としては、そういう考え方が出されてきていますので、ぜひこれをさらに、能力に応じた負担になるという改善をしていただきたいと思いますけれども、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"国のほうでは６段階を分けてございまして、一番所得が多い方でも４分の６ということで、１.５倍が国の施行令、それが基本となっていますので、先ほどの５５万円ですと、うちでいきますと、１０.何倍というような形というのは、国の施行令から考えても。","voiceIndex":45,"id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"介護保険料というのは、今でも、これだけ限界という状況だと思うんです。そして、取り崩す基金も限りがありますし、そういう点では、高齢者の状況を考えて、ぜひとも、区のほうから応能負担、もう既に１.５５というのを２.８までしているわけですから、これをさらに応能負担というところを提案をしていっていただきたいと要望をさせていただいて、とりあえず、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"なぜなのかと。だけれども、何で旧の第４段階と第６段階が下がっちゃうわけですか。そこの料率の問題を、ちょっと教えていただきたい。それから、４,７００円って、多分これは頑張っていらっしゃる、それでこれぐらいに押さえられたと思うので、今もう、大体全区出てきたんでしょうから、２３区の中でどれぐらいにいるかというのは言いたいんでしょうから、それはぜひ伺っておきます。","respondent":"木下健康福祉事業部長","answer":"非常に安い金額でありまして、全部正式に議決された後、数字をお示しする機会はあると思いますけれども、これは、この間の品川区のサービス供給体制、必要以上には出さないけれども、逆に足りないことはないという適切なマネージメントの結果でありますので、そのことを。","voiceIndex":48,"id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"２番目は強く言いたいのかなと思っておりました。そうすると、例えば生活保護にこれだけ金がかかっていますよなんて言うと、何だよ、ふざけるなとなる人たちなんですよ、負担を多くしているんですから。そういう人たちには、やっぱりしっかり、もうちょっとこういうときには丁寧に説明をするべきだと、これだけはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"第２号被保険者の方が、第四期は３０％から２９％に下がった。ここら辺の国の出してきたものと、今回、区の議案に出ている保険料の実態が、どういうふうに影響しているのかというのは、私たちはちゃんと理解しなきゃいけないと思いますので、教えていただきたいと思うのが一つ。ここを、全体的に、ちょっとお話をいただければと思います。","respondent":"原高齢者福祉課長","answer":"当然のことながら、それに応じて、区のほうで、２１％の第１号被保険者の保険料の負担で計算をし直しますと、向う３カ年の保険料の負担を考えまして、４,７００円ということで設定をさせていただいたところです。","voiceIndex":51,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、今後、基金の積立てというのですか、しっかりやっておかないと、今回は４,７００円で、低い所得の方にも配慮して、また、高い方にはこれからご理解をいただいていきますということで、また早い話で申しわけないんですが、今度第六期になったときに、基金があるかないかで、大変重大な局面というのですか、大変な混乱になることも予想されますので、基金の考え方と、今後３年間の、平成２４。","respondent":"原高齢者福祉課長","answer":"区のほうでは、今まで、そういった考え方の中で、こういった基金を残す中で、１０億７,０００万円を、第五期の基金の投入額ということで、これによって約４００円の保険料の引き下げになっているです。","voiceIndex":53,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"基金を１０億７,０００万円取り崩すことで、４００円引き下げになるということでしたけれども、それは財政安定化基金の２億２,０００万円も入れて、４００円という考え方になるのでしょうか。だから、今回の基金の繰入れは、トータルで１３億円弱になるんですか。それで、４００円の引き下げになるのか、そこのところをちょっとお聞かせください。","respondent":"原高齢者福祉課長","answer":"財政安定化基金は別でございまして、そちらのほうは約８０円の保険料への給付ということで考えているところです。","voiceIndex":55,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、では、介護給付費準備基金で４００円で、財政安定化基金で８０円で、合わせて４８０円の引き下げということになっていくんでしょうか。そうすると、もともとの保険料というのは、前は、第五期の推計保険料が５,０５３円ということだったんですけれども、これそのものも、もうちょっと上がっているということなんでしょうか、そこのところをお聞かせください。","respondent":"原高齢者福祉課長","answer":"先ほど、４,６００円から４,７００円というご質問の中で、地域加算の見直し、それから介護報酬が確定した等々で推計しまして、推定の保険料を５,０５３円から５,１８１円ということで、現在のところ、推計しておりまして、その中で、財政安定化基金、それから。","voiceIndex":57,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほど、若林委員からも第六期の話が出たので、ぜひここで、一つだけ言っておいてほしいのは、今、４,７００円と。だけれども、先ほどいったように、今、１０億７,０００万円使うと４００円くらいですよと。だって、そういうふうに見込んでいるんだろうから、一言ぐらい言っておかないと、３年後に大きな議論になってしまうから、今一言だけ言っておいたほうがいいと思います。","respondent":"原高齢者福祉課長","answer":"委員ご指摘のとおり、基金が約８億円の残というところで計算していきますと、第五期が、どれだけ給付が推計どおりになるかどうかというところでございまして、この推計の動きによっては、基金が全く積立てができないということも、当然考えておかなくてはいけないということで。","voiceIndex":59,"id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保険料の考え方というのが、応能負担ということで、能力に応じたということで、今回、品川区のほうでも出して、１３段階ということにしていますけれども、そういう点で言えば、料率というところで、所得の少ない人ほど料率が高いという状況になっていますので、ほんとうに能力に応じた保険料にする、そして大もとのところを改善していかない限りは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-023"}]},{"id":"topic-03","title":"第２３号議案、品川区立心身障害者福祉会館条例の一部を改正する条例","agenda":"第２３号議案、品川区立心身障害者福祉会館条例の一部を改正する条例","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"これは、必ず皆さん思っていると思うんですけれども、さっきもそれが出たので、具体的には、心身障害者会館が、これでどういうふうになるのかというのを、ついでに説明してくれると非常に助かります。これだけ何項から何項と言っても、よくイメージがわかないので、今の心身障害者福祉会館は、多分皆さん大分イメージは持っているので、それがどういうふうになるのかということを、ちょっと教えてください。","respondent":"永尾障害者福祉課長","answer":"ちょっと説明が不足しておりまして、申しわけありませんでした。会館のほうですけれども、まずは、障害者地域活動支援センターというものですけれども、こちらにつきましては、３階の部分に少し集える場所をつくろうかと考えております。","voiceIndex":73,"id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この件は、私も一般質問させていただいたので、今おっしゃったとおり、サービスも増えていく、スペースをつくろう、ほんとうにこれは手狭だと思うので、大変だと思いますが、よくいろいろ総合的に検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"障害者自立支援法が、ほんとうにいろいろと変わってきていて、仕組みが複雑で、なかなかわかりにくくて、私もいろいろと勉強してみたんですけれども、それでもなかなか理解するのは大変だなと思いながら、ちょっと質問させていただきたいんです。そういう中で、今回は第一歩という形になるのではないかと思うんです。","respondent":"永尾障害者福祉課長","answer":"今後につきましては、かといって、高齢者と全く同じようにすることは非常に難しいわけですので、一人ひとりかなり症状等も違いますので、家族関係だとか、そういうところも全体を含んで、一つ一つ相談に乗っていくような形になると思います。","voiceIndex":76,"id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"ほんとうに、現場で多分大変なことだろうなという思いがするんです。そうはいっても、こういう法律で位置づけられて、心身障害者福祉会館１カ所だけで、３年間の間にすべての方をやっていくということになると、とても足りないということになると思うんですけれども、そこら辺のところを、とりあえずは今回、一歩踏み出して、その後から考えていくということになっていくのか。","respondent":"永尾障害者福祉課長","answer":"資格の部分ですけれども、こちらもご指摘のとおり、きちんとした国家資格ではなくて、実務経験が、その経験している場所によって、３年、５年、１０年とかに分かれておりまして、それプラス、あとは初任者研修を５日程度、それから。","voiceIndex":78,"id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"いろいろと現場では大変なことを、一つ一つクリアしながら充実をさせていくということになっていくと思いますけれども、ぜひ、充実の方向でよろしくお願いしたいと思います。既に位置づけられているのであれば、どんなメンバーがいて、どんな活動をしているのかということについてお聞かせいただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"今回の法改正がおととしの１２月に出たところから、やはりもう少し自立支援協議会の活性化をしなければいけないということ、障害に関しては、区と社会福祉法人、地域のＮＰＯ等、それから民生委員もそうなんですけれども、チームを持って対応していかないと。","voiceIndex":80,"id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"最後に１点、お聞きしたいのが、第６条の２の使用料のところなんですが、利用者は材料費等の実費を負担するということで、今まではどうなっていたのか。それから、障害者地域活動支援センターの創作的活動と生産活動、それから社会との交流促進というのが、イのところに書かれているんですけれども、この中身についても、教えていただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"今までもやってはいるんですけれども、内容につきましては、さらにいろいろな障害に対応できるような内容を、今、検討しております。","voiceIndex":82,"id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、基本的には、今までと変わらないということでとらえていいんでしょうか、材料費の実費という点では。","respondent":"永尾障害者福祉課長","answer":"ちょっと説明が漏れてしまいましたけれども、今までと同様です。障害者地域活動支援センターになるということで、今までと全く同じ講座の内容にするのではなくて、もう少しいろいろな障害に合わせた講座を、今、組み直しをしています。","voiceIndex":84,"id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"自立支援が入ったということで、障害の種別なく、ということで、当然、いわゆる身体から、精神、発達障害等々、すべてのケアプランということで理解をするんですけれども、そうすると、各障害、種別それぞれの、ほんとうのスキルアップを図って、ケアプランを適切に、また当事者と相談をしながらつくるには、特にまだ新しい障害である発達障害も含めた、職員とか、また民間の法人との連携といいますか。","respondent":"永尾障害者福祉課長","answer":"ただ、そういうのがすぐに身につくというのは非常に難しいことですので、そういう検討を受けて、またさらに、自立支援協議会での専門部会の検討なども含めて充実させて、少しでもスキルアップをしていきたいと考えております。","voiceIndex":86,"id":"exchange-031"},{"speaker":"若林委員","kind":"質問","question":"わかりました。今後のプランの策定にあっては、関係機関等も含めて、しっかり区として、ある意味では、マニュアルというのでしょうか、サービスが必要な方へ、というところで、どういう方が対象になるのかというところも含めたガイドラインというのでしょうか、そういうものをしっかりと提示をして、また委員会にもご報告いただくということで理解してよろしいでしょうか。","respondent":"永尾障害者福祉課長","answer":"国のほうでも一定のガイドライン的なものは出すのではないかというお話も聞いておりますので、そちらも参考にしながら、区としての考え方を決めていきたいと考えています。","voiceIndex":88,"id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"障害者地域活動支援センターなんですが、身体障害者福祉法のＢ型からこちらに移行するわけですけれども、Ｂ型では、定員が何人あって、今度の障害者地域活動支援センターでは、何人ぐらいの定員になるのかということ。そこら辺の中身について、ちょっとお聞かせいただきたい。それから、障害者地域活動支援センターの生産活動というのは、どういう中身なのかも、ちょっと教えていただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"多少の余裕も持たせながら、希望があればなるべく受けていただけるような形をとっているものです。就労移行支援につきまして、４月からげんき品川のほうに移るということで、今、保護者にもご説明が終わりました。","voiceIndex":90,"id":"exchange-033"}]},{"id":"topic-04","title":"第２６号議案、品川区立児童学園条例の一部を改正する条例","agenda":"第２６号議案、品川区立児童学園条例の一部を改正する条例","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"基本的に、午前中の話になりますけれども、全体的に事業、サービスに変化はないということを、しっかりと確認させていただいたうえで、新しく（福祉型）児童発達支援センターになりますけれども、いわゆる法律のほうでは、このセンターというのは、地域の中核的な療育支援施設という位置づけで、おおむね１０万人に１カ所のイメージというふうにありました。","respondent":"永尾障害者福祉課長","answer":"ただし、３年間の経過措置の中で、健康福祉事業部だけでなく、子ども未来事業部、そのほか、教育関係、そのあたりの連携なども必要になってきますので、検討を進め、３年後に備えていきたいと考えております。","voiceIndex":117,"id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これが改正された背景というのが、どういうことで改正になったのかということ。それから、中身は平成２４年度は変わらないということなんですけれども、３年間のうちにどういうふうに変わっていくのかということと、センターの体制がどうなっていくのかということについてもお聞かせいただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"もし変わることがあれば、逆にそういう状態を保育園等から受ければ、回ってくるという形を、今もとっておりますので、この辺については、この３年間の検討ということと、それから政令がどう出てくるのかとか、その辺を含めながら考えていきたいと思っています。","voiceIndex":119,"id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"このセンターを使うにあたっては、利用料というのは発生することがあるのか、どうか。ちょっとそのところだけお聞かせください。","respondent":"永尾障害者福祉課長","answer":"利用料金につきましては、保護者の負担については、現在と変わりはありません。ただ、法的な整備の中で変更になっていまして、今までは障害者自立支援法の中で規定されていたのが、障害者自立支援法のその条項が廃止されて、児童福祉法にそのまま動いているような状態です。","voiceIndex":121,"id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひ、これはお願いをしておきたいんですが、今の、気にかかる子の話なんですけれども、多分、小学校も、私立幼稚園協会、幼稚園も、どこも困っているんです。連携をとっていくのはいいんですが、親が認めてないわけですよ。そこら辺の基本的な考え方を持っておかないと、ここだけは、ほんとうに親が認めてないわけなので、そこら辺の考え方だけちょっと、もし今、お考えがあるなら、教えてください。","respondent":"永尾障害者福祉課長","answer":"というのは、今までと仕分け方が違う部分がありますので、例えば子ども未来事業部としたときに、障害のことはあまりよくわからなかったり、教育委員会も同じような状態ですので、このあたりがやっぱり、３年間の間に調整すべきところかなと考えているところです。","voiceIndex":123,"id":"exchange-037"}]},{"id":"topic-05","title":"第２７号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第２７号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"国民健康保険が、毎年毎年値上げということで、ほんとうに大変な負担になっているんですが、先ほど、９ページのところで、一人当たりの２３区の平均では７９８円の値上げのところが、品川区の場合ですと、４,５４４円ということで、収入の多い方が多いために、２３区平均よりも、４.５倍の値上げ幅になってしまうということなんでしょうか。","respondent":"本城国保医療年金課長","answer":"先ほど、旧ただし書所得が１.３％下がる見込みだということで、８ページの下に２３区の動向を書かせていただきましたが、これについては、区によって所得の動き方の見込みも違っているところもありますので、２３区平均だと、このような状況ですが、品川区の場合は。","voiceIndex":137,"id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"滞納世帯というのを教えていただきたいんです。これはかなり増えてきているのではないかと思うんですけれども、滞納世帯がこれまでに増えたということに対しての区の認識を、ちょっとお伺いしたいと思います。それから、あらためて短期証、資格証、差し押さえ件数、その数字も教えてください。","respondent":"本城国保医療年金課長","answer":"滞納といいますか、収納の関係ですが、毎年、年度末に滞納状況だとか、集計する中では、今、ご説明いただいたような、平成２２年度末には、１回でも滞納がある世帯の数ということで、２５％ということになっておりますが、ただ、収納率は。","voiceIndex":139,"id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"資格証のことについては、いろいろなところで、毎回言わせていただいているんですが、払える能力があるにもかかわらず払わないという確認を取れたところでされているのか、そのことについてお聞かせいただきたいと思います。差し押さえなんですが、１４９件はかなり増えているという感じがするんですけれども、この中身についても、教えていただきたいと思います。","respondent":"本城国保医療年金課長","answer":"資格証の発行についてですが、これについては、保険料の未納が発生した段階から文書、あるいは電話等、可能な限り連絡をとって、ご本人の状況を確認して、最終的な形として、どうしても一切連絡が取れない方について、場合によっては資格証対応にしたりするということです。","voiceIndex":141,"id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、こういうときも、区民の、どういうふうに値上げがされていくのかということがわかるようにという数字では、住民税方式から旧ただし書き方式に変わったときに、大きく制度そのものが変わって、保険料が変わったわけですから、そこのところもここに一段出していただけると、どういうふうに保険料が経年的に変わるのかというのが見えるので、ぜひ、そういう資料を。","respondent":"本城国保医療年金課長","answer":"先ほど、経過措置後の額が、また大幅に上がるのではないかというご指摘もございましたが、これについては、どういう形の経過措置をすることが本則に至るうえで一番円滑かということは、なかなか難しいところですが、逆に。","voiceIndex":143,"id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"しかも、２５０万円といったら、年収ですから、３人世帯で２５０万円で、１２万９,０００円から２２万６,０００円へ、３年間で値上げというのは、あまりにも過酷だと思うんですけれども、そういう値上げに対しては、これでも軽減しているんだと言えるのかと思うんですけれども、その値上げ幅のあまりの大きさ、しかも、こういう所得の人に対して、そういう点に対しては、いかがでしょうか。","respondent":"本城国保医療年金課長","answer":"ただ、移行期については、なかなかどうしても、それによって不利益といいますか、上げ幅が大きくなる方もいますが、それについては、これも繰り返しご説明していますが、旧ただし書き方式自体、もう平成２５年度からすべての自治体で完全にやらなければいけないという中で。","voiceIndex":145,"id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"経過措置ということで言われますけれども、しかも、それも一般財源をさらに投入したというわけではなくて、高額療養費のほうを回すという形でしているわけですから、ぜひこれは、経過措置を継続して、これ以上の値上げにはしないという方向をご検討いただきたいということで要望させていただいて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、これだけ生活保護も多くなってきている。ここら辺のことを、どうお考えかというのをまず聞きたい。議論するときに、もうこのぐらいにしようということはできるわけですから、だけど、安易に所得割で、さっき言った、所得が高い人からどんどんもらっておくというふうにしておけば、所得割が増えていくわけで、ここら辺も含めて、どう考えていらっしゃるのかというのは、お聞きしたい。","respondent":"本城国保医療年金課長","answer":"経過措置の関係ですが、あくまでも、社会保険制度としての国民健康保険にとっては、平成２３年度からやっている旧ただし書き方式が制度にかなうということで、平成２３年度からそのように移行していますが、経過措置は、あくまで文字どおりの経過措置ということで。","voiceIndex":148,"id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ、そこでお考えをしっかり持っておいてほしいと思うのが一つ。それから、もう一つ言いたいのは、これは瑣末な国会の議論も含めて、政局がらみだと思うけれども、１割を２割にしていこうって、普通に言えばよかったんですよ、これは、お金がないから。だけど、ここに書き込むわけじゃないですか、こうやって。それは、ぜひ、強い意識を持っていただきたいという要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、そういう中では、７０歳から７４歳、無料にこそしてほしいと思っています。だから、２割に上げるなんていうのは、しかも２倍ですから、高齢者の実態を考えたら、そんなことはとんでもないと思います。ぜひとも、区としては１割のまま続けるようにということで頑張っていただきたいと、私は要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"反対です。負担が、ほんとうに異常な値上げだと、私は思います。１.８倍とか、そんな異常な保険料の値上げになっていますので、今の区民の実態を考えたら、とても賛成するわけにはいかないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":158,"id":"exchange-047"},{"speaker":"若林委員","kind":"質問","question":"では第２９号議案を中心にお聞きしたいと思います。許認可は、もう既に区のほうでということで、既にこういう理容所、また美容所の衛生環境における行政を行っているということで、例えば、そういった理容所等への調査、衛生環境が保たれているかどうかという立ち入り調査というのか、どういう頻度で、どういう方が調査に行って、実態を把握されているのか。この辺をお聞きしたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"こちらの職員が、理容所に関しましては、おおむね２年に一度、区内の理容所すべてを回るような形で、最初に開設の届けを出したときと構造上の変更がないかとか、消毒等の器具が整えられているか。","voiceIndex":164,"id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"どうしてもここに触れながら、この条例について、お話を伺いたいと思うんですが、いわゆる理容所、美容所を含めた衛生環境の保持、向上について、現状、特段の事故等はないということで、今、ご報告がございましたけれども、この請願等のお話の中で、衛生を保持する、向上させるうえで、条例の中で、上下水道の設備を、というご要望がありますけれども、今回、品川区から出された理容業。","respondent":"工藤品川区保健所生活衛生課長","answer":"やり方としましては、例えば煮沸した水に一定時間つけるという方法ですとか、例えばエタノール水溶液という、いわゆる消毒名を指定して、それに１０分間浸す、次亜塩素酸ナトリウム、これもそうなんですけれども、こういったものに漬けて１０分間浸すということで、最終的に。","voiceIndex":166,"id":"exchange-049"},{"speaker":"若林委員","kind":"確認","question":"そうしますと、先ほどの話に戻りますけれども、十分な水、また排水、上下水道の設備を、やはり、こういう事業所に整備をすることを、しっかりと保健所のほうで確認をする、そして区民の衛生環境を守っていくということを条例の中でしっかりとうたっていくということが、理想的な条例ではないかなと、私は思いましたので、ここに入れるということについて、品川区の見解を伺いたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"上下水道の設置という部分で、委員お話がありましたように、設置をすれば、今まで以上に、いわゆる衛生面での向上というのは明らかなわけですけれども、今現在では、私どもも、そういった趣旨を持って区内の事業者の方にお願いというか、指導をして。","voiceIndex":168,"id":"exchange-050"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、これはもう理容所だけでいいですが、品川区内に幾つの営業所があって、その実態として、上下水道の設備のあるところが何件か。タンク式ということが出ましたが、タンク式でそれにかえているところが何件か。どちらもないところが何件か、ここら辺の実態を、ちょっと教えてください。","respondent":"工藤品川区保健所生活衛生課長","answer":"品川区内の理容所の実態ですけれども、昨年３月末で、２３０カ所あります。その中につきましては、すべて上下水道がつながっているです。","voiceIndex":170,"id":"exchange-051"},{"speaker":"若林委員","kind":"質問","question":"現在、上下水道がすべて完備しているということですので、条例の中に盛り込むということは、もう当たり前のことではないかと、今のご答弁を聞いて、私は感じましたけれども、もう１回、いかがでしょうか。","respondent":"工藤品川区保健所生活衛生課長","answer":"理容所を衛生的に保つという部分では重要だと考えていますけれども、いわゆるこれを義務化しますと、私どもとしましては、先ほど言いましたように、新しいビジネス、移動車を使った理容サービスなどがあり、それ以外の手法をもっても。","voiceIndex":172,"id":"exchange-052"},{"speaker":"若林委員","kind":"質問","question":"このＡ３版の資料の中で、その他があります。移動式というのは、こういうところで、別途衛生基準を定める。今、一緒くたにご答弁がありましたけれども、そこはしっかり分けて、固定的な、いわゆる町の事業所には上下水道、その他、これからさまざまな新しいビジネスがあるかもしれない、それを踏まえて、それに対してはこういう衛生基準というふうに縦分けて条例化するということは可能じゃないですか。","respondent":"木下健康福祉事業部長","answer":"これは、どういうことかというと、やはり地域のことは地域で、ということだと思いますけれども、今回、地方分権という一つの流れの中にあって、これまで東京都がやってきた基本的な対応の部分と、区の対応の部分が、この４月から急に変わるというのは。","voiceIndex":174,"id":"exchange-053"},{"speaker":"若林委員","kind":"質問","question":"だって、さっき、生活衛生課長の答弁で、これまでも指導してきました、実態もこうですというご報告があったわけですから、私が今言ったことが条例化されることによって、来月の４月１日をもって、都の条例から区の条例に変わったから、区民、また事業所に不利益がこうむることはないと、私は思って、今のような質問をさせていただきました。","respondent":"工藤品川区保健所生活衛生課長","answer":"そういった中で、今回、区のほうで条例が制定されるということで、またその条例に対しての規則、運用をつくっていくというのが、考え方の基本ですけれども、先ほど答弁しましたように、まずは私どものほうで。","voiceIndex":176,"id":"exchange-054"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"今回、こういう形で条例が提案をされていますので、そういう点では、今の今、ここの中に入れてほしいというのも、なかなか難しいかもしれないんですけれども、ということは、今の生活衛生課長の答弁からすると、そういう区民の思い、それから理容組合とかの団体からの要望を受けとめて、規則の中で上下水道をつけざるを得ないというような規則なり、指導なりしていかれるということで。","respondent":"工藤品川区保健所生活衛生課長","answer":"ただし、先ほど言いましたように、まず、東京都から品川区に衛生基準が移ってきた。そういった中で、私どもも、区民の方、事業者、その他もろもろの意見、いろいろと声を聞きまして、今後の衛生措置、基準について検討したいです。","voiceIndex":178,"id":"exchange-055"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところで、ぜひ規則の中でも、それから、区の姿勢としても、そういう方向で、固定した理容所については、上下水道を設置をするという原則というところを、ぜひ貫いていただきたいと思うんですけれども、改めて、そこのところだけ確認をお願いします。","respondent":"工藤品川区保健所生活衛生課長","answer":"現段階では、区のほうで、規則等に盛り込むという考えはございませんが、平成２１年１０月に、東京都から出ています衛生措置の設定についてという通知で、上下水道を原則とするというふうにうたわれていますので、当然、区のほうでも。","voiceIndex":180,"id":"exchange-056"},{"speaker":"石田（秀）委員","kind":"意見","question":"今、東京都からきた中で、それはしっかり移管を受けて、条例をつくっていく、それでいいと思っています。そういう形で、東京都も逃げているわけ、縛っているではない。それから、規則、運用については、これからしっかりといろいろ意見を聞いて、品川区に来たんだから、再度聞く立場にあるわけだから、そういうことも含めてやっていくべきであって、今、この時点で何かをやるべきではないと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":182,"id":"exchange-057"},{"speaker":"若林委員","kind":"質問・要望","question":"実は、質疑の内容によって、委員会の中で附帯決議を、ぜひつけさせていただきたいということで、文面を用意をしてまいりました。ちょっと段取り、仕切りがわからないのですが、それは出させていただいて、また皆様にしっかり見ていただいて、さまざまなご意見を、多分、あしたになるのかということを、まずお知らせをして、条例については賛成をいたします。","respondent":"山内委員長","answer":"条例の審議をするので、公明党は賛成ですね。条例についての採決をしなければならないので。は条例に関する採決を先に行います。","voiceIndex":186,"id":"exchange-058"},{"speaker":"若林委員","kind":"意見","question":"附帯決議を、まだ皆さんにご提示していませんので、これを、後ほどしっかり提示をさせていただいて、検討をしていただくと。そのうえで、条例についての賛成、反対は、また申し述べるということになります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":191,"id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、三つをやっているわけですから、その中で、これについては附帯決議をつけてほしい。そのかわり、これから出す附帯決議を、それがつかないとなったときには、反対するのか、賛成するのかというのは、附帯決議はここの中で皆さんで議論するわけですから、それがもしつかないのだったら、反対します、つくのだったら賛成しますと、そういう諮り方なんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-060"},{"speaker":"石田（秀）委員","kind":"意見","question":"これは条例に附帯決議をつけようという話であって、先ほども言いましたが、ずっと議論の中でも、条例に入れ込めという話からスタートして、今、条例はいいですよということになって、それで附帯決議をつけようということです。２点あることで、一つは、こういう附帯決議を条例につけようということは、原則、私の知っている限りでも、大体が全会一致でやってきたと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":205,"id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、条例の中に、できれば上下水道の設備を設けることを入れていただきたいと思いますけれども、もう今回出てしまっているという状況がありますので、ぜひ、この附帯決議をつけて、これからも、１００％すべて上下水道がつながっているという現状を、品川区の中で保っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-062"},{"speaker":"石田（秀）委員","kind":"質問","question":"今まで慣例の中で、例えば我々は会派政治もしているわけですから、会派の中で、例えば幹事長会をやるにしても、何にしても、そういう形の中でしっかり附帯決議をつけていくべきであろう。これをもし、附帯決議をつけるというようなことになると、一つの条例だけではなく、ほかの条例もさまざまいろいろ出てきたときに、こういうことが起きてくる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-063"},{"speaker":"若林委員","kind":"意見","question":"今回、地方分権、権限委譲の中で出てきた条例です。ですので、原則という意味では、今、私も含めて３会派、あと２会派の方もいらっしゃいますので、そこら辺も含めて、この附帯決議に対するご意見はしっかりと承って、あとは委員長が、この原則にのっとってどのように仕切ってくださるか、それはもう一任します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":209,"id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。これはこれで、こういうふうに出すのはいいんだけれども、結局、みんな一つ一つにお伺いを立てて、許可をもらってくるんですけれども、そういうのはどこかにまとめたり、相談に行ったら、ワンストップじゃないけど、どこかで全部わかるというところというか、相談に乗ってくれるという、一つで流れるような制度はできないんですかね。","respondent":"工藤品川区保健所生活衛生課長","answer":"国のほうでも、縦割りではないんですけれども、法律の管轄の部分が異なっているということで、現状は、このような形になっているところです。","voiceIndex":217,"id":"exchange-065"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"お願いだけしておきますが、例えば建築確認を出しますね。消防法は一応、必然的に流れるようになっているんですよね。まさに建築確認なんかそうで、だからどんどん民間に流れていくわけで、そういうことも含めて、ぜひお考えいただきたい。今、法律では保健所でやらなくちゃならないんだけれども、そこら辺のところも含めて、ぜひお考えいただきたいと、これは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":219,"id":"exchange-066"},{"speaker":"鶴委員","kind":"質問・要望","question":"第３１号議案の件ですけれども、基本的なところで、クリーニング、実際にお店の中、機械があって、工場を持っているところと、あとは代理店だけみたいな、受け取りと引渡しというか、それだけのところとあると思うんですけれども、その辺の件数の把握がもしあれば、ちょっとまず教えていただきたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"現在、品川区内、クリーニング所すべてで、昨年の３月末時点で４０６カ所ありまして、その内訳としまして、先ほど言いました一般の機器等を設置しているクリーニング所が１６４カ所、取次ぎ所が２３４カ所、リネンサプライが８カ所というのが内訳になっております。","voiceIndex":220,"id":"exchange-067"},{"speaker":"向委員","kind":"意見","question":"多分、都の条例をそのままの文言で、区として施行してみて、それからまた変えるときは変えましょうというお考えだと思うんですけれども、このあたりの年齢って、この先変わってくる余地はあるのかと思って、このあたりは各自の判断ということではなくて、最近、発育もいいと思うし、私自身も、もう３０歳ですけど、３０歳過ぎの年代でも、１０歳のときに、自分の父とか異性の家族と入っていたかというと。","respondent":"工藤品川区保健所生活衛生課長","answer":"ただ、言えることは、今回から品川区のほうでこのような基準等も持つようになりましたので、そういった部分も含めて、公衆浴場法ができましたのが昭和２０年代の法律の考え方がそのまま残っているものですので、そういった部分に関しましても。","voiceIndex":222,"id":"exchange-068"},{"speaker":"若林委員","kind":"質問","question":"条例直接ではなくて、参考までに、ということで。逆に、２年に１回でいいんですかという思いも含めながら。","respondent":"工藤品川区保健所生活衛生課長","answer":"公衆浴場ですけれども、旅館と同じなんですけれども、水質の管理が大変難しい施設でございまして、そういった中で、特に基準等はしっかりと守っていただかなければいけないという観点で、年に２度、私どものほうで必ず立ち入り、監視をしています。","voiceIndex":224,"id":"exchange-069"}]},{"id":"topic-06","title":"第３４号議案、品川区墓地等の構造設備および管理の基準等に関する条例","agenda":"第３４号議案、品川区墓地等の構造設備および管理の基準等に関する条例","exchanges":[{"speaker":"向委員","kind":"質問","question":"一つだけ教えてください。火葬炉のことなんですけれども、５基以上設けることとなっていて、今、区内で１日当たり、火葬は何件ぐらいあるのか。それから、１カ所当たり、１日平均、例えば１０件とか、１５件とか、わかれば教えていただけませんか。","respondent":"工藤品川区保健所生活衛生課長","answer":"区内の火葬場は、桐ヶ谷斎場が１カ所あります。炉が１２基設置されておりまして、大体１日の処理の最大が８４体という形の能力を有しております。","voiceIndex":240,"id":"exchange-070"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これをやりますよというと、近隣紛争が非常に多かったり何だりだから、保健所のあるところでやってくれというのに、建築確認の部分ぐらいまで、構造から何から相当突っ込んでいると思っている。それを二つ教えてもらいたい。この納骨堂の場合だったら、敷地内に建てるわけだから、そこら辺で、駐車場ってつけたのはいいんだけれども、そこら辺の考え方はどう理解しておけばいいんでしょうか。","respondent":"工藤品川区保健所生活衛生課長","answer":"しかし、考え方としましては、近隣に迷惑がかからないように、建物だけでなく駐車場の設置を求めると、そこの部分を規制しているというのが、今の現状の区の考え方です。","voiceIndex":242,"id":"exchange-071"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２％でも何でもいいんだけれども、運用でお願いしていると。こういうことを考えたときに、なまじっか、駐車場を設けること、ということ自体が、運用でお願いなんでしょう、ここは設けることにしたら、１台は１台になってしまうじゃないですか、１台でよければ、わからないけれども。何となく、納骨堂については、これから増えそうな気がしてならないので、ちょっと教えていただきたい。","respondent":"工藤品川区保健所生活衛生課長","answer":"説明会を開催しまして、近隣住民から意見を聞きまして協議をする、その前提がなければ、区として、申請を受け付けないという形になっておりますので、まずはそのような観点からしっかりと、駐車場がないことによる交通渋滞等、近隣迷惑にならない形という部分は、私ども。","voiceIndex":244,"id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"確認","question":"中延でも、そんなことでもめたわけです。最初はもめたけれども、結局、建築確認が下りて、建ってしまうわけでしょう。建築確認というのはあるわけだから、今、近隣の方と話したって、訴訟になったって、建築確認自体は下りちゃうわけではないですか。だから、そこら辺の点をもう一段ちょっと突っ込んで聞きたい。そこら辺、あらためて、二つのことをお聞きしたい。","respondent":"工藤品川区保健所生活衛生課長","answer":"駐車場に関しましては、私どもも、現状としては、基本的には、区内の中で継続して宗教活動が行われて、かつ、礼拝施設があるところが建つ要件になっておりますので、そういった意味では、納骨堂が建つ際には。","voiceIndex":246,"id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"墓地とか納骨堂というのが、先ほど、数年前に墓地の申請があったということなんですけれども、これは多分、厚生委員会にかかった二葉の住宅地に建てられた墓地なのではないかと思うんですけれども、この十数年とかいう形で、墓地とか納骨堂の建設というのが、品川区でどの程度あったのか、まず実態をちょっと教えていただきたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"その前の状況ですけれども、平成２０年に、南大井二丁目にあります大森立正墓苑という部分の許可がございまして、それよりさかのぼりますと、平成１２年７月に、南品川四丁目にあります天龍寺墓苑ということで、平成１０年以降は３件という形になっております。","voiceIndex":248,"id":"exchange-074"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"そういう中で今回、こういう条例ができたんだと思うんですけれども、その中で、具体的に第７条の墓地の構造設備というところでの(1)が、墓地の区域と隣接する土地との境界には、障壁または密植した低木の垣根を設けることというのと、(6)のところで、墓地の区域と隣接する土地との境界には、規則で定める基準に従い緩衝帯を設けることということで、(1)と(6)に書かれているんですけれども。","respondent":"工藤品川区保健所生活衛生課長","answer":"新たに加えています６号の緩衝帯のほうですけれども、緩衝帯というのは、墓地の面積から墓石を設けるときに、内側１ｍは必ず下がってほしいということでございまして、墓地の中の周辺に必ず緩衝帯を設けるということでありまして。","voiceIndex":250,"id":"exchange-075"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それともう一つは、説明会の開催というところで、住民の範囲を広げたということで、これも規則で定める住民ということなんですが、この規則で定める住民を広げた範囲というのは、どの程度までを考えられているのかも聞かせていただきたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"それとあと、住民の範囲ですけれども、こちらのほうの規則で定める住民の範囲といいますのが、新規の墓地に関しましては、従来の隣接住民等というところからプラスアルファしまして、周辺３０ｍ以上の方に関しまして説明会を義務づけ、協議があればそれに応じまして。","voiceIndex":252,"id":"exchange-076"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"住民が３０ｍということで拡大していただいたのはいいと思うんですけれども、これは要望で、周りから墓地が気にならないというぐらいの間を設けるとなったら、ちょっと大きめの木が育つという程度の緩衝帯というのが必要じゃないかと思いますので、それはぜひ広げていただけるようにご検討いただきたいと要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":254,"id":"exchange-077"},{"speaker":"鶴委員","kind":"質問","question":"第３条の１、２、３号、それぞれ経営主体が明示されておりまして、地方公共団体、宗教法人、公益社団法人及び公益財団法人とあります。それぞれの墓地、経営している数と、そこまではどうかわかりませんけれども、お墓の基数ないし区画数でもいいんですけれども、そういうのがわかれば教えていただければと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"それとあと区内における墳墓の数ですけれども、これは以前、昭和２０年代、３０年代の部分につきましては少しデータが欠けているものがあるんですけれども、面積で割り出した部分もあるんですけれども、推定で申し上げますと、区内に２万４,８００の墓地の墳墓と。","voiceIndex":255,"id":"exchange-078"},{"speaker":"鶴委員","kind":"質問","question":"今、１１７法人とお答えいただきましたけれども、これはおそらく全部まとめてという感じだと思うんですが、宗教法人と、それから３号で言うところの公益社団法人、公益財団法人、もし別がわかればそれぞれ教えてください。","respondent":"工藤品川区保健所生活衛生課長","answer":"いずれの法人もこちらの２号に該当している宗教法人法に定められる宗教法人ということで、３号該当というのは区内にはございません。","voiceIndex":257,"id":"exchange-079"}]},{"id":"topic-07","title":"平成２４年請願第１号、「こころの健康を守り推進する基本法（仮称）」の法制化を求める意見書の提出に関する請願","agenda":"平成２４年請願第１号、「こころの健康を守り推進する基本法（仮称）」の法制化を求める意見書の提出に関する請願","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"請願をいただいてから我々も再度勉強したという感じなんですが、それまでよくわからなかった部分もありましたが、全会派が署名をしている。内容を勉強させていただいて、他区なんかも、もう杉並区なんかは意見書を出しているという状況もあるということです。もう結論みたいな形ですけれども、６会派みんな署名しているので、我々も協力をしていけるところはしっかり協力をしていきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":283,"id":"exchange-080"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私も、精神の問題というのはますます深刻な状況になっていますし、ここに書かれているとおりで、充実させることが早急に求められていると思いますので、今、言われたような形で、ぜひ意見書を出していきたいと思うんですけれども、すでに都内で意見書を出されているところがどれくらいあるのか、把握されていたらお聞かせいただきたいと思います。","respondent":"福島品川区保健所荏原保健センター所長","answer":"東京都内では、杉並区、葛飾区、調布市、三鷹市、立川市、町田市、日の出町の７つの地方議会で意見書が採択されたとのことです。","voiceIndex":284,"id":"exchange-081"},{"speaker":"若林委員","kind":"意見","question":"意見書をこのタイミングでしっかりと出してまいりたいと思います。請願という形で区民の方からお声が上がってということですが、議会として積極的にこれは出していくべきだろうと率直に思います。品川区議会においても、ぜひ皆様のお役に立てるような意見書をしっかりと出していくべきだろうと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":286,"id":"exchange-082"},{"speaker":"石田（秀）委員","kind":"意見","question":"結論を今日出してほしいと思います。態度は採択。しっかり意見書をつけて、我々も行っていくということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":289,"id":"exchange-083"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"今日、結論を出すということで、採択で、そしてぜひ意見書を出すということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":293,"id":"exchange-084"}]},{"id":"topic-08","title":"平成２４年請願第２号、理容所及び美容所の衛生水準向上のための条例策定についての請願","agenda":"平成２４年請願第２号、理容所及び美容所の衛生水準向上のための条例策定についての請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"１つだけ先にお聞きしたいので教えてください。理容の方々は自主的に指導なり調査なりをやっていると思うんですけれども、そこら辺の連携は今、どういうふうにしていらっしゃるのか、そこだけ教えてください。","respondent":"工藤品川区保健所生活衛生課長","answer":"理容所の方に関する管理的な部分をどうされているかですけれども、自主管理、自主点検の勧めということで、組合を通じまして、いわゆる自主管理点検表というものを平成１５年度からお願いしています。","voiceIndex":301,"id":"exchange-085"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、私の聞き方が悪かった。それはわかっているんですが、区として２年に１回行かれると言っていましたよね。それとその点検に行かれる方々とダブるわけですね。そこら辺のお互いにやってきたものの精査とか連携というのは、どういうふうにされているんでしょうか。","respondent":"工藤品川区保健所生活衛生課長","answer":"私どもも点検立ち入りの場面で、自主管理点検表という部分に沿って、十分な衛生措置等がされているかという部分を、この点検表に基づいて、私どものほうも点検項目として一つずつ確認させていただいているというのが現状です。","voiceIndex":303,"id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本当に理容組合の方々は、前会長のときから我々も非常にその点を一生懸命やっているんだと。自主点検も何もみんな一生懸命やろうというのでやっていると。もう長年やっているわけですから、それはそれで少し運用していただいて、私としてはしっかりそういうところはもう一度検証していただいて、いい方向に向かってほしいなと思っていますので、それは私の意見として述べておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":305,"id":"exchange-087"},{"speaker":"若林委員","kind":"質問","question":"自主点検されていましたね。これは大体２３０件ぐらい理容所があるということですが、このうち自主点検されている事業者はどのぐらいあるんでしょうか。","respondent":"工藤品川区保健所生活衛生課長","answer":"ただ、実態としまして、地区によってこの取り組みというのが温度差があると聞いておりまして、どれぐらいの組合員の方がこれをやっていただいているかという部分の詳細という部分は、ちょっと私どもつかんでいないというのが現状です。","voiceIndex":306,"id":"exchange-088"},{"speaker":"若林委員","kind":"確認","question":"それは４月１日というよりも、早急にそれは実態を把握されるということでお願いをして、今、組合という話ですが、２３０のうち組合に入っている方と、当然どこでもそうですけれども、入っていない方がいらっしゃって、そこは自主点検をされていないということで確認というんですか、ご答弁の内容からするとそうなのかと、そこだけちょっと確認を。","respondent":"工藤品川区保健所生活衛生課長","answer":"この自主点検に関しましては、組合を通じて以前、お願いしてあったものですので、組合に未加入の方に関しましては、特に投げかけというのはやっていないというのが現状です。","voiceIndex":308,"id":"exchange-089"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２３０店舗あるうちで、組合に入られているお店というのはどれぐらいあるのか、つかんでいたら教えていただきたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"申しわけございません。今、手元に資料がございませんので、後ほど調べまして回答します。","voiceIndex":310,"id":"exchange-090"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"その部分の強化も、もう少し自分たちの評価の強化もと言ったと思うんだけれども、後で質問したら、どれぐらいあってどういうふうにしてくれているという連携も本当にとれていないから起こっているんだと思うんだね。そういうことを含めて、この請願については、条例上、それはもう乗らないわけだけれども、趣旨は非常によくわかるので、自民党は趣旨採択でお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":322,"id":"exchange-091"},{"speaker":"若林委員","kind":"提案","question":"先ほどの条例の質疑の中でほぼ言わせていただきました。既に条例は委員会としては可決いたしましたので、しっかりと今後の運用、運営の部分も含めて、附帯決議の提案をさせていただきましたけれども、しっかりとこの請願の思いを受けて、品川区にはしっかりとした衛生環境向上のための取り組みを具体的に進めていただきたいということで、趣旨採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":323,"id":"exchange-092"},{"speaker":"向委員","kind":"質問・要望","question":"先ほど、条例が４月１日から施行されるということで、それと同じ考えなんですが、衛生面については、我が会派でも、きちんと担保していただきたい。ということで、趣旨採択で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":324,"id":"exchange-093"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"共産党としても趣旨採択ということでお願いしたいと思います。品川区に対しては、しっかりとこの面でも、具体的なところでしっかりと上下水道のついた理容所というところで、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":326,"id":"exchange-094"}]},{"id":"topic-09","title":"平成２４年請願第５号、介護保険料の値上げ中止と国に対し国庫負担引き上げを求める請願","agenda":"平成２４年請願第５号、介護保険料の値上げ中止と国に対し国庫負担引き上げを求める請願","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"住民税非課税者の介護保険料の値上げ中止をしてくださいということなんですけれども、おおよそ私が計算したところですと、１億８,０００万円ぐらいあれば、住民税非課税者の保険料値上げを抑えられるということなんですけれども、こういう考え方でいいのかということが１点と、それからあとは住民税非課税の方が基準額、基準額も住民税非課税なんですけれども。","respondent":"原高齢者福祉課長","answer":"そうはいっても収入はそれぞれ違うわけでございまして、そういったところに対して保険料率あるいは多段階化、こういったところで対応しているというところでございまして、応分の負担をしていただくという考え方のもとにいるところです。","voiceIndex":334,"id":"exchange-095"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この第５段階というのは、本人は非課税で、同一世帯の中にわずかでも課税というところであれば第５段階になってしまって、５万６,４００円ですか。そういう点では、今回の第五期の計画のこれを見ましても、大崎地区というのは全くないですし、ほかの地区も大体１カ所ずつという形なので、そういうバランスという点についてはどう考えられているかということと、あわせてお聞かせいただきたいと思います。","respondent":"原高齢者福祉課長","answer":"そういう中で、どうしても特別養護老人ホームに入らなくてはいけないといった方も実際増えているというところは、認識しています。そういった中で、この間、先ほども八潮南、それから平塚橋会館跡、杜松小学校跡地ということで、区のほうは整備をしてきたです。","voiceIndex":338,"id":"exchange-096"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今までは民間の土地も探しながら特別養護老人ホームをつくっていくということの答弁をされていたわけですけれども、そういう考え方は今でも変わらないのか。そして、待機者は今までは大体６００名ぐらいだったと思うんですけれども、まだ２月末になっていないですけれども、今の状況でどれくらい申し込みがあるかというのがわかったら、その数字も教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"土地というところが、特別養護老人ホームの場合は大きな土地ということでまずはとらえております。そういった意味では、土地の問題であるとか、それから財政的な状況、あるいはこういったところの保険料への影響等々も含めて、条件が整えばというところで考えているところです。","voiceIndex":340,"id":"exchange-097"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"有料老人ホームに入れる人はお金のある一部の人、そういう点では、やはりだれもが入れる特別養護老人ホームこそ、同じ保険料であれば、ぜひともつくっていただきたいというのが区民の願いですし、私もそういうふうに思うわけですけれども、そういうところではいかがでしょうか。","respondent":"原高齢者福祉課長","answer":"そういった意味で、トータルのバランスの中で、また高齢者の増加、特別養護老人ホームの入所等々を踏まえつつ、検討してまいるというところで考えているところです。","voiceIndex":342,"id":"exchange-098"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回の平塚橋会館に続く特別養護老人ホームの増設というところで、ぜひ計画を立てて増設をしていただきたいということを強く要望したいと思います。それともう一つ、老人保健施設なんですが、区がもう１カ所必要ということを言われてからもう何年もたつと思うんですね。","respondent":"原高齢者福祉課長","answer":"区のほうでも１カ所をぜひということで、具体化に向けてこれからも進めてまいりたいと考えているところです。","voiceIndex":344,"id":"exchange-099"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ずっとそういう答弁のままなんですけれども、具体的に１カ所というのは、まだ全く見通しはないんでしょうか。それともこういう見通しという方向もありつつ進められているという、そこら辺のところをもう一歩踏み込んだご答弁をいただけたらと思うんですが。","respondent":"原高齢者福祉課長","answer":"現在のところで具体化というところで、こういったところがあるんじゃないかというところまでは至ってはございません。方向として、老人保健施設については、必要性というところは区は判断しておりますので、今後もそこに向けて進めていきたいと思っているところです。","voiceIndex":346,"id":"exchange-100"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１カ所必要ということで、この答弁は前からお聞きしているところですけれども、それがなかなか前に進まない。進めるための課題という点では、どこをどうすれば進められるのか。どこをどうして進めていこうと考えているのか。","respondent":"原高齢者福祉課長","answer":"１つは土地というところが現実的な問題として出てまいります。そういった意味で特別養護老人ホーム、あるいはさまざまな条件の中で、どういったところをとらえていくかといった中で、今のところでは具体的なところは出ていないです。","voiceIndex":348,"id":"exchange-101"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"私も平塚橋会館というのが出てきて、こういうところもあるのかというのも思ったわけなんですけれども、そういう点では、区内を見渡せばそういう土地は出てくるところが、本会議の提案もありましたけれども、あるのではないかと思うんですけれども、ぜひそういうところで、ずっと言われ続けているので、なるべく近いうちに具体化をして、ぜひ増設に向けて取り組んでいただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":350,"id":"exchange-102"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"介護保険料を値上げしないでというのはさっきからずっと議論していたから、これはできないことだと思っていますし、本当に相互扶助で応分の負担をしていただくというのはもちろんあるわけでありまして、１番と２番は、よくよく考えると、介護保険料を値上げしないでというのと、特別養護老人ホームをつくったら介護保険料が上がるわけで、相反するものが出ているかなと思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":360,"id":"exchange-103"},{"speaker":"若林委員","kind":"意見","question":"ただ介護保険料、社会保障と税の一体改革の話に本当に、請願の第５号も絡みますけれども、国庫負担の引き上げとかになりますし、しっかりと社会保障の全体像の中で介護保険も医療も年金もというところの、しっかり議論を進めなければいけないという思いですので、この件については不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":361,"id":"exchange-104"},{"speaker":"向委員","kind":"意見","question":"我が会派でも、まず介護保険料値上げと特別養護老人ホームの増設に関しては矛盾しているだろうという意見が出たんですが、そういったことと、あと本日も本当に重ねて議論をしましたけれども、区としての介護保険料の考え方、今後についてもきちんと精査をして対応してくださるということも重々理解しておりますし、また特別養護老人ホームについても。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":362,"id":"exchange-105"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"採択をしていきたいと思います。これから高齢化率が、まだまだ品川区の骨子案の中でも、少なくとも平成４２年まではずっと上がり続けます。だからこそ区議会を挙げて特別養護老人ホームは必要だというところに、区議会でもなってきているということをぜひ受けとめていただいて、平塚橋会館までつくるという方向を出されたことは評価するものですけれども、さらなる増設に向けて取り組みを進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":364,"id":"exchange-106"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"結論を出す。採択でお願いします。先ほども言いましたように、介護保険料は国の負担割合を引き上げてくださいというのは、ずっと区も市長会でも言っているということなんですけれども、私は区のほうからも強力にこれは求めていただきたい。そして、この欠陥の介護保険料の設定そのものを変えていくことが必要だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":371,"id":"exchange-107"}]},{"id":"topic-10","title":"平成２４年陳情第２号 品川区国民健康保険被保険者証の裏面に臓器提供の意思表示欄の掲載を外すことを求める陳情","agenda":"平成２４年陳情第２号 品川区国民健康保険被保険者証の裏面に臓器提供の意思表示欄の掲載を外すことを求める陳情","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど、啓発や知識の普及という中で、この保険証の裏側にこれを印刷して出すということもあるんだということだったんですが、これ以外のところで、品川区として臓器移植の問題で、啓発や知識の普及というところを、どんな形でされているのかもお聞かせいただきたいと思います。","respondent":"本城国保医療年金課長","answer":"私どもの所管といたしましては、国民健康保険法の運営の中での啓発ということになってきますので、先ほどの被保険者証の裏面に記載事項を設けた際に、保険証のＰＲと一緒にこういう趣旨でということでその旨をお伝えしたり、あと保険証の発行後に。","voiceIndex":378,"id":"exchange-108"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ただ、こういうことの記載がされていますというだけだと、やっぱりそれでは臓器移植に対しての考え方を一人一人が考えるというところには、なかなか結びつかないんじゃないかと思うんですね。そういう自治体というのは、こういうふうに裏側にすぐに印刷してそのまま出すということではない対応をしているという自治体はどれぐらいあるのか、つかんでいたら教えていただきたいと思います。","respondent":"本城国保医療年金課長","answer":"そんな中で、私どもとしては、与えられた役割について、保険証の裏面に記載するという中で、国が示されているいろいろな考えの中で、国の方針に示されているところに則して対応するのが、保険者としての役割ではないかと考えて。","voiceIndex":380,"id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっと教えてください。この陳情の中で、実際にはドナーが移植の際に痛がる生体反応を示す場合も多いと書いてあるんだけれども、こういうことってどういう意味なのか、わかれば教えてほしい。","respondent":"本城国保医療年金課長","answer":"医学的な見地の専門的なことは私の持ち分からはあれなんですが、ただ、参議院で趣旨が説明されたときも、それに関連して若干趣旨説明があったようで、簡単に読み上げしますと、臓器を摘出する際に全身麻酔をかけるのではないかというご意見がありますということで触れられて。","voiceIndex":382,"id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうすると、我々の理解として、皆さんからいろいろこういう話、命の尊厳みたいなことで大変なことだと思いますが、聞かれたときには、そういうことではないということで、そういうことですね。そういうふうに思っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":384,"id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"質問","question":"我が会派は不採択でお願いします。別に私はそれを、今、免許証もそういうふうに変わったけれども、強制をしているわけではないと思っています。ご希望があればということなので、そういう待っていらっしゃる方のことも考えれば、やっぱり我々はそれの中の意思表示もしていってもいいのではないかと私は思っておりますので、この件については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":393,"id":"exchange-112"},{"speaker":"若林委員","kind":"意見","question":"だからこそ、こういう目に触れる形でこういうものを印刷物にして、それを見て多くの国民がしっかり自分自身で考えていく、家族のことを考えていくという機会にしましょうねという法の趣旨だと思いますので、外すとか、別な形でというのは、今の段階では私は違うと思いますので、不採択ということで結構かと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":394,"id":"exchange-113"},{"speaker":"向委員","kind":"質問・要望","question":"ただ会派でもちょっと意見が出ていたのは、できるだけ啓発活動をきちんとしていただきたいということで、特に高齢者の方とか、そこにそういうふうに書いてあれば、素直にご自身でぽんと書いてしまうという可能性もあると思うんですが、このあたりは家族ともしっかり話し合って、本当に大切な自分の体をだれに提供するかとか、そういうことなので、引き続き品川区の国民健康保険証ということでもありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":395,"id":"exchange-114"},{"speaker":"鈴木（博）委員","kind":"意見","question":"臓器を待ち望んでいて闘病生活をしていて、途中で力尽きて亡くなった方がたくさんいらっしゃいます。だから臓器移植というのは、要するにそれを待っていて、その人を助けるというのは非常に意味があることなので、先ほどお話があったみたいに、まだ一部で意見が盛り上がっていないというのは事実なんです。ということで、不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":396,"id":"exchange-115"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"私は採択でお願いしたいと思います。そしてそのときにしっかりと家族とも話し合い、そして決めていくという形が望ましいのではないかと思いますので、採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":397,"id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3316#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":109228,"voices":404}}]);
